insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','atos',1,1,'Fiz o primeiro tratado, ó Teófilo, acerca de tudo que Jesus começou, não só a fazer, mas a ensinar,'),
('acf','atos',1,2,'Até ao dia em que foi recebido em cima, depois de ter dado mandamentos, pelo Espírito Santo, aos apóstolos que escolhera;'),
('acf','atos',1,3,'Aos quais também, depois de ter padecido, se apresentou vivo, com muitas e infalíveis provas, sendo visto por eles por espaço de quarenta dias, e falando das coisas concernentes ao reino de Deus.'),
('acf','atos',1,4,'E, estando com eles, determinou-lhes que não se ausentassem de Jerusalém, mas que esperassem a promessa do Pai, que, disse ele, de mim ouvistes.'),
('acf','atos',1,5,'Porque, na verdade, João batizou com água, mas vós sereis batizados com o Espírito Santo, não muito depois destes dias.'),
('acf','atos',1,6,'Aqueles, pois, que se haviam reunido perguntaram-lhe, dizendo: Senhor, restaurarás tu neste tempo o reino a Israel?'),
('acf','atos',1,7,'E disse-lhes: Não vos pertence saber os tempos ou as estações que o Pai estabeleceu pelo seu próprio poder.'),
('acf','atos',1,8,'Mas recebereis a virtude do Espírito Santo, que há de vir sobre vós; e ser-me-eis testemunhas, tanto em Jerusalém como em toda a Judéia e Samaria, e até aos confins da terra.'),
('acf','atos',1,9,'E, quando dizia isto, vendo-o eles, foi elevado às alturas, e uma nuvem o recebeu, ocultando-o a seus olhos.'),
('acf','atos',1,10,'E, estando com os olhos fitos no céu, enquanto ele subia, eis que junto deles se puseram dois homens vestidos de branco.'),
('acf','atos',1,11,'Os quais lhes disseram: Homens galileus, por que estais olhando para o céu? Esse Jesus, que dentre vós foi recebido em cima no céu, há de vir assim como para o céu o vistes ir.'),
('acf','atos',1,12,'Então voltaram para Jerusalém, do monte chamado das Oliveiras, o qual está perto de Jerusalém, à distância do caminho de um sábado.'),
('acf','atos',1,13,'E, entrando, subiram ao cenáculo, onde habitavam Pedro e Tiago, João e André, Filipe e Tomé, Bartolomeu e Mateus, Tiago, filho de Alfeu, Simão, o Zelote, e Judas, irmào de Tiago.'),
('acf','atos',1,14,'Todos estes perseveravam unanimemente em oração e súplicas, com as mulheres, e Maria mãe de Jesus, e com seus irmãos.'),
('acf','atos',1,15,'E naqueles dias, levantando-se Pedro no meio dos discípulos (ora a multidão junta era de quase cento e vinte pessoas) disse:'),
('acf','atos',1,16,'Homens irmãos, convinha que se cumprisse a Escritura que o Espírito Santo predisse pela boca de Davi, acerca de Judas, que foi o guia daqueles que prenderam a Jesus;'),
('acf','atos',1,17,'Porque foi contado conosco e alcançou sorte neste ministério.'),
('acf','atos',1,18,'Ora, este adquiriu um campo com o galardão da iniqüidade; e, precipitando-se, rebentou pelo meio, e todas as suas entranhas se derramaram.'),
('acf','atos',1,19,'E foi notório a todos os que habitam em Jerusalém; de maneira que na sua própria língua esse campo se chama Aceldama, isto é, Campo de Sangue.'),
('acf','atos',1,20,'Porque no livro dos Salmos está escrito: Fique deserta a sua habitação, E não haja quem nela habite, e: Tome outro o seu bispado.'),
('acf','atos',1,21,'É necessário, pois, que, dos homens que conviveram conosco todo o tempo em que o Senhor Jesus entrou e saiu dentre nós,'),
('acf','atos',1,22,'Começando desde o batismo de João até ao dia em que de entre nós foi recebido em cima, um deles se faça conosco testemunha da sua ressurreição.'),
('acf','atos',1,23,'E apresentaram dois: José, chamado Barsabás, que tinha por sobrenome o Justo, e Matias.'),
('acf','atos',1,24,'E, orando, disseram: Tu, Senhor, conhecedor dos corações de todos, mostra qual destes dois tens escolhido,'),
('acf','atos',1,25,'Para que tome parte neste ministério e apostolado, de que Judas se desviou, para ir para o seu próprio lugar.'),
('acf','atos',1,26,'E, lançando-lhes sortes, caiu a sorte sobre Matias. E por voto comum foi contado com os onze apóstolos.'),
('acf','atos',2,1,'E, cumprindo-se o dia de Pentecostes, estavam todos concordemente no mesmo lugar;'),
('acf','atos',2,2,'E de repente veio do céu um som, como de um vento veemente e impetuoso, e encheu toda a casa em que estavam assentados.'),
('acf','atos',2,3,'E foram vistas por eles línguas repartidas, como que de fogo, as quais pousaram sobre cada um deles.'),
('acf','atos',2,4,'E todos foram cheios do Espírito Santo, e começaram a falar noutras línguas, conforme o Espírito Santo lhes concedia que falassem.'),
('acf','atos',2,5,'E em Jerusalém estavam habitando judeus, homens religiosos, de todas as nações que estão debaixo do céu.'),
('acf','atos',2,6,'E, quando aquele som ocorreu, ajuntou-se uma multidão, e estava confusa, porque cada um os ouvia falar na sua própria língua.'),
('acf','atos',2,7,'E todos pasmavam e se maravilhavam, dizendo uns aos outros: Pois quê! não são galileus todos esses homens que estão falando?'),
('acf','atos',2,8,'Como, pois, os ouvimos, cada um, na nossa própria língua em que somos nascidos?'),
('acf','atos',2,9,'Partos e medos, elamitas e os que habitam na Mesopotâmia, Judéia, Capadócia, Ponto e Asia,'),
('acf','atos',2,10,'E Frígia e Panfília, Egito e partes da Líbia, junto a Cirene, e forasteiros romanos, tanto judeus como prosélitos,'),
('acf','atos',2,11,'Cretenses e árabes, todos nós temos ouvido em nossas próprias línguas falar das grandezas de Deus.'),
('acf','atos',2,12,'E todos se maravilhavam e estavam suspensos, dizendo uns para os outros: Que quer isto dizer?'),
('acf','atos',2,13,'E outros, zombando, diziam: Estão cheios de mosto.'),
('acf','atos',2,14,'Pedro, porém, pondo-se em pé com os onze, levantou a sua voz, e disse-lhes: Homens judeus, e todos os que habitais em Jerusalém, seja-vos isto notório, e escutai as minhas palavras.'),
('acf','atos',2,15,'Estes homens não estão embriagados, como vós pensais, sendo a terceira hora do dia.'),
('acf','atos',2,16,'Mas isto é o que foi dito pelo profeta Joel:'),
('acf','atos',2,17,'E nos últimos dias acontecerá, diz Deus, Que do meu Espírito derramarei sobre toda a carne; E os vossos filhos e as vossas filhas profetizarão, Os vossos jovens terão visões, E os vossos velhos sonharão sonhos;'),
('acf','atos',2,18,'E também do meu Espírito derramarei sobre os meus servos e as minhas servas naqueles dias, e profetizarão;'),
('acf','atos',2,19,'E farei aparecer prodígios em cima, no céu; E sinais em baixo na terra, Sangue, fogo e vapor de fumo.'),
('acf','atos',2,20,'O sol se converterá em trevas, E a lua em sangue, Antes de chegar o grande e glorioso dia do Senhor;'),
('acf','atos',2,21,'E acontecerá que todo aquele que invocar o nome do Senhor será salvo.'),
('acf','atos',2,22,'Homens israelitas, escutai estas palavras: A Jesus Nazareno, homem aprovado por Deus entre vós com maravilhas, prodígios e sinais, que Deus por ele fez no meio de vós, como vós mesmos bem sabeis;'),
('acf','atos',2,23,'A este que vos foi entregue pelo determinado conselho e presciência de Deus, prendestes, crucificastes e matastes pelas mãos de injustos;'),
('acf','atos',2,24,'Ao qual Deus ressuscitou, soltas as ânsias da morte, pois não era possível que fosse retido por ela;'),
('acf','atos',2,25,'Porque dele disse Davi: Sempre via diante de mim o Senhor, Porque está à minha direita, para que eu não seja comovido;'),
('acf','atos',2,26,'Por isso se alegrou o meu coração, e a minha língua exultou; E ainda a minha carne há de repousar em esperança;'),
('acf','atos',2,27,'Pois não deixarás a minha alma no inferno, Nem permitirás que o teu Santo veja a corrupção;'),
('acf','atos',2,28,'Fizeste-me conhecidos os caminhos da vida; Com a tua face me encherás de júbilo.'),
('acf','atos',2,29,'Homens irmãos, seja-me lícito dizer-vos livremente acerca do patriarca Davi, que ele morreu e foi sepultado, e entre nós está até hoje a sua sepultura.'),
('acf','atos',2,30,'Sendo, pois, ele profeta, e sabendo que Deus lhe havia prometido com juramento que do fruto de seus lombos, segundo a carne, levantaria o Cristo, para o assentar sobre o seu trono,'),
('acf','atos',2,31,'Nesta previsão, disse da ressurreição de Cristo, que a sua alma não foi deixada no inferno, nem a sua carne viu a corrupção.'),
('acf','atos',2,32,'Deus ressuscitou a este Jesus, do que todos nós somos testemunhas.'),
('acf','atos',2,33,'De sorte que, exaltado pela destra de Deus, e tendo recebido do Pai a promessa do Espírito Santo, derramou isto que vós agora vedes e ouvis.'),
('acf','atos',2,34,'Porque Davi não subiu aos céus, mas ele próprio diz:Disse o Senhor ao meu Senhor:Assenta-te à minha direita,'),
('acf','atos',2,35,'Até que ponha os teus inimigos por escabelo de teus pés.'),
('acf','atos',2,36,'Saiba pois com certeza toda a casa de Israel que a esse Jesus, a quem vós crucificastes, Deus o fez Senhor e Cristo.'),
('acf','atos',2,37,'E, ouvindo eles isto, compungiram-se em seu coração, e perguntaram a Pedro e aos demais apóstolos: Que faremos, homens irmãos?'),
('acf','atos',2,38,'E disse-lhes Pedro: Arrependei-vos, e cada um de vós seja batizado em nome de Jesus Cristo, para perdão dos pecados; e recebereis o dom do Espírito Santo;'),
('acf','atos',2,39,'Porque a promessa vos diz respeito a vós, a vossos filhos, e a todos os que estão longe, a tantos quantos Deus nosso Senhor chamar.'),
('acf','atos',2,40,'E com muitas outras palavras isto testificava, e os exortava, dizendo: Salvai-vos desta geração perversa.'),
('acf','atos',2,41,'De sorte que foram batizados os que de bom grado receberam a sua palavra; e naquele dia agregaram-se quase três mil almas,'),
('acf','atos',2,42,'E perseveravam na doutrina dos apóstolos, e na comunhão, e no partir do pão, e nas orações.'),
('acf','atos',2,43,'E em toda a alma havia temor, e muitas maravilhas e sinais se faziam pelos apóstolos.'),
('acf','atos',2,44,'E todos os que criam estavam juntos, e tinham tudo em comum.'),
('acf','atos',2,45,'E vendiam suas propriedades e bens, e repartiam com todos, segundo cada um havia de mister.'),
('acf','atos',2,46,'E, perseverando unânimes todos os dias no templo, e partindo o pão em casa, comiam juntos com alegria e singeleza de coração,'),
('acf','atos',2,47,'Louvando a Deus, e caindo na graça de todo o povo. E todos os dias acrescentava o Senhor à igreja aqueles que se haviam de salvar.'),
('acf','atos',3,1,'E Pedro e João subiam juntos ao templo à hora da oração, a nona.'),
('acf','atos',3,2,'E era trazido um homem que desde o ventre de sua mãe era coxo, o qual todos os dias punham à porta do templo, chamada Formosa, para pedir esmola aos que entravam.'),
('acf','atos',3,3,'O qual, vendo a Pedro e a João que iam entrando no templo, pediu que lhe dessem uma esmola.'),
('acf','atos',3,4,'E Pedro, com João, fitando os olhos nele, disse: Olha para nós.'),
('acf','atos',3,5,'E olhou para eles, esperando receber deles alguma coisa.'),
('acf','atos',3,6,'E disse Pedro: Não tenho prata nem ouro; mas o que tenho isso te dou. Em nome de Jesus Cristo, o Nazareno, levanta-te e anda.'),
('acf','atos',3,7,'E, tomando-o pela mão direita, o levantou, e logo os seus pés e artelhos se firmaram.'),
('acf','atos',3,8,'E, saltando ele, pôs-se em pé, e andou, e entrou com eles no templo, andando, e saltando, e louvando a Deus.'),
('acf','atos',3,9,'E todo o povo o viu andar e louvar a Deus;'),
('acf','atos',3,10,'E conheciam-no, pois era ele o que se assentava a pedir esmola à porta Formosa do templo; e ficaram cheios de pasmo e assombro, pelo que lhe acontecera.'),
('acf','atos',3,11,'E, apegando-se o coxo, que fora curado, a Pedro e João, todo o povo correu atônito para junto deles, ao alpendre chamado de Salomão.'),
('acf','atos',3,12,'E quando Pedro viu isto, disse ao povo: Homens israelitas, por que vos maravilhais disto? Ou, por que olhais tanto para nós, como se por nossa própria virtude ou santidade fizéssemos andar este homem?'),
('acf','atos',3,13,'O Deus de Abraão, de Isaque e de Jacó, o Deus de nossos pais, glorificou a seu filho Jesus, a quem vós entregastes e perante a face de Pilatos negastes, tendo ele determinado que fosse solto.'),
('acf','atos',3,14,'Mas vós negastes o Santo e o Justo, e pedistes que se vos desse um homem homicida.'),
('acf','atos',3,15,'E matastes o Príncipe da vida, ao qual Deus ressuscitou dentre os mortos, do que nós somos testemunhas.'),
('acf','atos',3,16,'E pela fé no seu nome fez o seu nome fortalecer a este que vedes e conheceis; sim, a fé que vem por ele, deu a este, na presença de todos vós, esta perfeita saúde.'),
('acf','atos',3,17,'E agora, irmãos, eu sei que o fizestes por ignorância, como também os vossos príncipes.'),
('acf','atos',3,18,'Mas Deus assim cumpriu o que já dantes pela boca de todos os seus profetas havia anunciado; que o Cristo havia de padecer.'),
('acf','atos',3,19,'Arrependei-vos, pois, e convertei-vos, para que sejam apagados os vossos pecados, e venham assim os tempos do refrigério pela presença do Senhor,'),
('acf','atos',3,20,'E envie ele a Jesus Cristo, que já dantes vos foi pregado.'),
('acf','atos',3,21,'O qual convém que o céu contenha até aos tempos da restauração de tudo, dos quais Deus falou pela boca de todos os seus santos profetas, desde o princípio.'),
('acf','atos',3,22,'Porque Moisés disse aos pais: O Senhor vosso Deus levantará de entre vossos irmãos um profeta semelhante a mim; a ele ouvireis em tudo quanto vos disser.'),
('acf','atos',3,23,'E acontecerá que toda a alma que não escutar esse profeta será exterminada dentre o povo.'),
('acf','atos',3,24,'Sim, e todos os profetas, desde Samuel, todos quantos depois falaram, também predisseram estes dias.'),
('acf','atos',3,25,'Vós sois os filhos dos profetas e da aliança que Deus fez com nossos pais, dizendo a Abraão: Na tua descendência serão benditas todas as famílias da terra.'),
('acf','atos',3,26,'Ressuscitando Deus a seu Filho Jesus, primeiro o enviou a vós, para que nisso vos abençoasse, no apartar, a cada um de vós, das vossas maldades.'),
('acf','atos',4,1,'E, estando eles falando ao povo, sobrevieram os sacerdotes, e o capitão do templo, e os saduceus,'),
('acf','atos',4,2,'Doendo-se muito de que ensinassem o povo, e anunciassem em Jesus a ressurreição dentre os mortos.'),
('acf','atos',4,3,'E lançaram mão deles, e os encerraram na prisão até ao dia seguinte, pois já era tarde.'),
('acf','atos',4,4,'Muitos, porém, dos que ouviram a palavra creram, e chegou o número desses homens a quase cinco mil.'),
('acf','atos',4,5,'E aconteceu, no dia seguinte, reunirem-se em Jerusalém os seus principais, os anciãos, os escribas,'),
('acf','atos',4,6,'E Anás, o sumo sacerdote, e Caifás, e João, e Alexandre, e todos quantos havia da linhagem do sumo sacerdote.'),
('acf','atos',4,7,'E, pondo-os no meio, perguntaram: Com que poder ou em nome de quem fizestes isto?'),
('acf','atos',4,8,'Então Pedro, cheio do Espírito Santo, lhes disse: Principais do povo, e vós, anciãos de Israel,'),
('acf','atos',4,9,'Visto que hoje somos interrogados acerca do benefício feito a um homem enfermo, e do modo como foi curado,'),
('acf','atos',4,10,'Seja conhecido de vós todos, e de todo o povo de Israel, que em nome de Jesus Cristo, o Nazareno, aquele a quem vós crucificastes e a quem Deus ressuscitou dentre os mortos, em nome desse é que este está são diante de vós.'),
('acf','atos',4,11,'Ele é a pedra que foi rejeitada por vós, os edificadores, a qual foi posta por cabeça de esquina.'),
('acf','atos',4,12,'E em nenhum outro há salvação, porque também debaixo do céu nenhum outro nome há, dado entre os homens, pelo qual devamos ser salvos.'),
('acf','atos',4,13,'Então eles, vendo a ousadia de Pedro e João, e informados de que eram homens sem letras e indoutos, maravilharam-se e reconheceram que eles haviam estado com Jesus.'),
('acf','atos',4,14,'E, vendo estar com eles o homem que fora curado, nada tinham que dizer em contrário.'),
('acf','atos',4,15,'Todavia, mandando-os sair fora do conselho, conferenciaram entre si,'),
('acf','atos',4,16,'Dizendo: Que havemos de fazer a estes homens? porque a todos os que habitam em Jerusalém é manifesto que por eles foi feito um sinal notório, e não o podemos negar;'),
('acf','atos',4,17,'Mas, para que não se divulgue mais entre o povo, ameacemo-los para que não falem mais nesse nome a homem algum.'),
('acf','atos',4,18,'E, chamando-os, disseram-lhes que absolutamente não falassem, nem ensinassem, no nome de Jesus.'),
('acf','atos',4,19,'Respondendo, porém, Pedro e João, lhes disseram: Julgai vós se é justo, diante de Deus, ouvir-vos antes a vós do que a Deus;'),
('acf','atos',4,20,'Porque não podemos deixar de falar do que temos visto e ouvido.'),
('acf','atos',4,21,'Mas eles ainda os ameaçaram mais e, não achando motivo para os castigar, deixaram-nos ir, por causa do povo; porque todos glorificavam a Deus pelo que acontecera;'),
('acf','atos',4,22,'Pois tinha mais de quarenta anos o homem em quem se operara aquele milagre de saúde.'),
('acf','atos',4,23,'E, soltos eles, foram para os seus, e contaram tudo o que lhes disseram os principais dos sacerdotes e os anciãos.'),
('acf','atos',4,24,'E, ouvindo eles isto, unânimes levantaram a voz a Deus, e disseram: Senhor, tu és o Deus que fizeste o céu, e a terra, e o mar e tudo o que neles há;'),
('acf','atos',4,25,'Que disseste pela boca de Davi, teu servo: Por que bramaram os gentios, e os povos pensaram coisas vãs?'),
('acf','atos',4,26,'Levantaram-se os reis da terra,E os príncipes se ajuntaram à uma,Contra o Senhor e contra o seu Ungido.'),
('acf','atos',4,27,'Porque verdadeiramente contra o teu santo Filho Jesus, que tu ungiste, se ajuntaram, não só Herodes, mas Pôncio Pilatos, com os gentios e os povos de Israel;'),
('acf','atos',4,28,'Para fazerem tudo o que a tua mão e o teu conselho tinham anteriormente determinado que se havia de fazer.'),
('acf','atos',4,29,'Agora, pois, ó Senhor, olha para as suas ameaças, e concede aos teus servos que falem com toda a ousadia a tua palavra;'),
('acf','atos',4,30,'Enquanto estendes a tua mão para curar, e para que se façam sinais e prodígios pelo nome de teu santo Filho Jesus.'),
('acf','atos',4,31,'E, tendo orado, moveu-se o lugar em que estavam reunidos; e todos foram cheios do Espírito Santo, e anunciavam com ousadia a palavra de Deus.'),
('acf','atos',4,32,'E era um o coração e a alma da multidão dos que criam, e ninguém dizia que coisa alguma do que possuía era sua própria, mas todas as coisas lhes eram comuns.'),
('acf','atos',4,33,'E os apóstolos davam, com grande poder, testemunho da ressurreição do Senhor Jesus, e em todos eles havia abundante graça.'),
('acf','atos',4,34,'Não havia, pois, entre eles necessitado algum; porque todos os que possuíam herdades ou casas, vendendo-as, traziam o preço do que fora vendido, e o depositavam aos pés dos apóstolos.'),
('acf','atos',4,35,'E repartia-se a cada um, segundo a necessidade que cada um tinha.'),
('acf','atos',4,36,'Então José, cognominado pelos apóstolos Barnabé(que, traduzido, é Filho da consolação), levita, natural de Chipre,'),
('acf','atos',4,37,'Possuindo uma herdade, vendeu-a, e trouxe o preço, e o depositou aos pés dos apóstolos.'),
('acf','atos',5,1,'Mas um certo homem chamado Ananias, com Safira, sua mulher, vendeu uma propriedade,'),
('acf','atos',5,2,'E reteve parte do preço, sabendo-o também sua mulher; e, levando uma parte, a depositou aos pés dos apóstolos.'),
('acf','atos',5,3,'Disse então Pedro: Ananias, por que encheu Satanás o teu coração, para que mentisses ao Espírito Santo, e retivesses parte do preço da herdade?'),
('acf','atos',5,4,'Guardando-a não ficava para ti? E, vendida, não estava em teu poder? Por que formaste este desígnio em teu coração? Não mentiste aos homens, mas a Deus.'),
('acf','atos',5,5,'E Ananias, ouvindo estas palavras, caiu e expirou. E um grande temor veio sobre todos os que isto ouviram.'),
('acf','atos',5,6,'E, levantando-se os moços, cobriram o morto e, transportando-o para fora, o sepultaram.'),
('acf','atos',5,7,'E, passando um espaço quase de três horas, entrou também sua mulher, não sabendo o que havia acontecido.'),
('acf','atos',5,8,'E disse-lhe Pedro: Dize-me, vendestes por tanto aquela herdade? E ela disse: Sim, por tanto.'),
('acf','atos',5,9,'Então Pedro lhe disse: Por que é que entre vós vos concertastes para tentar o Espírito do Senhor? Eis aí à porta os pés dos que sepultaram o teu marido, e também te levarão a ti.'),
('acf','atos',5,10,'E logo caiu aos seus pés, e expirou. E, entrando os moços, acharam-na morta, e a sepultaram junto de seu marido.'),
('acf','atos',5,11,'E houve um grande temor em toda a igreja, e em todos os que ouviram estas coisas.'),
('acf','atos',5,12,'E muitos sinais e prodígios eram feitos entre o povo pelas mãos dos apóstolos. E estavam todos unanimemente no alpendre de Salomão.'),
('acf','atos',5,13,'Dos outros, porém, ninguém ousava ajuntar-se a eles; mas o povo tinha-os em grande estima.'),
('acf','atos',5,14,'E a multidão dos que criam no Senhor, tanto homens como mulheres, crescia cada vez mais.'),
('acf','atos',5,15,'De sorte que transportavam os enfermos para as ruas, e os punham em leitos e em camilhas para que ao menos a sombra de Pedro, quando este passasse, cobrisse alguns deles.'),
('acf','atos',5,16,'E até das cidades circunvizinhas concorria muita gente a Jerusalém, conduzindo enfermos e atormentados de espíritos imundos; os quais eram todos curados.'),
('acf','atos',5,17,'E, levantando-se o sumo sacerdote, e todos os que estavam com ele (e eram eles da seita dos saduceus), encheram-se de inveja,'),
('acf','atos',5,18,'E lançaram mão dos apóstolos, e os puseram na prisão pública.'),
('acf','atos',5,19,'Mas de noite um anjo do Senhor abriu as portas da prisão e, tirando-os para fora, disse:'),
('acf','atos',5,20,'Ide e apresentai-vos no templo, e dizei ao povo todas as palavras desta vida.'),
('acf','atos',5,21,'E, ouvindo eles isto, entraram de manhã cedo no templo, e ensinavam. Chegando, porém, o sumo sacerdote e os que estavam com ele, convocaram o conselho, e a todos os anciãos dos filhos de Israel, e enviaram ao cárcere, para que de lá os trouxessem.'),
('acf','atos',5,22,'Mas, tendo lá ido os servidores, não os acharam na prisão e, voltando, lho anunciaram,'),
('acf','atos',5,23,'Dizendo: Achamos realmente o cárcere fechado, com toda a segurança, e os guardas, que estavam fora, diante das portas; mas, quando abrimos, ninguém achamos dentro.'),
('acf','atos',5,24,'Então o sumo sacerdote, o capitão do templo e os chefes dos sacerdotes, ouvindo estas palavras, estavam perplexos acerca deles e do que viria a ser aquilo.'),
('acf','atos',5,25,'E, chegando um, anunciou-lhes, dizendo: Eis que os homens que encerrastes na prisão estão no templo e ensinam ao povo.'),
('acf','atos',5,26,'Então foi o capitão com os servidores, e os trouxe, não com violência (porque temiam ser apedrejados pelo povo).'),
('acf','atos',5,27,'E, trazendo-os, os apresentaram ao conselho. E o sumo sacerdote os interrogou,'),
('acf','atos',5,28,'Dizendo: Não vos admoestamos nós expressamente que não ensinásseis nesse nome? E eis que enchestes Jerusalém dessa vossa doutrina, e quereis lançar sobre nós o sangue desse homem.'),
('acf','atos',5,29,'Porém, respondendo Pedro e os apóstolos, disseram: Mais importa obedecer a Deus do que aos homens.'),
('acf','atos',5,30,'O Deus de nossos pais ressuscitou a Jesus, ao qual vós matastes, suspendendo-o no madeiro.'),
('acf','atos',5,31,'Deus com a sua destra o elevou a Príncipe e Salvador, para dar a Israel o arrependimento e a remissão dos pecados.'),
('acf','atos',5,32,'E nós somos testemunhas acerca destas palavras, nós e também o Espírito Santo, que Deus deu àqueles que lhe obedecem.'),
('acf','atos',5,33,'E, ouvindo eles isto, se enfureciam, e deliberaram matá-los.'),
('acf','atos',5,34,'Mas, levantando-se no conselho um certo fariseu, chamado Gamaliel, doutor da lei, venerado por todo o povo, mandou que por um pouco levassem para fora os apóstolos;'),
('acf','atos',5,35,'E disse-lhes: Homens israelitas, acautelai-vos a respeito do que haveis de fazer a estes homens,'),
('acf','atos',5,36,'Porque antes destes dias levantou-se Teudas, dizendo ser alguém; a este se ajuntou o número de uns quatrocentos homens; o qual foi morto, e todos os que lhe deram ouvidos foram dispersos e reduzidos a nada.'),
('acf','atos',5,37,'Depois deste levantou-se Judas, o galileu, nos dias do alistamento, e levou muito povo após si; mas também este pereceu, e todos os que lhe deram ouvidos foram dispersos.'),
('acf','atos',5,38,'E agora digo-vos: Dai de mão a estes homens, e deixai-os, porque, se este conselho ou esta obra é de homens, se desfará,'),
('acf','atos',5,39,'Mas, se é de Deus, não podereis desfazê-la; para que não aconteça serdes também achados combatendo contra Deus.'),
('acf','atos',5,40,'E concordaram com ele. E, chamando os apóstolos, e tendo-os açoitado, mandaram que não falassem no nome de Jesus, e os deixaram ir.'),
('acf','atos',5,41,'Retiraram-se, pois, da presença do conselho, regozijando-se de terem sido julgados dignos de padecer afronta pelo nome de Jesus.'),
('acf','atos',5,42,'E todos os dias, no templo e nas casas, não cessavam de ensinar, e de anunciar a Jesus Cristo.'),
('acf','atos',6,1,'Ora, naqueles dias, crescendo o número dos discípulos, houve uma murmuração dos gregos contra os hebreus, porque as suas viúvas eram desprezadas no ministério cotidiano.'),
('acf','atos',6,2,'E os doze, convocando a multidão dos discípulos, disseram: Não é razoável que nós deixemos a palavra de Deus e sirvamos às mesas.'),
('acf','atos',6,3,'Escolhei, pois, irmãos, dentre vós, sete homens de boa reputação, cheios do Espírito Santo e de sabedoria, aos quais constituamos sobre este importante negócio.'),
('acf','atos',6,4,'Mas nós perseveraremos na oração e no ministério da palavra.'),
('acf','atos',6,5,'E este parecer contentou a toda a multidão, e elegeram Estêvão, homem cheio de fé e do Espírito Santo, e Filipe, e Prócoro, e Nicanor, e Timão, e Parmenas e Nicolau, prosélito de Antioquia;'),
('acf','atos',6,6,'E os apresentaram ante os apóstolos, e estes, orando, lhes impuseram as mãos.'),
('acf','atos',6,7,'E crescia a palavra de Deus, e em Jerusalém se multiplicava muito o número dos discípulos, e grande parte dos sacerdotes obedecia à fé.'),
('acf','atos',6,8,'E Estêvão, cheio de fé e de poder, fazia prodígios e grandes sinais entre o povo.'),
('acf','atos',6,9,'E levantaram-se alguns que eram da sinagoga chamada dos libertinos, e dos cireneus e dos alexandrinos, e dos que eram da Cilícia e da Asia, e disputavam com Estêvão.'),
('acf','atos',6,10,'E não podiam resistir à sabedoria, e ao Espírito com que falava.'),
('acf','atos',6,11,'Então subornaram uns homens, para que dissessem: Ouvimos-lhe proferir palavras blasfemas contra Moisés e contra Deus.'),
('acf','atos',6,12,'E excitaram o povo, os anciãos e os escribas; e, investindo contra ele, o arrebataram e o levaram ao conselho.'),
('acf','atos',6,13,'E apresentaram falsas testemunhas, que diziam: Este homem não cessa de proferir palavras blasfemas contra este santo lugar e a lei;'),
('acf','atos',6,14,'Porque nós lhe ouvimos dizer que esse Jesus Nazareno há de destruir este lugar e mudar os costumes que Moisés nos deu.'),
('acf','atos',6,15,'Então todos os que estavam assentados no conselho, fixando os olhos nele, viram o seu rosto como o rosto de um anjo.'),
('acf','atos',7,1,'E disse o sumo sacerdote: Porventura é isto assim?'),
('acf','atos',7,2,'E ele disse: Homens, irmãos, e pais, ouvi. O Deus da glória apareceu a nosso pai Abraão, estando na mesopotâmia, antes de habitar em Harã,'),
('acf','atos',7,3,'E disse-lhe: Sai da tua terra e dentre a tua parentela, e dirige-te à terra que eu te mostrar.'),
('acf','atos',7,4,'Então saiu da terra dos caldeus, e habitou em Harã. E dali, depois que seu pai faleceu, Deus o trouxe para esta terra em que habitais agora.'),
('acf','atos',7,5,'E não lhe deu nela herança, nem ainda o espaço de um pé; mas prometeu que lhe daria a posse dela, e depois dele, à sua descendência, não tendo ele ainda filho.'),
('acf','atos',7,6,'E falou Deus assim: Que a sua descendência seria peregrina em terra alheia, e a sujeitariam à escravidão, e a maltratariam por quatrocentos anos.'),
('acf','atos',7,7,'E eu julgarei a nação que os tiver escravizado, disse Deus. E depois disto sairão e me servirão neste lugar.'),
('acf','atos',7,8,'E deu-lhe a aliança da circuncisão; e assim gerou a Isaque, e o circuncidou ao oitavo dia; e Isaque a Jacó; e Jacó aos doze patriarcas.'),
('acf','atos',7,9,'E os patriarcas, movidos de inveja, venderam José para o Egito; mas Deus era com ele.'),
('acf','atos',7,10,'E livrou-o de todas as suas tribulações, e lhe deu graça e sabedoria ante Faraó, rei do Egito, que o constituiu governador sobre o Egito e toda a sua casa.'),
('acf','atos',7,11,'Sobreveio então a todo o país do Egito e de Canaã fome e grande tribulação; e nossos pais não achavam alimentos.'),
('acf','atos',7,12,'Mas tendo ouvido Jacó que no Egito havia trigo, enviou ali nossos pais, a primeira vez.'),
('acf','atos',7,13,'E na segunda vez foi José conhecido por seus irmãos, e a sua linhagem foi manifesta a Faraó.'),
('acf','atos',7,14,'E José mandou chamar a seu pai Jacó, e a toda a sua parentela, que era de setenta e cinco almas.'),
('acf','atos',7,15,'E Jacó desceu ao Egito, e morreu, ele e nossos pais;'),
('acf','atos',7,16,'E foram transportados para Siquém, e depositados na sepultura que Abraão comprara por certa soma de dinheiro aos filhos de Emor, pai de Siquém.'),
('acf','atos',7,17,'Aproximando-se, porém, o tempo da promessa que Deus tinha feito a Abraão, o povo cresceu e se multiplicou no Egito;'),
('acf','atos',7,18,'Até que se levantou outro rei, que não conhecia a José.'),
('acf','atos',7,19,'Esse, usando de astúcia contra a nossa linhagem, maltratou nossos pais, ao ponto de os fazer enjeitar as suas crianças, para que não se multiplicassem.'),
('acf','atos',7,20,'Nesse tempo nasceu Moisés, e era mui formoso, e foi criado três meses em casa de seu pai.'),
('acf','atos',7,21,'E, sendo enjeitado, tomou-o a filha de Faraó, e o criou como seu filho.'),
('acf','atos',7,22,'E Moisés foi instruído em toda a ciência dos egípcios; e era poderoso em suas palavras e obras.'),
('acf','atos',7,23,'E, quando completou a idade de quarenta anos, veio-lhe ao coração ir visitar seus irmãos, os filhos de Israel.'),
('acf','atos',7,24,'E, vendo maltratado um deles, o defendeu, e vingou o ofendido, matando o egípcio.'),
('acf','atos',7,25,'E ele cuidava que seus irmãos entenderiam que Deus lhes havia de dar a liberdade pela sua mão; mas eles não entenderam.'),
('acf','atos',7,26,'E no dia seguinte, pelejando eles, foi por eles visto, e quis levá-los à paz, dizendo: Homens, sois irmãos; por que vos agravais um ao outro?'),
('acf','atos',7,27,'E o que ofendia o seu próximo o repeliu, dizendo: Quem te constituiu príncipe e juiz sobre nós?'),
('acf','atos',7,28,'Queres tu matar-me, como ontem mataste o egípcio?'),
('acf','atos',7,29,'E a esta palavra fugiu Moisés, e esteve como estrangeiro na terra de Midiã, onde gerou dois filhos.'),
('acf','atos',7,30,'E, completados quarenta anos, apareceu-lhe o anjo do Senhor no deserto do monte Sinai, numa chama de fogo no meio de uma sarça.'),
('acf','atos',7,31,'Então Moisés, quando viu isto, se maravilhou da visão; e, aproximando-se para observar, foi-lhe dirigida a voz do Senhor,'),
('acf','atos',7,32,'Dizendo: Eu sou o Deus de teus pais, o Deus de Abraão, e o Deus de Isaque, e o Deus de Jacó. E Moisés, todo trêmulo, não ousava olhar.'),
('acf','atos',7,33,'E disse-lhe o Senhor: Tira as alparcas dos teus pés, porque o lugar em que estás é terra santa.'),
('acf','atos',7,34,'Tenho visto atentamente a aflição do meu povo que está no Egito, e ouvi os seus gemidos, e desci a livrá-los. Agora, pois, vem, e enviar-te-ei ao Egito.'),
('acf','atos',7,35,'A este Moisés, ao qual haviam negado, dizendo: Quem te constituiu príncipe e juiz? a este enviou Deus como príncipe e libertador, pela mão do anjo que lhe aparecera na sarça.'),
('acf','atos',7,36,'Foi este que os conduziu para fora, fazendo prodígios e sinais na terra do Egito, e no Mar Vermelho, e no deserto, por quarenta anos.'),
('acf','atos',7,37,'Este é aquele Moisés que disse aos filhos de Israel: O Senhor vosso Deus vos levantará dentre vossos irmãos um profeta como eu; a ele ouvireis.'),
('acf','atos',7,38,'Este é o que esteve entre a congregação no deserto, com o anjo que lhe falava no monte Sinai, e com nossos pais, o qual recebeu as palavras de vida para no-las dar.'),
('acf','atos',7,39,'Ao qual nossos pais não quiseram obedecer, antes o rejeitaram e em seu coração se tornaram ao Egito,'),
('acf','atos',7,40,'Dizendo a Arão: Faze-nos deuses que vão adiante de nós; porque a esse Moisés, que nos tirou da terra do Egito, não sabemos o que lhe aconteceu.'),
('acf','atos',7,41,'E naqueles dias fizeram o bezerro, e ofereceram sacrifícios ao ídolo, e se alegraram nas obras das suas mãos.'),
('acf','atos',7,42,'Mas Deus se afastou, e os abandonou a que servissem ao exército do céu, como está escrito no livro dos profetas: Porventura me oferecestes vítimas e sacrifícios No deserto por quarenta anos, ó casa de Israel?'),
('acf','atos',7,43,'Antes tomastes o tabernáculo de Moloque,E a estrela do vosso deus Renfã, figuras que vós fizestes para as adorar.Transportar-vos-ei, pois, para além da Babilônia.'),
('acf','atos',7,44,'Estava entre nossos pais no deserto o tabernáculo do testemunho, como ordenara aquele que disse a Moisés que o fizesse segundo o modelo que tinha visto.'),
('acf','atos',7,45,'O qual, nossos pais, recebendo-o também, o levaram com Josué quando entraram na posse das nações que Deus lançou para fora da presença de nossos pais, até aos dias de Davi,'),
('acf','atos',7,46,'Que achou graça diante de Deus, e pediu que pudesse achar tabernáculo para o Deus de Jacó.'),
('acf','atos',7,47,'E Salomão lhe edificou casa;'),
('acf','atos',7,48,'Mas o Altíssimo não habita em templos feitos por mãos de homens, como diz o profeta:'),
('acf','atos',7,49,'O céu é o meu trono,e a terra o estrado dos meus pés.Que casa me edificareis? diz o Senhor,Ou qual é o lugar do meu repouso?'),
('acf','atos',7,50,'Porventura não fez a minha mão todas estas coisas?'),
('acf','atos',7,51,'Homens de dura cerviz, e incircuncisos de coração e ouvido, vós sempre resistis ao Espírito Santo; assim vós sois como vossos pais.'),
('acf','atos',7,52,'A qual dos profetas não perseguiram vossos pais? Até mataram os que anteriormente anunciaram a vinda do Justo, do qual vós agora fostes traidores e homicidas;'),
('acf','atos',7,53,'Vós, que recebestes a lei por ordenação dos anjos, e não a guardastes.'),
('acf','atos',7,54,'E, ouvindo eles isto, enfureciam-se em seus corações, e rangiam os dentes contra ele.'),
('acf','atos',7,55,'Mas ele, estando cheio do Espírito Santo, fixando os olhos no céu, viu a glória de Deus, e Jesus, que estava à direita de Deus;'),
('acf','atos',7,56,'E disse: Eis que vejo os céus abertos, e o Filho do homem, que está em pé à mão direita de Deus.'),
('acf','atos',7,57,'Mas eles gritaram com grande voz, taparam os seus ouvidos, e arremeteram unânimes contra ele.'),
('acf','atos',7,58,'E, expulsando-o da cidade, o apedrejavam. E as testemunhas depuseram as suas capas aos pés de um jovem chamado Saulo.'),
('acf','atos',7,59,'E apedrejaram a Estêvão que em invocação dizia: Senhor Jesus, recebe o meu espírito.'),
('acf','atos',7,60,'E, pondo-se de joelhos, clamou com grande voz: Senhor, não lhes imputes este pecado. E, tendo dito isto, adormeceu.'),
('acf','atos',8,1,'E também Saulo consentiu na morte dele. E fez-se naquele dia uma grande perseguição contra a igreja que estava em Jerusalém; e todos foram dispersos pelas terras da Judéia e de Samaria, exceto os apóstolos.'),
('acf','atos',8,2,'E uns homens piedosos foram enterrar Estêvão, e fizeram sobre ele grande pranto.'),
('acf','atos',8,3,'E Saulo assolava a igreja, entrando pelas casas; e, arrastando homens e mulheres, os encerrava na prisão.'),
('acf','atos',8,4,'Mas os que andavam dispersos iam por toda a parte, anunciando a palavra.'),
('acf','atos',8,5,'E, descendo Filipe à cidade de Samaria lhes pregava a Cristo.'),
('acf','atos',8,6,'E as multidões unanimemente prestavam atenção ao que Filipe dizia, porque ouviam e viam os sinais que ele fazia;'),
('acf','atos',8,7,'Pois que os espíritos imundos saíam de muitos que os tinham, clamando em alta voz; e muitos paralíticos e coxos eram curados.'),
('acf','atos',8,8,'E havia grande alegria naquela cidade.'),
('acf','atos',8,9,'E estava ali um certo homem, chamado Simão, que anteriormente exercera naquela cidade a arte mágica, e tinha iludido o povo de Samaria, dizendo que era uma grande personagem;'),
('acf','atos',8,10,'Ao qual todos atendiam, desde o menor até ao maior, dizendo: Este é a grande virtude de Deus.'),
('acf','atos',8,11,'E atendiam-no, porque já desde muito tempo os havia iludido com artes mágicas.'),
('acf','atos',8,12,'Mas, como cressem em Filipe, que lhes pregava acerca do reino de Deus, e do nome de Jesus Cristo, se batizavam, tanto homens como mulheres.'),
('acf','atos',8,13,'E creu até o próprio Simão; e, sendo batizado, ficou de contínuo com Filipe; e, vendo os sinais e as grandes maravilhas que se faziam, estava atônito.'),
('acf','atos',8,14,'Os apóstolos, pois, que estavam em Jerusalém, ouvindo que Samaria recebera a palavra de Deus, enviaram para lá Pedro e João.'),
('acf','atos',8,15,'Os quais, tendo descido, oraram por eles para que recebessem o Espírito Santo'),
('acf','atos',8,16,'(Porque sobre nenhum deles tinha ainda descido; mas somente eram batizados em nome do Senhor Jesus).'),
('acf','atos',8,17,'Então lhes impuseram as mãos, e receberam o Espírito Santo.'),
('acf','atos',8,18,'E Simão, vendo que pela imposição das mãos dos apóstolos era dado o Espírito Santo, lhes ofereceu dinheiro,'),
('acf','atos',8,19,'Dizendo: Dai-me também a mim esse poder, para que aquele sobre quem eu puser as mãos receba o Espírito Santo.'),
('acf','atos',8,20,'Mas disse-lhe Pedro: O teu dinheiro seja contigo para perdição, pois cuidaste que o dom de Deus se alcança por dinheiro.'),
('acf','atos',8,21,'Tu não tens parte nem sorte nesta palavra, porque o teu coração não é reto diante de Deus.'),
('acf','atos',8,22,'Arrepende-te, pois, dessa tua iniqüidade, e ora a Deus, para que porventura te seja perdoado o pensamento do teu coração;'),
('acf','atos',8,23,'Pois vejo que estás em fel de amargura, e em laço de iniqüidade.'),
('acf','atos',8,24,'Respondendo, porém, Simão, disse: Orai vós por mim ao Senhor, para que nada do que dissestes venha sobre mim.'),
('acf','atos',8,25,'Tendo eles, pois, testificado e falado a palavra do Senhor, voltaram para Jerusalém e em muitas aldeias dos samaritanos anunciaram o evangelho.'),
('acf','atos',8,26,'E o anjo do Senhor falou a Filipe, dizendo: Levanta-te, e vai para o lado do sul, ao caminho que desce de Jerusalém para Gaza, que está deserta.'),
('acf','atos',8,27,'E levantou-se, e foi; e eis que um homem etíope, eunuco, mordomo-mor de Candace, rainha dos etíopes, o qual era superintendente de todos os seus tesouros, e tinha ido a Jerusalém para adoração,'),
('acf','atos',8,28,'Regressava e, assentado no seu carro, lia o profeta Isaías.'),
('acf','atos',8,29,'E disse o Espírito a Filipe: Chega-te, e ajunta-te a esse carro.'),
('acf','atos',8,30,'E, correndo Filipe, ouviu que lia o profeta Isaías, e disse: Entendes tu o que lês?'),
('acf','atos',8,31,'E ele disse: Como poderei entender, se alguém não me ensinar? E rogou a Filipe que subisse e com ele se assentasse.'),
('acf','atos',8,32,'E o lugar da Escritura que lia era este: Foi levado como a ovelha para o matadouro; e, como está mudo o cordeiro diante do que o tosquia, Assim não abriu a sua boca.'),
('acf','atos',8,33,'Na sua humilhação foi tirado o seu julgamento; E quem contará a sua geração? Porque a sua vida é tirada da terra.'),
('acf','atos',8,34,'E, respondendo o eunuco a Filipe, disse: Rogo-te, de quem diz isto o profeta? De si mesmo, ou de algum outro?'),
('acf','atos',8,35,'Então Filipe, abrindo a sua boca, e começando nesta Escritura, lhe anunciou a Jesus.'),
('acf','atos',8,36,'E, indo eles caminhando, chegaram ao pé de alguma água, e disse o eunuco: Eis aqui água; que impede que eu seja batizado?'),
('acf','atos',8,37,'E disse Filipe: É lícito, se crês de todo o coração. E, respondendo ele, disse: Creio que Jesus Cristo é o Filho de Deus.'),
('acf','atos',8,38,'E mandou parar o carro, e desceram ambos à água, tanto Filipe como o eunuco, e o batizou.'),
('acf','atos',8,39,'E, quando saíram da água, o Espírito do Senhor arrebatou a Filipe, e não o viu mais o eunuco; e, jubiloso, continuou o seu caminho.'),
('acf','atos',8,40,'E Filipe se achou em Azoto e, indo passando, anunciava o evangelho em todas as cidades, até que chegou a Cesaréia.'),
('acf','atos',9,1,'E Saulo, respirando ainda ameaças e mortes contra os discípulos do Senhor, dirigiu-se ao sumo sacerdote.'),
('acf','atos',9,2,'E pediu-lhe cartas para Damasco, para as sinagogas, a fim de que, se encontrasse alguns deste Caminho, quer homens quer mulheres, os conduzisse presos a Jerusalém.'),
('acf','atos',9,3,'E, indo no caminho, aconteceu que, chegando perto de Damasco, subitamente o cercou um resplendor de luz do céu.'),
('acf','atos',9,4,'E, caindo em terra, ouviu uma voz que lhe dizia: Saulo, Saulo, por que me persegues?'),
('acf','atos',9,5,'E ele disse: Quem és, Senhor? E disse o Senhor: Eu sou Jesus, a quem tu persegues. Duro é para ti recalcitrar contra os aguilhões.'),
('acf','atos',9,6,'E ele, tremendo e atônito, disse: Senhor, que queres que eu faça? E disse-lhe o Senhor: Levanta-te, e entra na cidade, e lá te será dito o que te convém fazer.'),
('acf','atos',9,7,'E os homens, que iam com ele, pararam espantados, ouvindo a voz, mas não vendo ninguém.'),
('acf','atos',9,8,'E Saulo levantou-se da terra, e, abrindo os olhos, não via a ninguém. E, guiando-o pela mão, o conduziram a Damasco.'),
('acf','atos',9,9,'E esteve três dias sem ver, e não comeu nem bebeu.'),
('acf','atos',9,10,'E havia em Damasco um certo discípulo chamado Ananias; e disse-lhe o Senhor em visão: Ananias! E ele respondeu: Eis-me aqui, Senhor.'),
('acf','atos',9,11,'E disse-lhe o Senhor: Levanta-te, e vai à rua chamada Direita, e pergunta em casa de Judas por um homem de Tarso chamado Saulo; pois eis que ele está orando;'),
('acf','atos',9,12,'E numa visão ele viu que entrava um homem chamado Ananias, e punha sobre ele a mão, para que tornasse a ver.'),
('acf','atos',9,13,'E respondeu Ananias: Senhor, a muitos ouvi acerca deste homem, quantos males tem feito aos teus santos em Jerusalém;'),
('acf','atos',9,14,'E aqui tem poder dos principais dos sacerdotes para prender a todos os que invocam o teu nome.'),
('acf','atos',9,15,'Disse-lhe, porém, o Senhor: Vai, porque este é para mim um vaso escolhido, para levar o meu nome diante dos gentios, e dos reis e dos filhos de Israel.'),
('acf','atos',9,16,'E eu lhe mostrarei quanto deve padecer pelo meu nome.'),
('acf','atos',9,17,'E Ananias foi, e entrou na casa e, impondo-lhe as mãos, disse: Irmão Saulo, o Senhor Jesus, que te apareceu no caminho por onde vinhas, me enviou, para que tornes a ver e sejas cheio do Espírito Santo.'),
('acf','atos',9,18,'E logo lhe caíram dos olhos como que umas escamas, e recuperou a vista; e, levantando-se, foi batizado.'),
('acf','atos',9,19,'E, tendo comido, ficou confortado. E esteve Saulo alguns dias com os discípulos que estavam em Damasco.'),
('acf','atos',9,20,'E logo nas sinagogas pregava a Cristo, que este é o Filho de Deus.'),
('acf','atos',9,21,'E todos os que o ouviam estavam atônitos, e diziam: Não é este o que em Jerusalém perseguia os que invocavam este nome, e para isso veio aqui, para os levar presos aos principais dos sacerdotes?'),
('acf','atos',9,22,'Saulo, porém, se esforçava muito mais, e confundia os judeus que habitavam em Damasco, provando que aquele era o Cristo.'),
('acf','atos',9,23,'E, tendo passado muitos dias, os judeus tomaram conselho entre si para o matar.'),
('acf','atos',9,24,'Mas as suas ciladas vieram ao conhecimento de Saulo; e como eles guardavam as portas, tanto de dia como de noite, para poderem tirar-lhe a vida,'),
('acf','atos',9,25,'Tomando-o de noite os discípulos o desceram, dentro de um cesto, pelo muro.'),
('acf','atos',9,26,'E, quando Saulo chegou a Jerusalém, procurava ajuntar-se aos discípulos, mas todos o temiam, não crendo que fosse discípulo.'),
('acf','atos',9,27,'Então Barnabé, tomando-o consigo, o trouxe aos apóstolos, e lhes contou como no caminho ele vira ao Senhor e lhe falara, e como em Damasco falara ousadamente no nome de Jesus.'),
('acf','atos',9,28,'E andava com eles em Jerusalém, entrando e saindo,'),
('acf','atos',9,29,'E falava ousadamente no nome do Senhor Jesus. Falava e disputava também contra os gregos, mas eles procuravam matá-lo.'),
('acf','atos',9,30,'Sabendo-o, porém, os irmãos, o acompanharam até Cesaréia, e o enviaram a Tarso.'),
('acf','atos',9,31,'Assim, pois, as igrejas em toda a Judéia, e Galiléia e Samaria tinham paz, e eram edificadas; e se multiplicavam, andando no temor do Senhor e consolação do Espírito Santo.'),
('acf','atos',9,32,'E aconteceu que, passando Pedro por toda a parte, veio também aos santos que habitavam em Lida.'),
('acf','atos',9,33,'E achou ali certo homem, chamado Enéias, jazendo numa cama havia oito anos, o qual era paralítico.'),
('acf','atos',9,34,'E disse-lhe Pedro: Enéias, Jesus Cristo te dá saúde; levanta-te e faze a tua cama. E logo se levantou.'),
('acf','atos',9,35,'E viram-no todos os que habitavam em Lida e Sarona, os quais se converteram ao Senhor.'),
('acf','atos',9,36,'E havia em Jope uma discípula chamada Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e esmolas que fazia.'),
('acf','atos',9,37,'E aconteceu naqueles dias que, enfermando ela, morreu; e, tendo-a lavado, a depositaram num quarto alto.'),
('acf','atos',9,38,'E, como Lida era perto de Jope, ouvindo os discípulos que Pedro estava ali, lhe mandaram dois homens, rogando-lhe que não se demorasse em vir ter com eles.'),
('acf','atos',9,39,'E, levantando-se Pedro, foi com eles; e quando chegou o levaram ao quarto alto, e todas as viúvas o rodearam, chorando e mostrando as túnicas e roupas que Dorcas fizera quando estava com elas.'),
('acf','atos',9,40,'Mas Pedro, fazendo sair a todos, pôs-se de joelhos e orou: e, voltando-se para o corpo, disse: Tabita, levanta-te. E ela abriu os olhos, e, vendo a Pedro, assentou-se.'),
('acf','atos',9,41,'E ele, dando-lhe a mão, a levantou e, chamando os santos e as viúvas, apresentou-lha viva.'),
('acf','atos',9,42,'E foi isto notório por toda a Jope, e muitos creram no Senhor.'),
('acf','atos',9,43,'E ficou muitos dias em Jope, com um certo Simão curtidor.'),
('acf','atos',10,1,'E havia em Cesaréia um homem por nome Cornélio, centurião da coorte chamada italiana,'),
('acf','atos',10,2,'Piedoso e temente a Deus, com toda a sua casa, o qual fazia muitas esmolas ao povo, e de contínuo orava a Deus.'),
('acf','atos',10,3,'Este, quase à hora nona do dia, viu claramente numa visão um anjo de Deus, que se dirigia para ele e dizia: Cornélio.'),
('acf','atos',10,4,'O qual, fixando os olhos nele, e muito atemorizado, disse: Que é, Senhor? E disse-lhe: As tuas orações e as tuas esmolas têm subido para memória diante de Deus;'),
('acf','atos',10,5,'Agora, pois, envia homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro.'),
('acf','atos',10,6,'Este está hospedado com um certo Simão curtidor, que tem a sua casa junto do mar. Ele te dirá o que deves fazer.'),
('acf','atos',10,7,'E, retirando-se o anjo que lhe falava, chamou dois dos seus criados, e a um piedoso soldado dos que estavam ao seu serviço.'),
('acf','atos',10,8,'E, havendo-lhes contado tudo, os enviou a Jope.'),
('acf','atos',10,9,'E no dia seguinte, indo eles seu caminho, e estando já perto da cidade, subiu Pedro ao terraço para orar, quase à hora sexta.'),
('acf','atos',10,10,'E tendo fome, quis comer; e, enquanto lho preparavam, sobreveio-lhe um arrebatamento de sentidos,'),
('acf','atos',10,11,'E viu o céu aberto, e que descia um vaso, como se fosse um grande lençol atado pelas quatro pontas, e vindo para a terra.'),
('acf','atos',10,12,'No qual havia de todos os animais quadrúpedes e feras e répteis da terra, e aves do céu.'),
('acf','atos',10,13,'E foi-lhe dirigida uma voz: Levanta-te, Pedro, mata e come.'),
('acf','atos',10,14,'Mas Pedro disse: De modo nenhum, Senhor, porque nunca comi coisa alguma comum e imunda.'),
('acf','atos',10,15,'E segunda vez lhe disse a voz: Não faças tu comum ao que Deus purificou.'),
('acf','atos',10,16,'E aconteceu isto por três vezes; e o vaso tornou a recolher-se ao céu.'),
('acf','atos',10,17,'E estando Pedro duvidando entre si acerca do que seria aquela visão que tinha visto, eis que os homens que foram enviados por Cornélio pararam à porta, perguntando pela casa de Simão.'),
('acf','atos',10,18,'E, chamando, perguntaram se Simão, que tinha por sobrenome Pedro, morava ali.'),
('acf','atos',10,19,'E, pensando Pedro naquela visão, disse-lhe o Espírito: Eis que três homens te buscam.'),
('acf','atos',10,20,'Levanta-te pois, desce, e vai com eles, não duvidando; porque eu os enviei.'),
('acf','atos',10,21,'E, descendo Pedro para junto dos homens que lhe foram enviados por Cornélio, disse: Eis que sou eu a quem procurais; qual é a causa por que estais aqui?'),
('acf','atos',10,22,'E eles disseram: Cornélio, o centurião, homem justo e temente a Deus, e que tem bom testemunho de toda a nação dos judeus, foi avisado por um santo anjo para que te chamasse a sua casa, e ouvisse as tuas palavras.'),
('acf','atos',10,23,'Então, chamando-os para dentro, os recebeu em casa. E no dia seguinte foi Pedro com eles, e foram com ele alguns irmãos de Jope.'),
('acf','atos',10,24,'E no dia imediato chegaram a Cesaréia. E Cornélio os estava esperando, tendo já convidado os seus parentes e amigos mais íntimos.'),
('acf','atos',10,25,'E aconteceu que, entrando Pedro, saiu Cornélio a recebê-lo, e, prostrando-se a seus pés o adorou.'),
('acf','atos',10,26,'Mas Pedro o levantou, dizendo: Levanta-te, que eu também sou homem.'),
('acf','atos',10,27,'E, falando com ele, entrou, e achou muitos que ali se haviam ajuntado.'),
('acf','atos',10,28,'E disse-lhes: Vós bem sabeis que não é lícito a um homem judeu ajuntar-se ou chegar-se a estrangeiros; mas Deus mostrou-me que a nenhum homem chame comum ou imundo.'),
('acf','atos',10,29,'Por isso, sendo chamado, vim sem contradizer. Pergunto, pois, por que razão mandastes chamar-me?'),
('acf','atos',10,30,'E disse Cornélio: Há quatro dias estava eu em jejum até esta hora, orando em minha casa à hora nona.'),
('acf','atos',10,31,'E eis que diante de mim se apresentou um homem com vestes resplandecentes, e disse: Cornélio, a tua oração foi ouvida, e as tuas esmolas estão em memória diante de Deus.'),
('acf','atos',10,32,'Envia, pois, a Jope, e manda chamar Simão, o que tem por sobrenome Pedro; este está hospedado em casa de Simão o curtidor, junto do mar, e ele, vindo, te falará.'),
('acf','atos',10,33,'E logo mandei chamar-te, e bem fizeste em vir. Agora, pois, estamos todos presentes diante de Deus, para ouvir tudo quanto por Deus te é mandado.'),
('acf','atos',10,34,'E, abrindo Pedro a boca, disse: Reconheço por verdade que Deus não faz acepção de pessoas;'),
('acf','atos',10,35,'Mas que lhe é agradável aquele que, em qualquer nação, o teme e faz o que é justo.'),
('acf','atos',10,36,'A palavra que ele enviou aos filhos de Israel, anunciando a paz por Jesus Cristo (este é o Senhor de todos);'),
('acf','atos',10,37,'Esta palavra, vós bem sabeis, veio por toda a Judéia, começando pela Galiléia, depois do batismo que João pregou;'),
('acf','atos',10,38,'Como Deus ungiu a Jesus de Nazaré com o Espírito Santo e com virtude; o qual andou fazendo bem, e curando a todos os oprimidos do diabo, porque Deus era com ele.'),
('acf','atos',10,39,'E nós somos testemunhas de todas as coisas que fez, tanto na terra da Judéia como em Jerusalém; ao qual mataram, pendurando-o num madeiro.'),
('acf','atos',10,40,'A este ressuscitou Deus ao terceiro dia, e fez que se manifestasse,'),
('acf','atos',10,41,'Não a todo o povo, mas às testemunhas que Deus antes ordenara; a nós, que comemos e bebemos juntamente com ele, depois que ressuscitou dentre os mortos.'),
('acf','atos',10,42,'E nos mandou pregar ao povo, e testificar que ele é o que por Deus foi constituído juiz dos vivos e dos mortos.'),
('acf','atos',10,43,'A este dão testemunho todos os profetas, de que todos os que nele crêem receberão o perdão dos pecados pelo seu nome.'),
('acf','atos',10,44,'E, dizendo Pedro ainda estas palavras, caiu o Espírito Santo sobre todos os que ouviam a palavra.'),
('acf','atos',10,45,'E os fiéis que eram da circuncisão, todos quantos tinham vindo com Pedro, maravilharam-se de que o dom do Espírito Santo se derramasse também sobre os gentios.'),
('acf','atos',10,46,'Porque os ouviam falar línguas, e magnificar a Deus.'),
('acf','atos',10,47,'Respondeu, então, Pedro: Pode alguém porventura recusar a água, para que não sejam batizados estes, que também receberam como nós o Espírito Santo?'),
('acf','atos',10,48,'E mandou que fossem batizados em nome do Senhor. Então rogaram-lhe que ficasse com eles por alguns dias.'),
('acf','atos',11,1,'E ouviram os apóstolos, e os irmãos que estavam na Judéia, que também os gentios tinham recebido a palavra de Deus.'),
('acf','atos',11,2,'E, subindo Pedro a Jerusalém, disputavam com ele os que eram da circuncisão,'),
('acf','atos',11,3,'Dizendo: Entraste em casa de homens incircuncisos, e comeste com eles.'),
('acf','atos',11,4,'Mas Pedro começou a fazer-lhes uma exposição por ordem, dizendo:'),
('acf','atos',11,5,'Estando eu orando na cidade de Jope, tive, num arrebatamento dos sentidos, uma visão; via um vaso, como um grande lençol que descia do céu e vinha até junto de mim.'),
('acf','atos',11,6,'E, pondo nele os olhos, considerei, e vi animais da terra, quadrúpedes, e feras, e répteis e aves do céu.'),
('acf','atos',11,7,'E ouvi uma voz que me dizia: Levanta-te, Pedro; mata e come.'),
('acf','atos',11,8,'Mas eu disse: De maneira nenhuma, Senhor; pois, nunca em minha boca entrou coisa alguma comum ou imunda.'),
('acf','atos',11,9,'Mas a voz respondeu-me do céu segunda vez: Não chames tu comum ao que Deus purificou.'),
('acf','atos',11,10,'E sucedeu isto por três vezes; e tudo tornou a recolher-se ao céu.'),
('acf','atos',11,11,'E eis que, na mesma hora, pararam, junto da casa em que eu estava, três homens que me foram enviados de Cesaréia.'),
('acf','atos',11,12,'E disse-me o Espírito que fosse com eles, nada duvidando; e também estes seis irmãos foram comigo, e entramos em casa daquele homem;'),
('acf','atos',11,13,'E contou-nos como vira em pé um anjo em sua casa, e lhe dissera: Envia homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro,'),
('acf','atos',11,14,'O qual te dirá palavras com que te salves, tu e toda a tua casa.'),
('acf','atos',11,15,'E, quando comecei a falar, caiu sobre eles o Espírito Santo, como também sobre nós ao princípio.'),
('acf','atos',11,16,'E lembrei-me do dito do Senhor, quando disse: João certamente batizou com água; mas vós sereis batizados com o Espírito Santo.'),
('acf','atos',11,17,'Portanto, se Deus lhes deu o mesmo dom que a nós, quando havemos crido no Senhor Jesus Cristo, quem era então eu, para que pudesse resistir a Deus?'),
('acf','atos',11,18,'E, ouvindo estas coisas, apaziguaram-se, e glorificaram a Deus, dizendo: Na verdade até aos gentios deu Deus o arrependimento para a vida.'),
('acf','atos',11,19,'E os que foram dispersos pela perseguição que sucedeu por causa de Estêvão caminharam até à Fenícia, Chipre e Antioquia, não anunciando a ninguém a palavra, senão somente aos judeus.'),
('acf','atos',11,20,'E havia entre eles alguns homens chíprios e cirenenses, os quais entrando em Antioquia falaram aos gregos, anunciando o Senhor Jesus.'),
('acf','atos',11,21,'E a mão do Senhor era com eles; e grande número creu e se converteu ao Senhor.'),
('acf','atos',11,22,'E chegou a fama destas coisas aos ouvidos da igreja que estava em Jerusalém; e enviaram Barnabé a Antioquia.'),
('acf','atos',11,23,'O qual, quando chegou, e viu a graça de Deus, se alegrou, e exortou a todos a que permanecessem no Senhor, com propósito de coração;'),
('acf','atos',11,24,'Porque era homem de bem e cheio do Espírito Santo e de fé. E muita gente se uniu ao Senhor.'),
('acf','atos',11,25,'E partiu Barnabé para Tarso, a buscar Saulo; e, achando-o, o conduziu para Antioquia.'),
('acf','atos',11,26,'E sucedeu que todo um ano se reuniram naquela igreja, e ensinaram muita gente; e em Antioquia foram os discípulos, pela primeira vez, chamados cristãos.'),
('acf','atos',11,27,'E naqueles dias desceram profetas de Jerusalém para Antioquia.'),
('acf','atos',11,28,'E, levantando-se um deles, por nome Ágabo, dava a entender pelo Espírito, que haveria uma grande fome em todo o mundo, e isso aconteceu no tempo de Cláudio César.'),
('acf','atos',11,29,'E os discípulos determinaram mandar, cada um conforme o que pudesse, socorro aos irmãos que habitavam na Judéia.'),
('acf','atos',11,30,'O que eles com efeito fizeram, enviando-o aos anciãos por mão de Barnabé e de Saulo.'),
('acf','atos',12,1,'E por aquele mesmo tempo o rei Herodes estendeu as mãos sobre alguns da igreja, para os maltratar;'),
('acf','atos',12,2,'E matou à espada Tiago, irmão de João.'),
('acf','atos',12,3,'E, vendo que isso agradara aos judeus, continuou, mandando prender também a Pedro. E eram os dias dos ázimos.'),
('acf','atos',12,4,'E, havendo-o prendido, o encerrou na prisão, entregando-o a quatro quaternos de soldados, para que o guardassem, querendo apresentá-lo ao povo depois da páscoa.'),
('acf','atos',12,5,'Pedro, pois, era guardado na prisão; mas a igreja fazia contínua oração por ele a Deus.'),
('acf','atos',12,6,'E quando Herodes estava para o fazer comparecer, nessa mesma noite estava Pedro dormindo entre dois soldados, ligado com duas cadeias, e os guardas diante da porta guardavam a prisão.'),
('acf','atos',12,7,'E eis que sobreveio o anjo do Senhor, e resplandeceu uma luz na prisão; e, tocando a Pedro na ilharga, o despertou, dizendo: Levanta-te depressa. E caíram-lhe das mãos as cadeias.'),
('acf','atos',12,8,'E disse-lhe o anjo: Cinge-te, e ata as tuas alparcas. E ele assim o fez. Disse-lhe mais: Lança às costas a tua capa, e segue-me.'),
('acf','atos',12,9,'E, saindo, o seguia. E não sabia que era real o que estava sendo feito pelo anjo, mas cuidava que via alguma visão.'),
('acf','atos',12,10,'E, quando passaram a primeira e segunda guarda, chegaram à porta de ferro, que dá para a cidade, a qual se lhes abriu por si mesma; e, tendo saído, percorreram uma rua, e logo o anjo se apartou dele.'),
('acf','atos',12,11,'E Pedro, tornando a si, disse: Agora sei verdadeiramente que o Senhor enviou o seu anjo, e me livrou da mão de Herodes, e de tudo o que o povo dos judeus esperava.'),
('acf','atos',12,12,'E, considerando ele nisto, foi à casa de Maria, mãe de João, que tinha por sobrenome Marcos, onde muitos estavam reunidos e oravam.'),
('acf','atos',12,13,'E, batendo Pedro à porta do pátio, uma menina chamada Rode saiu a escutar;'),
('acf','atos',12,14,'E, conhecendo a voz de Pedro, de gozo não abriu a porta, mas, correndo para dentro, anunciou que Pedro estava à porta.'),
('acf','atos',12,15,'E disseram-lhe: Estás fora de ti. Mas ela afirmava que assim era. E diziam: É o seu anjo.'),
('acf','atos',12,16,'Mas Pedro perseverava em bater e, quando abriram, viram-no, e se espantaram.'),
('acf','atos',12,17,'E acenando-lhes ele com a mão para que se calassem, contou-lhes como o Senhor o tirara da prisão, e disse: Anunciai isto a Tiago e aos irmãos. E, saindo, partiu para outro lugar.'),
('acf','atos',12,18,'E, sendo já dia, houve não pouco alvoroço entre os soldados sobre o que seria feito de Pedro.'),
('acf','atos',12,19,'E, quando Herodes o procurou e o não achou, feita inquirição aos guardas, mandou-os justiçar. E, partindo da Judéia para Cesaréia, ficou ali.'),
('acf','atos',12,20,'E ele estava irritado com os de Tiro e de Sidom; mas estes, vindo de comum acordo ter com ele, e obtendo a amizade de Blasto, que era o camarista do rei, pediam paz; porquanto o seu país se abastecia do país do rei.'),
('acf','atos',12,21,'E num dia designado, vestindo Herodes as vestes reais, estava assentado no tribunal e lhes fez uma prática.'),
('acf','atos',12,22,'E o povo exclamava: Voz de Deus, e não de homem.'),
('acf','atos',12,23,'E no mesmo instante feriu-o o anjo do Senhor, porque não deu glória a Deus e, comido de bichos, expirou.'),
('acf','atos',12,24,'E a palavra de Deus crescia e se multiplicava.'),
('acf','atos',12,25,'E Barnabé e Saulo, havendo terminado aquele serviço, voltaram de Jerusalém, levando também consigo a João, que tinha por sobrenome Marcos.'),
('acf','atos',13,1,'E na igreja que estava em Antioquia havia alguns profetas e doutores, a saber: Barnabé e Simeão chamado Níger, e Lúcio, cireneu, e Manaém, que fora criado com Herodes o tetrarca, e Saulo.'),
('acf','atos',13,2,'E, servindo eles ao Senhor, e jejuando, disse o Espírito Santo: Apartai-me a Barnabé e a Saulo para a obra a que os tenho chamado.'),
('acf','atos',13,3,'Então, jejuando e orando, e pondo sobre eles as mãos, os despediram.'),
('acf','atos',13,4,'E assim estes, enviados pelo Espírito Santo, desceram a Selêucia e dali navegaram para Chipre.'),
('acf','atos',13,5,'E, chegados a Salamina, anunciavam a palavra de Deus nas sinagogas dos judeus; e tinham também a João como cooperador.'),
('acf','atos',13,6,'E, havendo atravessado a ilha até Pafos, acharam um certo judeu mágico, falso profeta, chamado Barjesus,'),
('acf','atos',13,7,'O qual estava com o procônsul Sérgio Paulo, homem prudente. Este, chamando a si Barnabé e Saulo, procurava muito ouvir a palavra de Deus.'),
('acf','atos',13,8,'Mas resistia-lhes Elimas, o encantador (porque assim se interpreta o seu nome), procurando apartar da fé o procônsul.'),
('acf','atos',13,9,'Todavia Saulo, que também se chama Paulo, cheio do Espírito Santo, e fixando os olhos nele,'),
('acf','atos',13,10,'Disse: Ó filho do diabo, cheio de todo o engano e de toda a malícia, inimigo de toda a justiça, não cessarás de perturbar os retos caminhos do Senhor?'),
('acf','atos',13,11,'Eis aí, pois, agora contra ti a mão do Senhor, e ficarás cego, sem ver o sol por algum tempo. E no mesmo instante a escuridão e as trevas caíram sobre ele e, andando à roda, buscava a quem o guiasse pela mão.'),
('acf','atos',13,12,'Então o procônsul, vendo o que havia acontecido, creu, maravilhado da doutrina do Senhor.'),
('acf','atos',13,13,'E, partindo de Pafos, Paulo e os que estavam com ele chegaram a Perge, da Panfília. Mas João, apartando-se deles, voltou para Jerusalém.'),
('acf','atos',13,14,'E eles, saindo de Perge, chegaram a Antioquia, da Pisídia, e, entrando na sinagoga, num dia de sábado, assentaram-se;'),
('acf','atos',13,15,'E, depois da lição da lei e dos profetas, lhes mandaram dizer os principais da sinagoga: Homens irmãos, se tendes alguma palavra de consolação para o povo, falai.'),
('acf','atos',13,16,'E, levantando-se Paulo, e pedindo silêncio com a mão, disse: Homens israelitas, e os que temeis a Deus, ouvi:'),
('acf','atos',13,17,'O Deus deste povo de Israel escolheu a nossos pais, e exaltou o povo, sendo eles estrangeiros na terra do Egito; e com braço poderoso os tirou dela;'),
('acf','atos',13,18,'E suportou os seus costumes no deserto por espaço de quase quarenta anos.'),
('acf','atos',13,19,'E, destruindo a sete nações na terra de Canaã, deu-lhes por sorte a terra deles.'),
('acf','atos',13,20,'E, depois disto, por quase quatrocentos e cinqüenta anos, lhes deu juízes, até ao profeta Samuel.'),
('acf','atos',13,21,'E depois pediram um rei, e Deus lhes deu por quarenta anos, a Saul filho de Cis, homem da tribo de Benjamim.'),
('acf','atos',13,22,'E, quando este foi retirado, levantou-lhes como rei a Davi, ao qual também deu testemunho, e disse: Achei a Davi, filho de Jessé, homem conforme o meu coração, que executará toda a minha vontade.'),
('acf','atos',13,23,'Da descendência deste, conforme a promessa, levantou Deus a Jesus para Salvador de Israel;'),
('acf','atos',13,24,'Tendo primeiramente João, antes da vinda dele, pregado a todo o povo de Israel o batismo de arrependimento.'),
('acf','atos',13,25,'Mas João, quando completava a carreira, disse: Quem pensais vós que eu sou? Eu não sou o Cristo; mas eis que após mim vem aquele a quem não sou digno de desatar as alparcas dos pés.'),
('acf','atos',13,26,'Homens irmãos, filhos da geração de Abraão, e os que dentre vós temem a Deus, a vós vos é enviada a palavra desta salvação.'),
('acf','atos',13,27,'Por não terem conhecido a este, os que habitavam em Jerusalém, e os seus príncipes, condenaram-no, cumprindo assim as vozes dos profetas que se lêem todos os sábados.'),
('acf','atos',13,28,'E, embora não achassem alguma causa de morte, pediram a Pilatos que ele fosse morto.'),
('acf','atos',13,29,'E, havendo eles cumprido todas as coisas que dele estavam escritas, tirando-o do madeiro, o puseram na sepultura;'),
('acf','atos',13,30,'Mas Deus o ressuscitou dentre os mortos.'),
('acf','atos',13,31,'E ele por muitos dias foi visto pelos que subiram com ele da Galiléia a Jerusalém, e são suas testemunhas para com o povo.'),
('acf','atos',13,32,'E nós vos anunciamos que a promessa que foi feita aos pais, Deus a cumpriu a nós, seus filhos, ressuscitando a Jesus;'),
('acf','atos',13,33,'Como também está escrito no salmo segundo: Meu filho és tu, hoje te gerei.'),
('acf','atos',13,34,'E que o ressuscitaria dentre os mortos, para nunca mais tornar à corrupção, disse-o assim: As santas e fiéis bênçãos de Davi vos darei.'),
('acf','atos',13,35,'Por isso também em outro salmo diz: Não permitirás que o teu santo veja corrupção.'),
('acf','atos',13,36,'Porque, na verdade, tendo Davi no seu tempo servido conforme a vontade de Deus, dormiu, foi posto junto de seus pais e viu a corrupção.'),
('acf','atos',13,37,'Mas aquele a quem Deus ressuscitou nenhuma corrupção viu.'),
('acf','atos',13,38,'Seja-vos, pois, notório, homens irmàos, que por este se vos anuncia a remissão dos pecados.'),
('acf','atos',13,39,'E de tudo o que, pela lei de Moisés, não pudestes ser justificados, por ele é justificado todo aquele que crê.'),
('acf','atos',13,40,'Vede, pois, que não venha sobre vós o que está dito nos profetas:'),
('acf','atos',13,41,'Vede, ó desprezadores, e espantai-vos e desaparecei;porque opero uma obra em vossos dias,ora tal que não crereis, se alguém vo-la contar.'),
('acf','atos',13,42,'E, saídos os judeus da sinagoga, os gentios rogaram que no sábado seguinte lhes fossem ditas as mesmas coisas.'),
('acf','atos',13,43,'E, despedida a sinagoga, muitos dos judeus e dos prosélitos religiosos seguiram Paulo e Barnabé; os quais, falando-lhes, os exortavam a que permanecessem na graça de Deus.'),
('acf','atos',13,44,'E no sábado seguinte ajuntou-se quase toda a cidade para ouvir a palavra de Deus.'),
('acf','atos',13,45,'Então os judeus, vendo a multidão, encheram-se de inveja e, blasfemando, contradiziam o que Paulo falava.'),
('acf','atos',13,46,'Mas Paulo e Barnabé, usando de ousadia, disseram: Era mister que a vós se vos pregasse primeiro a palavra de Deus; mas, visto que a rejeitais, e não vos julgais dignos da vida eterna, eis que nos voltamos para os gentios;'),
('acf','atos',13,47,'Porque o Senhor assim no-lo mandou:eu te pus para luz dos gentios,a fim de que sejas para salvação até os confins da terra.'),
('acf','atos',13,48,'E os gentios, ouvindo isto, alegraram-se, e glorificavam a palavra do Senhor; e creram todos quantos estavam ordenados para a vida eterna.'),
('acf','atos',13,49,'E a palavra do Senhor se divulgava por toda aquela província.'),
('acf','atos',13,50,'Mas os judeus incitaram algumas mulheres religiosas e honestas, e os principais da cidade, e levantaram perseguição contra Paulo e Barnabé, e os lançaram fora dos seus termos.'),
('acf','atos',13,51,'Sacudindo, porém, contra eles o pó dos seus pés, partiram para Icônio.'),
('acf','atos',13,52,'E os discípulos estavam cheios de alegria e do Espírito Santo.'),
('acf','atos',14,1,'E aconteceu que em Icônio entraram juntos na sinagoga dos judeus, e falaram de tal modo que creu uma grande multidão, não só de judeus mas de gregos.'),
('acf','atos',14,2,'Mas os judeus incrédulos incitaram e irritaram, contra os irmãos, os ânimos dos gentios.'),
('acf','atos',14,3,'Detiveram-se, pois, muito tempo, falando ousadamente acerca do Senhor, o qual dava testemunho à palavra da sua graça, permitindo que por suas mãos se fizessem sinais e prodígios.'),
('acf','atos',14,4,'E dividiu-se a multidão da cidade; e uns eram pelos judeus, e outros pelos apóstolos.'),
('acf','atos',14,5,'E havendo um motim, tanto dos judeus como dos gentios, com os seus principais, para os insultarem e apedrejarem,'),
('acf','atos',14,6,'Sabendo-o eles, fugiram para Listra e Derbe, cidades de Licaônia, e para a província circunvizinha;'),
('acf','atos',14,7,'E ali pregavam o evangelho.'),
('acf','atos',14,8,'E estava assentado em Listra certo homem leso dos pés, coxo desde o ventre de sua mãe, o qual nunca tinha andado.'),
('acf','atos',14,9,'Este ouviu falar Paulo, que, fixando nele os olhos, e vendo que tinha fé para ser curado,'),
('acf','atos',14,10,'Disse em voz alta: Levanta-te direito sobre teus pés. E ele saltou e andou.'),
('acf','atos',14,11,'E as multidões, vendo o que Paulo fizera, levantaram a sua voz, dizendo em língua licaônica: Fizeram-se os deuses semelhantes aos homens, e desceram até nós.'),
('acf','atos',14,12,'E chamavam Júpiter a Barnabé, e Mercúrio a Paulo; porque este era o que falava.'),
('acf','atos',14,13,'E o sacerdote de Júpiter, cujo templo estava em frente da cidade, trazendo para a entrada da porta touros e grinaldas, queria com a multidão sacrificar-lhes.'),
('acf','atos',14,14,'Ouvindo, porém, isto os apóstolos Barnabé e Paulo, rasgaram as suas vestes, e saltaram para o meio da multidão, clamando,'),
('acf','atos',14,15,'E dizendo: Senhores, por que fazeis essas coisas? Nós também somos homens como vós, sujeitos às mesmas paixões, e vos anunciamos que vos convertais dessas vaidades ao Deus vivo, que fez o céu, e a terra, o mar, e tudo quanto há neles;'),
('acf','atos',14,16,'O qual nos tempos passados deixou andar todas as nações em seus próprios caminhos.'),
('acf','atos',14,17,'E contudo, não se deixou a si mesmo sem testemunho, beneficiando-vos lá do céu, dando-vos chuvas e tempos frutíferos, enchendo de mantimento e de alegria os vossos corações.'),
('acf','atos',14,18,'E, dizendo isto, com dificuldade impediram que as multidões lhes sacrificassem.'),
('acf','atos',14,19,'Sobrevieram, porém, uns judeus de Antioquia e de Icônio que, tendo convencido a multidão, apedrejaram a Paulo e o arrastaram para fora da cidade, cuidando que estava morto.'),
('acf','atos',14,20,'Mas, rodeando-o os discípulos, levantou-se, e entrou na cidade, e no dia seguinte saiu com Barnabé para Derbe.'),
('acf','atos',14,21,'E, tendo anunciado o evangelho naquela cidade e feito muitos discípulos, voltaram para Listra, e Icônio e Antioquia,'),
('acf','atos',14,22,'Confirmando os ânimos dos discípulos, exortando-os a permanecer na fé, pois que por muitas tribulações nos importa entrar no reino de Deus.'),
('acf','atos',14,23,'E, havendo-lhes, por comum consentimento, eleito anciãos em cada igreja, orando com jejuns, os encomendaram ao Senhor em quem haviam crido.'),
('acf','atos',14,24,'Passando depois por Pisídia, dirigiram-se a Panfília.'),
('acf','atos',14,25,'E, tendo anunciado a palavra em Perge, desceram a Atália.'),
('acf','atos',14,26,'E dali navegaram para Antioquia, de onde tinham sido encomendados à graça de Deus para a obra que já haviam cumprido.'),
('acf','atos',14,27,'E, quando chegaram e reuniram a igreja, relataram quão grandes coisas Deus fizera por eles, e como abrira aos gentios a porta da fé.'),
('acf','atos',14,28,'E ficaram ali não pouco tempo com os discípulos.'),
('acf','atos',15,1,'Então alguns que tinham descido da Judéia ensinavam assim os irmãos: Se não vos circuncidardes conforme o uso de Moisés, não podeis salvar-vos.'),
('acf','atos',15,2,'Tendo tido Paulo e Barnabé não pequena discussão e contenda contra eles, resolveu-se que Paulo e Barnabé, e alguns dentre eles, subissem a Jerusalém, aos apóstolos e aos anciãos, sobre aquela questão.'),
('acf','atos',15,3,'E eles, sendo acompanhados pela igreja, passavam pela Fenícia e por Samaria, contando a conversão dos gentios; e davam grande alegria a todos os irmãos.'),
('acf','atos',15,4,'E, quando chegaram a Jerusalém, foram recebidos pela igreja e pelos apóstolos e anciãos, e lhes anunciaram quão grandes coisas Deus tinha feito com eles.'),
('acf','atos',15,5,'Alguns, porém, da seita dos fariseus, que tinham crido, se levantaram, dizendo que era mister circuncidá-los e mandar-lhes que guardassem a lei de Moisés.'),
('acf','atos',15,6,'Congregaram-se, pois, os apóstolos e os anciãos para considerar este assunto.'),
('acf','atos',15,7,'E, havendo grande contenda, levantou-se Pedro e disse-lhes: Homens irmãos, bem sabeis que já há muito tempo Deus me elegeu dentre nós, para que os gentios ouvissem da minha boca a palavra do evangelho, e cressem.'),
('acf','atos',15,8,'E Deus, que conhece os corações, lhes deu testemunho, dando-lhes o Espírito Santo, assim como também a nós;'),
('acf','atos',15,9,'E não fez diferença alguma entre eles e nós, purificando os seus corações pela fé.'),
('acf','atos',15,10,'Agora, pois, por que tentais a Deus, pondo sobre a cerviz dos discípulos um jugo que nem nossos pais nem nós pudemos suportar?'),
('acf','atos',15,11,'Mas cremos que seremos salvos pela graça do Senhor Jesus Cristo, como eles também.'),
('acf','atos',15,12,'Então toda a multidão se calou e escutava a Barnabé e a Paulo, que contavam quão grandes sinais e prodígios Deus havia feito por meio deles entre os gentios.'),
('acf','atos',15,13,'E, havendo-se eles calado, tomou Tiago a palavra, dizendo: Homens irmãos, ouvi-me:'),
('acf','atos',15,14,'Simão relatou como primeiramente Deus visitou os gentios, para tomar deles um povo para o seu nome.'),
('acf','atos',15,15,'E com isto concordam as palavras dos profetas; como está escrito:'),
('acf','atos',15,16,'Depois disto voltarei,e reedificarei o tabernáculo de Davi, que está caído, levantá-lo-ei das suas ruínas, e tornarei a edificá-lo.'),
('acf','atos',15,17,'Para que o restante dos homens busque ao Senhor,e todos os gentios, sobre os quais o meu nome é invocado,diz o Senhor, que faz todas estas coisas,'),
('acf','atos',15,18,'Conhecidas sào a Deus, desde o princípio do mundo, todas as suas obras.'),
('acf','atos',15,19,'Por isso julgo que não se deve perturbar aqueles, dentre os gentios, que se convertem a Deus.'),
('acf','atos',15,20,'Mas escrever-lhes que se abstenham das contaminações dos ídolos, da fornicação, do que é sufocado e do sangue.'),
('acf','atos',15,21,'Porque Moisés, desde os tempos antigos, tem em cada cidade quem o pregue, e cada sábado é lido nas sinagogas.'),
('acf','atos',15,22,'Então pareceu bem aos apóstolos e aos anciãos, com toda a igreja, eleger homens dentre eles e enviá-los com Paulo e Barnabé a Antioquia, a saber: Judas, chamado Barsabás, e Silas, homens distintos entre os irmãos.'),
('acf','atos',15,23,'E por intermédio deles escreveram o seguinte: Os apóstolos, e os anciãos e os irmãos, aos irmãos dentre os gentios que estão em Antioquia, e Síria e Cilícia, saúde.'),
('acf','atos',15,24,'Porquanto ouvimos que alguns que saíram dentre nós vos perturbaram com palavras, e transtornaram as vossas almas, dizendo que deveis circuncidar-vos e guardar a lei, não lhes tendo nós dado mandamento,'),
('acf','atos',15,25,'Pareceu-nos bem, reunidos concordemente, eleger alguns homens e enviá-los com os nossos amados Barnabé e Paulo,'),
('acf','atos',15,26,'Homens que já expuseram as suas vidas pelo nome de nosso Senhor Jesus Cristo.'),
('acf','atos',15,27,'Enviamos, portanto, Judas e Silas, os quais por palavra vos anunciarão também as mesmas coisas.'),
('acf','atos',15,28,'Na verdade pareceu bem ao Espírito Santo e a nós, não vos impor mais encargo algum, senão estas coisas necessárias:'),
('acf','atos',15,29,'Que vos abstenhais das coisas sacrificadas aos ídolos, e do sangue, e da carne sufocada, e da fornicação, das quais coisas bem fazeis se vos guardardes. Bem vos vá.'),
('acf','atos',15,30,'Tendo eles então se despedido, partiram para Antioquia e, ajuntando a multidão, entregaram a carta.'),
('acf','atos',15,31,'E, quando a leram, alegraram-se pela exortação.'),
('acf','atos',15,32,'Depois Judas e Silas, que também eram profetas, exortaram e confirmaram os irmãos com muitas palavras.'),
('acf','atos',15,33,'E, detendo-se ali algum tempo, os irmãos os deixaram voltar em paz para os apóstolos;'),
('acf','atos',15,34,'Mas pareceu bem a Silas ficar ali.'),
('acf','atos',15,35,'E Paulo e Barnabé ficaram em Antioquia, ensinando e pregando, com muitos outros, a palavra do Senhor.'),
('acf','atos',15,36,'E alguns dias depois, disse Paulo a Barnabé: Tornemos a visitar nossos irmãos por todas as cidades em que já anunciamos a palavra do Senhor, para ver como estão.'),
('acf','atos',15,37,'E Barnabé aconselhava que tomassem consigo a João, chamado Marcos.'),
('acf','atos',15,38,'Mas a Paulo parecia razoável que não tomassem consigo aquele que desde a Panfília se tinha apartado deles e não os acompanhou naquela obra.'),
('acf','atos',15,39,'E tal contenda houve entre eles, que se apartaram um do outro. Barnabé, levando consigo a Marcos, navegou para Chipre.'),
('acf','atos',15,40,'E Paulo, tendo escolhido a Silas, partiu, encomendado pelos irmãos à graça de Deus.'),
('acf','atos',15,41,'E passou pela Síria e Cilícia, confirmando as igrejas.'),
('acf','atos',16,1,'E chegou a Derbe e Listra. E eis que estava ali um certo discípulo por nome Timóteo, filho de uma judia que era crente, mas de pai grego;'),
('acf','atos',16,2,'Do qual davam bom testemunho os irmãos que estavam em Listra e em Icônio.'),
('acf','atos',16,3,'Paulo quis que este fosse com ele; e tomando-o, o circuncidou, por causa dos judeus que estavam naqueles lugares; porque todos sabiam que seu pai era grego.'),
('acf','atos',16,4,'E, quando iam passando pelas cidades, lhes entregavam, para serem observados, os decretos que haviam sido estabelecidos pelos apóstolos e anciãos em Jerusalém.'),
('acf','atos',16,5,'De sorte que as igrejas eram confirmadas na fé, e cada dia cresciam em número.'),
('acf','atos',16,6,'E, passando pela Frígia e pela província da Galácia, foram impedidos pelo Espírito Santo de anunciar a palavra na Ásia.'),
('acf','atos',16,7,'E, quando chegaram a Mísia, intentavam ir para Bitínia, mas o Espírito não lho permitiu.'),
('acf','atos',16,8,'E, tendo passado por Mísia, desceram a Trôade.'),
('acf','atos',16,9,'E Paulo teve de noite uma visão, em que se apresentou um homem da Macedônia, e lhe rogou, dizendo: Passa à Macedônia, e ajuda-nos.'),
('acf','atos',16,10,'E, logo depois desta visão, procuramos partir para a Macedônia, concluindo que o Senhor nos chamava para lhes anunciarmos o evangelho.'),
('acf','atos',16,11,'E, navegando de Trôade, fomos correndo em caminho direito para a Samotrácia e, no dia seguinte, para Neápolis;'),
('acf','atos',16,12,'E dali para Filipos, que é a primeira cidade desta parte da Macedônia, e é uma colônia; e estivemos alguns dias nesta cidade.'),
('acf','atos',16,13,'E no dia de sábado saímos fora das portas, para a beira do rio, onde se costumava fazer oração; e, assentando-nos, falamos às mulheres que ali se ajuntaram.'),
('acf','atos',16,14,'E uma certa mulher, chamada Lídia, vendedora de púrpura, da cidade de Tiatira, e que servia a Deus, nos ouvia, e o Senhor lhe abriu o coração para que estivesse atenta ao que Paulo dizia.'),
('acf','atos',16,15,'E, depois que foi batizada, ela e a sua casa, nos rogou, dizendo: Se haveis julgado que eu seja fiel ao Senhor, entrai em minha casa, e ficai ali. E nos constrangeu a isso.'),
('acf','atos',16,16,'E aconteceu que, indo nós à oração, nos saiu ao encontro uma jovem, que tinha espírito de adivinhação, a qual, adivinhando, dava grande lucro aos seus senhores.'),
('acf','atos',16,17,'Esta, seguindo a Paulo e a nós, clamava, dizendo: Estes homens, que nos anunciam o caminho da salvação, são servos do Deus Altíssimo.'),
('acf','atos',16,18,'E isto fez ela por muitos dias. Mas Paulo, perturbado, voltou-se e disse ao espírito: Em nome de Jesus Cristo, te mando que saias dela. E na mesma hora saiu.'),
('acf','atos',16,19,'E, vendo seus senhores que a esperança do seu lucro estava perdida, prenderam Paulo e Silas, e os levaram à praça, à presença dos magistrados.'),
('acf','atos',16,20,'E, apresentando-os aos magistrados, disseram: Estes homens, sendo judeus, perturbaram a nossa cidade,'),
('acf','atos',16,21,'E nos expõem costumes que não nos é lícito receber nem praticar, visto que somos romanos.'),
('acf','atos',16,22,'E a multidão se levantou unida contra eles, e os magistrados, rasgando-lhes as vestes, mandaram açoitá-los com varas.'),
('acf','atos',16,23,'E, havendo-lhes dado muitos açoites, os lançaram na prisão, mandando ao carcereiro que os guardasse com segurança.'),
('acf','atos',16,24,'O qual, tendo recebido tal ordem, os lançou no cárcere interior, e lhes segurou os pés no tronco.'),
('acf','atos',16,25,'E, perto da meia-noite, Paulo e Silas oravam e cantavam hinos a Deus, e os outros presos os escutavam.'),
('acf','atos',16,26,'E de repente sobreveio um tão grande terremoto, que os alicerces do cárcere se moveram, e logo se abriram todas as portas, e foram soltas as prisões de todos.'),
('acf','atos',16,27,'E, acordando o carcereiro, e vendo abertas as portas da prisão, tirou a espada, e quis matar-se, cuidando que os presos já tinham fugido.'),
('acf','atos',16,28,'Mas Paulo clamou com grande voz, dizendo: Não te faças nenhum mal, que todos aqui estamos.'),
('acf','atos',16,29,'E, pedindo luz, saltou dentro e, todo trêmulo, se prostrou ante Paulo e Silas.'),
('acf','atos',16,30,'E, tirando-os para fora, disse: Senhores, que é necessário que eu faça para me salvar?'),
('acf','atos',16,31,'E eles disseram: Crê no Senhor Jesus Cristo e serás salvo, tu e a tua casa.'),
('acf','atos',16,32,'E lhe pregavam a palavra do Senhor, e a todos os que estavam em sua casa.'),
('acf','atos',16,33,'E, tomando-os ele consigo naquela mesma hora da noite, lavou-lhes os vergões; e logo foi batizado, ele e todos os seus.'),
('acf','atos',16,34,'E, levando-os à sua casa, lhes pôs a mesa; e, na sua crença em Deus, alegrou-se com toda a sua casa.'),
('acf','atos',16,35,'E, sendo já dia, os magistrados mandaram quadrilheiros, dizendo: Soltai aqueles homens.'),
('acf','atos',16,36,'E o carcereiro anunciou a Paulo estas palavras, dizendo: Os magistrados mandaram que vos soltasse; agora, pois, saí e ide em paz.'),
('acf','atos',16,37,'Mas Paulo replicou: Açoitaram-nos publicamente e, sem sermos condenados, sendo homens romanos, nos lançaram na prisão, e agora encobertamente nos lançam fora? Não será assim; mas venham eles mesmos e tirem-nos para fora.'),
('acf','atos',16,38,'E os quadrilheiros foram dizer aos magistrados estas palavras; e eles temeram, ouvindo que eram romanos.'),
('acf','atos',16,39,'E, vindo, lhes dirigiram súplicas; e, tirando-os para fora, lhes pediram que saíssem da cidade.'),
('acf','atos',16,40,'E, saindo da prisão, entraram em casa de Lídia e, vendo os irmãos, os confortaram, e depois partiram.'),
('acf','atos',17,1,'E passando por Anfípolis e Apolônia, chegaram a Tessalônica, onde havia uma sinagoga de judeus.'),
('acf','atos',17,2,'E Paulo, como tinha por costume, foi ter com eles; e por três sábados disputou com eles sobre as Escrituras,'),
('acf','atos',17,3,'Expondo e demonstrando que convinha que o Cristo padecesse e ressuscitasse dentre os mortos. E este Jesus, que vos anuncio, dizia ele, é o Cristo.'),
('acf','atos',17,4,'E alguns deles creram, e ajuntaram-se com Paulo e Silas; e também uma grande multidão de gregos religiosos, e não poucas mulheres principais.'),
('acf','atos',17,5,'Mas os judeus desobedientes, movidos de inveja, tomaram consigo alguns homens perversos, dentre os vadios e, ajuntando o povo, alvoroçaram a cidade, e assaltando a casa de Jasom, procuravam trazê-los para junto do povo.'),
('acf','atos',17,6,'E, não os achando, trouxeram Jasom e alguns irmãos à presença dos magistrados da cidade, clamando: Estes que têm alvoroçado o mundo, chegaram também aqui;'),
('acf','atos',17,7,'Os quais Jasom recolheu; e todos estes procedem contra os decretos de César, dizendo que há outro rei, Jesus.'),
('acf','atos',17,8,'E alvoroçaram a multidão e os principais da cidade, que ouviram estas coisas.'),
('acf','atos',17,9,'Tendo, porém, recebido satisfação de Jasom e dos demais, os soltaram.'),
('acf','atos',17,10,'E logo os irmãos enviaram de noite Paulo e Silas a Beréia; e eles, chegando lá, foram à sinagoga dos judeus.'),
('acf','atos',17,11,'Ora, estes foram mais nobres do que os que estavam em Tessalônica, porque de bom grado receberam a palavra, examinando cada dia nas Escrituras se estas coisas eram assim.'),
('acf','atos',17,12,'De sorte que creram muitos deles, e também mulheres gregas da classe nobre, e não poucos homens.'),
('acf','atos',17,13,'Mas, logo que os judeus de Tessalônica souberam que a palavra de Deus também era anunciada por Paulo em Beréia, foram lá, e excitaram as multidões.'),
('acf','atos',17,14,'No mesmo instante os irmãos mandaram a Paulo que fosse até ao mar, mas Silas e Timóteo ficaram ali.'),
('acf','atos',17,15,'E os que acompanhavam Paulo o levaram até Atenas, e, recebendo ordem para que Silas e Timóteo fossem ter com ele o mais depressa possível, partiram.'),
('acf','atos',17,16,'E, enquanto Paulo os esperava em Atenas, o seu espírito se comovia em si mesmo, vendo a cidade tão entregue à idolatria.'),
('acf','atos',17,17,'De sorte que disputava na sinagoga com os judeus e religiosos, e todos os dias na praça com os que se apresentavam.'),
('acf','atos',17,18,'E alguns dos filósofos epicureus e estóicos contendiam com ele; e uns diziam: Que quer dizer este paroleiro? E outros: Parece que é pregador de deuses estranhos; porque lhes anunciava a Jesus e a ressurreição.'),
('acf','atos',17,19,'E tomando-o, o levaram ao Areópago, dizendo: Poderemos nós saber que nova doutrina é essa de que falas?'),
('acf','atos',17,20,'Pois coisas estranhas nos trazes aos ouvidos; queremos pois saber o que vem a ser isto'),
('acf','atos',17,21,'(Pois todos os atenienses e estrangeiros residentes, de nenhuma outra coisa se ocupavam, senão de dizer e ouvir alguma novidade).'),
('acf','atos',17,22,'E, estando Paulo no meio do Areópago, disse: Homens atenienses, em tudo vos vejo um tanto supersticiosos;'),
('acf','atos',17,23,'Porque, passando eu e vendo os vossos santuários, achei também um altar em que estava escrito: AO DEUS DESCONHECIDO. Esse, pois, que vós honrais, não o conhecendo, é o que eu vos anuncio.'),
('acf','atos',17,24,'O Deus que fez o mundo e tudo que nele há, sendo Senhor do céu e da terra, não habita em templos feitos por mãos de homens;'),
('acf','atos',17,25,'Nem tampouco é servido por mãos de homens, como que necessitando de alguma coisa; pois ele mesmo é quem dá a todos a vida, e a respiração, e todas as coisas;'),
('acf','atos',17,26,'E de um só sangue fez toda a geração dos homens, para habitar sobre toda a face da terra, determinando os tempos já dantes ordenados, e os limites da sua habitação;'),
('acf','atos',17,27,'Para que buscassem ao Senhor, se porventura, tateando, o pudessem achar; ainda que não está longe de cada um de nós;'),
('acf','atos',17,28,'Porque nele vivemos, e nos movemos, e existimos; como também alguns dos vossos poetas disseram: Pois somos também sua geração.'),
('acf','atos',17,29,'Sendo nós, pois, geração de Deus, não havemos de cuidar que a divindade seja semelhante ao ouro, ou à prata, ou à pedra esculpida por artifício e imaginação dos homens.'),
('acf','atos',17,30,'Mas Deus, não tendo em conta os tempos da ignorância, anuncia agora a todos os homens, e em todo o lugar, que se arrependam;'),
('acf','atos',17,31,'Porquanto tem determinado um dia em que com justiça há de julgar o mundo, por meio do homem que destinou; e disso deu certeza a todos, ressuscitando-o dentre os mortos.'),
('acf','atos',17,32,'E, como ouviram falar da ressurreição dos mortos, uns escarneciam, e outros diziam: Acerca disso te ouviremos outra vez.'),
('acf','atos',17,33,'E assim Paulo saiu do meio deles.'),
('acf','atos',17,34,'Todavia, chegando alguns homens a ele, creram; entre os quais foi Dionísio, areopagita, uma mulher por nome Dâmaris, e com eles outros.'),
('acf','atos',18,1,'E depois disto partiu Paulo de Atenas, e chegou a Corinto.'),
('acf','atos',18,2,'E, achando um certo judeu por nome Áqüila, natural do Ponto, que havia pouco tinha vindo da Itália, e Priscila, sua mulher (pois Cláudio tinha mandado que todos os judeus saíssem de Roma), ajuntou-se com eles,'),
('acf','atos',18,3,'E, como era do mesmo ofício, ficou com eles, e trabalhava; pois tinham por ofício fazer tendas.'),
('acf','atos',18,4,'E todos os sábados disputava na sinagoga, e convencia a judeus e gregos.'),
('acf','atos',18,5,'E, quando Silas e Timóteo desceram da Macedônia, foi Paulo impulsionado no espírito, testificando aos judeus que Jesus era o Cristo.'),
('acf','atos',18,6,'Mas, resistindo e blasfemando eles, sacudiu as vestes, e disse-lhes: O vosso sangue seja sobre a vossa cabeça; eu estou limpo, e desde agora parto para os gentios.'),
('acf','atos',18,7,'E, saindo dali, entrou em casa de um homem chamado chamado Justo, que servia a Deus, e cuja casa estava junto da sinagoga.'),
('acf','atos',18,8,'E Crispo, principal da sinagoga, creu no Senhor com toda a sua casa; e muitos dos coríntios, ouvindo-o, creram e foram batizados.'),
('acf','atos',18,9,'E disse o Senhor em visão a Paulo: Não temas, mas fala, e não te cales;'),
('acf','atos',18,10,'Porque eu sou contigo, e ninguém lançará mão de ti para te fazer mal, pois tenho muito povo nesta cidade.'),
('acf','atos',18,11,'E ficou ali um ano e seis meses, ensinando entre eles a palavra de Deus.'),
('acf','atos',18,12,'Mas, sendo Gálio procônsul da Acaia, levantaram-se os judeus concordemente contra Paulo, e o levaram ao tribunal,'),
('acf','atos',18,13,'Dizendo: Este persuade os homens a servir a Deus contra a lei.'),
('acf','atos',18,14,'E, querendo Paulo abrir a boca, disse Gálio aos judeus: Se houvesse, ó judeus, algum agravo ou crime enorme, com razão vos sofreria,'),
('acf','atos',18,15,'Mas, se a questão é de palavras, e de nomes, e da lei que entre vós há, vede-o vós mesmos; porque eu não quero ser juiz dessas coisas.'),
('acf','atos',18,16,'E expulsou-os do tribunal.'),
('acf','atos',18,17,'Então todos os gregos agarraram Sóstenes, principal da sinagoga, e o feriram diante do tribunal; e a Gálio nada destas coisas o incomodava.'),
('acf','atos',18,18,'E Paulo, ficando ainda ali muitos dias, despediu-se dos irmãos, e dali navegou para a Síria, e com ele Priscila e Áqüila, tendo rapado a cabeça em Cencréia, porque tinha voto.'),
('acf','atos',18,19,'E chegou a Éfeso, e deixou-os ali; mas ele, entrando na sinagoga, disputava com os judeus.'),
('acf','atos',18,20,'E, rogando-lhe eles que ficasse por mais algum tempo, não conveio nisso.'),
('acf','atos',18,21,'Antes se despediu deles, dizendo: É-me de todo preciso celebrar a solenidade que vem em Jerusalém; mas querendo Deus, outra vez voltarei a vós. E partiu de Éfeso.'),
('acf','atos',18,22,'E, chegando a Cesaréia, subiu a Jerusalém e, saudando a igreja, desceu a Antioquia.'),
('acf','atos',18,23,'E, estando ali algum tempo, partiu, passando sucessivamente pela província da Galácia e da Frígia, confirmando a todos os discípulos.'),
('acf','atos',18,24,'E chegou a Éfeso um certo judeu chamado Apolo, natural de Alexandria, homem eloqüente e poderoso nas Escrituras.'),
('acf','atos',18,25,'Este era instruído no caminho do Senhor e, fervoroso de espírito, falava e ensinava diligentemente as coisas do Senhor, conhecendo somente o batismo de João.'),
('acf','atos',18,26,'Ele começou a falar ousadamente na sinagoga; e, quando o ouviram Priscila e Aqüila, o levaram consigo e lhe declararam mais precisamente o caminho de Deus.'),
('acf','atos',18,27,'Querendo ele passar à Acaia, o animaram os irmãos, e escreveram aos discípulos que o recebessem; o qual, tendo chegado, aproveitou muito aos que pela graça criam.'),
('acf','atos',18,28,'Porque com grande veemência, convencia publicamente os judeus, mostrando pelas Escrituras que Jesus era o Cristo.'),
('acf','atos',19,1,'E sucedeu que, enquanto Apolo estava em Corinto, Paulo, tendo passado por todas as regiões superiores, chegou a Éfeso; e achando ali alguns discípulos,'),
('acf','atos',19,2,'Disse-lhes: Recebestes vós já o Espírito Santo quando crestes? E eles disseram-lhe: Nós nem ainda ouvimos que haja Espírito Santo.'),
('acf','atos',19,3,'Perguntou-lhes, então: Em que sois batizados então? E eles disseram: No batismo de João.'),
('acf','atos',19,4,'Mas Paulo disse: Certamente João batizou com o batismo de arrependimento, dizendo ao povo que cresse no que após ele havia de vir, isto é, em Jesus Cristo.'),
('acf','atos',19,5,'E os que ouviram foram batizados em nome do Senhor Jesus.'),
('acf','atos',19,6,'E, impondo-lhes Paulo as mãos, veio sobre eles o Espírito Santo; e falavam línguas, e profetizavam.'),
('acf','atos',19,7,'E estes eram, ao todo, uns doze homens.'),
('acf','atos',19,8,'E, entrando na sinagoga, falou ousadamente por espaço de três meses, disputando e persuadindo-os acerca do reino de Deus.'),
('acf','atos',19,9,'Mas, como alguns deles se endurecessem e não obedecessem, falando mal do Caminho perante a multidão, retirou-se deles, e separou os discípulos, disputando todos os dias na escola de um certo Tirano.'),
('acf','atos',19,10,'E durou isto por espaço de dois anos; de tal maneira que todos os que habitavam na Ásia ouviram a palavra do Senhor Jesus, assim judeus como gregos.'),
('acf','atos',19,11,'E Deus pelas mãos de Paulo fazia maravilhas extraordinárias.'),
('acf','atos',19,12,'De sorte que até os lenços e aventais se levavam do seu corpo aos enfermos, e as enfermidades fugiam deles, e os espíritos malignos saíam.'),
('acf','atos',19,13,'E alguns dos exorcistas judeus ambulantes tentavam invocar o nome do Senhor Jesus sobre os que tinham espíritos malignos, dizendo: Esconjuro-vos por Jesus a quem Paulo prega.'),
('acf','atos',19,14,'E os que faziam isto eram sete filhos de Ceva, judeu, principal dos sacerdotes.'),
('acf','atos',19,15,'Respondendo, porém, o espírito maligno, disse: Conheço a Jesus, e bem sei quem é Paulo; mas vós quem sois?'),
('acf','atos',19,16,'E, saltando neles o homem que tinha o espírito maligno, e assenhoreando-se de todos, pôde mais do que eles; de tal maneira que, nus e feridos, fugiram daquela casa.'),
('acf','atos',19,17,'E foi isto notório a todos os que habitavam em Éfeso, tanto judeus como gregos; e caiu temor sobre todos eles, e o nome do Senhor Jesus era engrandecido.'),
('acf','atos',19,18,'E muitos dos que tinham crido vinham, confessando e publicando os seus feitos.'),
('acf','atos',19,19,'Também muitos dos que seguiam artes mágicas trouxeram os seus livros, e os queimaram na presença de todos e, feita a conta do seu preço, acharam que montava a cinqüenta mil peças de prata.'),
('acf','atos',19,20,'Assim a palavra do Senhor crescia poderosamente e prevalecia.'),
('acf','atos',19,21,'E, cumpridas estas coisas, Paulo propôs, em espírito, ir a Jerusalém, passando pela Macedônia e pela Acaia, dizendo: Depois que houver estado ali, importa-me ver também Roma.'),
('acf','atos',19,22,'E, enviando à Macedônia dois daqueles que o serviam, Timóteo e Erasto, ficou ele por algum tempo na Ásia.'),
('acf','atos',19,23,'E, naquele mesmo tempo, houve um não pequeno alvoroço acerca do Caminho.'),
('acf','atos',19,24,'Porque um certo ourives da prata, por nome Demétrio, que fazia de prata nichos de Diana, dava não pouco lucro aos artífices,'),
('acf','atos',19,25,'Aos quais, havendo-os ajuntado com os oficiais de obras semelhantes, disse: Senhores, vós bem sabeis que deste ofício temos a nossa prosperidade;'),
('acf','atos',19,26,'E bem vedes e ouvis que não só em Éfeso, mas até quase em toda a Ásia, este Paulo tem convencido e afastado uma grande multidão, dizendo que não são deuses os que se fazem com as mãos.'),
('acf','atos',19,27,'E não somente há o perigo de que a nossa profissão caia em descrédito, mas também de que o próprio templo da grande deusa Diana seja estimado em nada, vindo a ser destruída a majestade daquela que toda a Ásia e o mundo veneram.'),
('acf','atos',19,28,'E, ouvindo-o, encheram-se de ira, e clamaram, dizendo: Grande é a Diana dos efésios.'),
('acf','atos',19,29,'E encheu-se de confusão toda a cidade e, unânimes, correram ao teatro, arrebatando a Gaio e a Aristarco, macedônios, companheiros de Paulo na viagem.'),
('acf','atos',19,30,'E, querendo Paulo apresentar-se ao povo, não lho permitiram os discípulos.'),
('acf','atos',19,31,'E também alguns dos principais da Ásia, que eram seus amigos, lhe rogaram que não se apresentasse no teatro.'),
('acf','atos',19,32,'Uns, pois, clamavam de uma maneira, outros de outra, porque o ajuntamento era confuso; e os mais deles não sabiam por que causa se tinham ajuntado.'),
('acf','atos',19,33,'Então tiraram Alexandre dentre a multidão, impelindo-o os judeus para diante; e Alexandre, acenando com a mão, queria dar razão disto ao povo.'),
('acf','atos',19,34,'Mas quando conheceram que era judeu, todos unanimemente levantaram a voz, clamando por espaço de quase duas horas: Grande é a Diana dos efésios.'),
('acf','atos',19,35,'Então o escrivão da cidade, tendo apaziguado a multidão, disse: Homens efésios, qual é o homem que não sabe que a cidade dos efésios é a guardadora do templo da grande deusa Diana, e da imagem que desceu de Júpiter?'),
('acf','atos',19,36,'Ora, não podendo isto ser contraditado, convém que vos aplaqueis e nada façais temerariamente;'),
('acf','atos',19,37,'Porque estes homens que aqui trouxestes nem são sacrílegos nem blasfemam da vossa deusa.'),
('acf','atos',19,38,'Mas, se Demétrio e os artífices que estão com ele têm alguma coisa contra alguém, há audiências e há procônsules; que se acusem uns aos outros;'),
('acf','atos',19,39,'E, se alguma outra coisa demandais, averiguar-se-á em legítima assembléia.'),
('acf','atos',19,40,'Na verdade até corremos perigo de que, por hoje, sejamos acusados de sedição, não havendo causa alguma com que possamos justificar este concurso.'),
('acf','atos',19,41,'E, tendo dito isto, despediu a assembléia.'),
('acf','atos',20,1,'E, depois que cessou o alvoroço, Paulo chamou a si os discípulos e, abraçando-os, saiu para a macedônia.'),
('acf','atos',20,2,'E, havendo andado por aquelas terras, exortando-os com muitas palavras, veio à Grécia.'),
('acf','atos',20,3,'E, passando ali três meses, e sendo-lhe pelos judeus postas ciladas, como tivesse de navegar para a Síria, determinou voltar pela macedônia.'),
('acf','atos',20,4,'E acompanhou-o, até à Ásia, Sópater, de Beréia, e, dos de Tessalônica, Aristarco, e Segundo, e Gaio de Derbe, e Timóteo, e, dos da Ásia, Tíquico e Trófimo.'),
('acf','atos',20,5,'Estes, indo adiante, nos esperaram em Trôade.'),
('acf','atos',20,6,'E, depois dos dias dos pães ázimos, navegamos de Filipos, e em cinco dias fomos ter com eles a Trôade, onde estivemos sete dias.'),
('acf','atos',20,7,'E no primeiro dia da semana, ajuntando-se os discípulos para partir o pão, Paulo, que havia de partir no dia seguinte, falava com eles; e prolongou a prática até à meia-noite.'),
('acf','atos',20,8,'E havia muitas luzes no cenáculo onde estavam juntos.'),
('acf','atos',20,9,'E, estando um certo jovem, por nome Eutico, assentado numa janela, caiu do terceiro andar, tomado de um sono profundo que lhe sobreveio durante o extenso discurso de Paulo; e foi levantado morto.'),
('acf','atos',20,10,'Paulo, porém, descendo, inclinou-se sobre ele e, abraçando-o, disse: Não vos perturbeis, que a sua alma nele está.'),
('acf','atos',20,11,'E subindo, e partindo o pão, e comendo, ainda lhes falou largamente até à alvorada; e assim partiu.'),
('acf','atos',20,12,'E levaram vivo o jovem, e ficaram não pouco consolados.'),
('acf','atos',20,13,'Nós, porém, subindo ao navio, navegamos até Assôs, onde devíamos receber a Paulo, porque assim o ordenara, indo ele por terra.'),
('acf','atos',20,14,'E, logo que se ajuntou conosco em Assôs, o recebemos, e fomos a Mitilene.'),
('acf','atos',20,15,'E, navegando dali, chegamos no dia seguinte defronte de Quios, e no outro aportamos a Samos e, ficando em Trogílio, chegamos no dia seguinte a Mileto.'),
('acf','atos',20,16,'Porque já Paulo tinha determinado passar ao largo de Éfeso, para não gastar tempo na Ásia. Apressava-se, pois, para estar, se lhe fosse possível, em Jerusalém no dia de Pentecostes.'),
('acf','atos',20,17,'E de Mileto mandou a Éfeso, a chamar os anciãos da igreja.'),
('acf','atos',20,18,'E, logo que chegaram junto dele, disse-lhes: Vós bem sabeis, desde o primeiro dia em que entrei na Ásia, como em todo esse tempo me portei no meio de vós,'),
('acf','atos',20,19,'Servindo ao Senhor com toda a humildade, e com muitas lágrimas e tentações, que pelas ciladas dos judeus me sobrevieram;'),
('acf','atos',20,20,'Como nada, que útil seja, deixei de vos anunciar, e ensinar publicamente e pelas casas,'),
('acf','atos',20,21,'Testificando, tanto aos judeus como aos gregos, a conversão a Deus, e a fé em nosso Senhor Jesus Cristo.'),
('acf','atos',20,22,'E agora, eis que, ligado eu pelo espírito, vou para Jerusalém, não sabendo o que lá me há de acontecer,'),
('acf','atos',20,23,'Senão o que o Espírito Santo de cidade em cidade me revela, dizendo que me esperam prisões e tribulações.'),
('acf','atos',20,24,'Mas de nada faço questão, nem tenho a minha vida por preciosa, contanto que cumpra com alegria a minha carreira, e o ministério que recebi do Senhor Jesus, para dar testemunho do evangelho da graça de Deus.'),
('acf','atos',20,25,'E agora, na verdade, sei que todos vós, por quem passei pregando o reino de Deus, não vereis mais o meu rosto.'),
('acf','atos',20,26,'Portanto, no dia de hoje, vos protesto que estou limpo do sangue de todos.'),
('acf','atos',20,27,'Porque nunca deixei de vos anunciar todo o conselho de Deus.'),
('acf','atos',20,28,'Olhai, pois, por vós, e por todo o rebanho sobre que o Espírito Santo vos constituiu bispos, para apascentardes a igreja de Deus, que ele resgatou com seu próprio sangue.'),
('acf','atos',20,29,'Porque eu sei isto que, depois da minha partida, entrarão no meio de vós lobos cruéis, que não pouparão ao rebanho;'),
('acf','atos',20,30,'E que de entre vós mesmos se levantarão homens que falarão coisas perversas, para atraírem os discípulos após si.'),
('acf','atos',20,31,'Portanto, vigiai, lembrando-vos de que durante três anos, não cessei, noite e dia, de admoestar com lágrimas a cada um de vós.'),
('acf','atos',20,32,'Agora, pois, irmãos, encomendo-vos a Deus e à palavra da sua graça; a ele que é poderoso para vos edificar e dar herança entre todos os santificados.'),
('acf','atos',20,33,'De ninguém cobicei a prata, nem o ouro, nem o vestuário.'),
('acf','atos',20,34,'Sim, vós mesmos sabeis que para o que me era necessário a mim, e aos que estão comigo, estas mãos me serviram.'),
('acf','atos',20,35,'Tenho-vos mostrado em tudo que, trabalhando assim, é necessário auxiliar os enfermos, e recordar as palavras do Senhor Jesus, que disse: Mais bem-aventurada coisa é dar do que receber.'),
('acf','atos',20,36,'E, havendo dito isto, pôs-se de joelhos, e orou com todos eles.'),
('acf','atos',20,37,'E levantou-se um grande pranto entre todos e, lançando-se ao pescoço de Paulo, o beijavam,'),
('acf','atos',20,38,'Entristecendo-se muito, principalmente pela palavra que dissera, que não veriam mais o seu rosto. E acompanharam-no até o navio.'),
('acf','atos',21,1,'E aconteceu que, separando-nos deles, navegamos e fomos correndo caminho direito, e chegamos a Cós, e no dia seguinte a Rodes, de onde passamos a Pátara.'),
('acf','atos',21,2,'E, achando um navio, que ia para a Fenícia, embarcamos nele, e partimos.'),
('acf','atos',21,3,'E, indo já à vista de Chipre, deixando-a à esquerda, navegamos para a Síria e chegamos a Tiro; porque o navio havia de ser descarregado ali.'),
('acf','atos',21,4,'E, achando discípulos, ficamos ali sete dias; e eles pelo Espírito diziam a Paulo que não subisse a Jerusalém.'),
('acf','atos',21,5,'E, havendo passado ali aqueles dias, saímos, e seguimos nosso caminho, acompanhando-nos todos, com suas mulheres e filhos até fora da cidade; e, postos de joelhos na praia, oramos.'),
('acf','atos',21,6,'E, despedindo-nos uns dos outros, subimos ao navio; e eles voltaram para suas casas.'),
('acf','atos',21,7,'E nós, concluída a navegação de Tiro, viemos a Ptolemaida; e, havendo saudado os irmãos, ficamos com eles um dia.'),
('acf','atos',21,8,'E no dia seguinte, partindo dali Paulo, e nós que com ele estávamos, chegamos a Cesaréia; e, entrando em casa de Filipe, o evangelista, que era um dos sete, ficamos com ele.'),
('acf','atos',21,9,'E tinha este quatro filhas virgens, que profetizavam.'),
('acf','atos',21,10,'E, demorando-nos ali por muitos dias, chegou da Judéia um profeta, por nome Ágabo;'),
('acf','atos',21,11,'E, vindo ter conosco, tomou a cinta de Paulo, e ligando-se os seus próprios pés e mãos, disse: Isto diz o Espírito Santo: Assim ligarão os judeus em Jerusalém o homem de quem é esta cinta, e o entregarão nas mãos dos gentios.'),
('acf','atos',21,12,'E, ouvindo nós isto, rogamos-lhe, tanto nós como os que eram daquele lugar, que não subisse a Jerusalém.'),
('acf','atos',21,13,'Mas Paulo respondeu: Que fazeis vós, chorando e magoando-me o coração? Porque eu estou pronto não só a ser ligado, mas ainda a morrer em Jerusalém pelo nome do Senhor Jesus.'),
('acf','atos',21,14,'E, como não podíamos convencê-lo, nos aquietamos, dizendo: Faça-se a vontade do Senhor.'),
('acf','atos',21,15,'E depois daqueles dias, havendo feito os nossos preparativos, subimos a Jerusalém.'),
('acf','atos',21,16,'E foram também conosco alguns discípulos de Cesaréia, levando consigo um certo Mnasom, chíprio, discípulo antigo, com quem havíamos de hospedar-nos.'),
('acf','atos',21,17,'E, logo que chegamos a Jerusalém, os irmãos nos receberam de muito boa vontade.'),
('acf','atos',21,18,'E no dia seguinte, Paulo entrou conosco em casa de Tiago, e todos os anciãos vieram ali.'),
('acf','atos',21,19,'E, havendo-os saudado, contou-lhes por miúdo o que por seu ministério Deus fizera entre os gentios.'),
('acf','atos',21,20,'E, ouvindo-o eles, glorificaram ao Senhor, e disseram-lhe: Bem vês, irmão, quantos milhares de judeus há que crêem, e todos são zeladores da lei.'),
('acf','atos',21,21,'E já acerca de ti foram informados de que ensinas todos os judeus que estão entre os gentios a apartarem-se de Moisés, dizendo que não devem circuncidar seus filhos, nem andar segundo o costume da lei.'),
('acf','atos',21,22,'Que faremos pois? em todo o caso é necessário que a multidão se ajunte; porque terão ouvido que já és vindo.'),
('acf','atos',21,23,'Faze, pois, isto que te dizemos: Temos quatro homens que fizeram voto.'),
('acf','atos',21,24,'Toma estes contigo, e santifica-te com eles, e faze por eles os gastos para que rapem a cabeça, e todos ficarão sabendo que nada há daquilo de que foram informados acerca de ti, mas que também tu mesmo andas guardando a lei.'),
('acf','atos',21,25,'Todavia, quanto aos que creem dos gentios, já nós havemos escrito, e achado por bem, que nada disto observem; mas que só se guardem do que se sacrifica aos ídolos, e do sangue, e do sufocado e da fornicação.'),
('acf','atos',21,26,'Então Paulo, tomando consigo aqueles homens, entrou no dia seguinte no templo, já santificado com eles, anunciando serem já cumpridos os dias da purificação; e ficou ali até se oferecer por cada um deles a oferta.'),
('acf','atos',21,27,'E quando os sete dias estavam quase a terminar, os judeus da Ásia, vendo-o no templo, alvoroçaram todo o povo e lançaram mão dele,'),
('acf','atos',21,28,'Clamando: Homens israelitas, acudi; este é o homem que por todas as partes ensina a todos contra o povo e contra a lei, e contra este lugar; e, demais disto, introduziu também no templo os gregos, e profanou este santo lugar.'),
('acf','atos',21,29,'Porque tinham visto com ele na cidade a Trófimo de Éfeso, o qual pensavam que Paulo introduzira no templo.'),
('acf','atos',21,30,'E alvoroçou-se toda a cidade, e houve grande concurso de povo; e, pegando Paulo, o arrastaram para fora do templo, e logo as portas se fecharam.'),
('acf','atos',21,31,'E, procurando eles matá-lo, chegou ao tribuno da coorte o aviso de que Jerusalém estava toda em confusão;'),
('acf','atos',21,32,'O qual, tomando logo consigo soldados e centuriões, correu para eles. E, quando viram o tribuno e os soldados, cessaram de ferir a Paulo.'),
('acf','atos',21,33,'Então, aproximando-se o tribuno, o prendeu e o mandou atar com duas cadeias, e lhe perguntou quem era e o que tinha feito.'),
('acf','atos',21,34,'E na multidão uns clamavam de uma maneira, outros de outra; mas, como nada podia saber ao certo, por causa do alvoroço, mandou conduzi-lo para a fortaleza.'),
('acf','atos',21,35,'E sucedeu que, chegando às escadas, os soldados tiveram de lhe pegar por causa da violência da multidão.'),
('acf','atos',21,36,'Porque a multidão do povo o seguia, clamando: Mata-o!'),
('acf','atos',21,37,'E, quando iam a introduzir Paulo na fortaleza, disse Paulo ao tribuno: É-me permitido dizer-te alguma coisa? E ele disse: Sabes o grego?'),
('acf','atos',21,38,'Não és tu porventura aquele egípcio que antes destes dias fez uma sedição e levou ao deserto quatro mil salteadores?'),
('acf','atos',21,39,'Mas Paulo lhe disse: Na verdade que sou um homem judeu, cidadão de Tarso, cidade não pouco célebre na Cilícia; rogo-te, porém, que me permitas falar ao povo.'),
('acf','atos',21,40,'E, havendo-lho permitido, Paulo, pondo-se em pé nas escadas, fez sinal com a mão ao povo; e, feito grande silêncio, falou-lhes em língua hebraica, dizendo:'),
('acf','atos',22,1,'Homens, irmàos e pais, ouvi agora a minha defesa perante vós'),
('acf','atos',22,2,'(E, quando ouviram falar-lhes em língua hebraica, maior silêncio guardaram). E disse:'),
('acf','atos',22,3,'Quanto a mim, sou judeu, nascido em Tarso da Cilícia, e nesta cidade criado aos pés de Gamaliel, instruído conforme a verdade da lei de nossos pais, zelador de Deus, como todos vós hoje sois.'),
('acf','atos',22,4,'E persegui este caminho até à morte, prendendo, e pondo em prisões, tanto homens como mulheres,'),
('acf','atos',22,5,'Como também o sumo sacerdote me é testemunha, e todo o conselho dos anciãos. E, recebendo destes cartas para os irmãos, fui a Damasco, para trazer maniatados para Jerusalém aqueles que ali estivessem, a fim de que fossem castigados.'),
('acf','atos',22,6,'Ora, aconteceu que, indo eu já de caminho, e chegando perto de Damasco, quase ao meio-dia, de repente me rodeou uma grande luz do céu.'),
('acf','atos',22,7,'E caí por terra, e ouvi uma voz que me dizia: Saulo, Saulo, por que me persegues?'),
('acf','atos',22,8,'E eu respondi: Quem és, Senhor? E disse-me: Eu sou Jesus Nazareno, a quem tu persegues.'),
('acf','atos',22,9,'E os que estavam comigo viram, em verdade, a luz, e se atemorizaram muito, mas não ouviram a voz daquele que falava comigo.'),
('acf','atos',22,10,'Então disse eu: Senhor, que farei? E o Senhor disse-me: Levanta-te, e vai a Damasco, e ali se te dirá tudo o que te é ordenado fazer.'),
('acf','atos',22,11,'E, como eu não via, por causa do esplendor daquela luz, fui levado pela mão dos que estavam comigo, e cheguei a Damasco.'),
('acf','atos',22,12,'E um certo Ananias, homem piedoso conforme a lei, que tinha bom testemunho de todos os judeus que ali moravam,'),
('acf','atos',22,13,'Vindo ter comigo, e apresentando-se, disse-me: Saulo, irmão, recobra a vista. E naquela mesma hora o vi.'),
('acf','atos',22,14,'E ele disse: O Deus de nossos pais de antemão te designou para que conheças a sua vontade, e vejas aquele Justo e ouças a voz da sua boca.'),
('acf','atos',22,15,'Porque hás de ser sua testemunha para com todos os homens do que tens visto e ouvido.'),
('acf','atos',22,16,'E agora por que te deténs? Levanta-te, e batiza-te, e lava os teus pecados, invocando o nome do Senhor.'),
('acf','atos',22,17,'E aconteceu que, tornando eu para Jerusalém, quando orava no templo, fui arrebatado para fora de mim.'),
('acf','atos',22,18,'E vi aquele que me dizia: Dá-te pressa e sai apressadamente de Jerusalém; porque não receberão o teu testemunho acerca de mim.'),
('acf','atos',22,19,'E eu disse: Senhor, eles bem sabem que eu lançava na prisão e açoitava nas sinagogas os que criam em ti.'),
('acf','atos',22,20,'E quando o sangue de Estêvão, tua testemunha, se derramava, também eu estava presente, e consentia na sua morte, e guardava as capas dos que o matavam.'),
('acf','atos',22,21,'E disse-me: Vai, porque hei de enviar-te aos gentios de longe.'),
('acf','atos',22,22,'E ouviram-no até esta palavra, e levantaram a voz, dizendo: Tira da terra um tal homem, porque não convém que viva.'),
('acf','atos',22,23,'E, clamando eles, e arrojando de si as vestes, e lançando pó para o ar,'),
('acf','atos',22,24,'O tribuno mandou que o levassem para a fortaleza, dizendo que o examinassem com açoites, para saber por que causa assim clamavam contra ele.'),
('acf','atos',22,25,'E, quando o estavam atando com correias, disse Paulo ao centurião que ali estava: É-vos lícito açoitar um romano, sem ser condenado?'),
('acf','atos',22,26,'E, ouvindo isto, o centurião foi, e anunciou ao tribuno, dizendo: Vê o que vais fazer, porque este homem é romano.'),
('acf','atos',22,27,'E, vindo o tribuno, disse-lhe: Dize-me, és tu romano? E ele disse: Sim.'),
('acf','atos',22,28,'E respondeu o tribuno: Eu com grande soma de dinheiro alcancei este direito de cidadão. Paulo disse: Mas eu o sou de nascimento.'),
('acf','atos',22,29,'E logo dele se apartaram os que o haviam de examinar; e até o tribuno teve temor, quando soube que era romano, visto que o tinha ligado.'),
('acf','atos',22,30,'E no dia seguinte, querendo saber ao certo a causa por que era acusado pelos judeus, soltou-o das prisões, e mandou vir o principais dos sacerdotes, e todo o seu conselho; e, trazendo Paulo, o apresentou diante deles.'),
('acf','atos',23,1,'E, pondo Paulo os olhos no conselho, disse: Homens irmãos, até ao dia de hoje tenho andado diante de Deus com toda a boa consciência.'),
('acf','atos',23,2,'Mas o sumo sacerdote, Ananias, mandou aos que estavam junto dele que o ferissem na boca.'),
('acf','atos',23,3,'Então Paulo lhe disse: Deus te ferirá, parede branqueada; tu estás aqui assentado para julgar-me conforme a lei, e contra a lei me mandas ferir?'),
('acf','atos',23,4,'E os que ali estavam disseram: Injurias o sumo sacerdote de Deus?'),
('acf','atos',23,5,'E Paulo disse: Não sabia, irmãos, que era o sumo sacerdote; porque está escrito: Não dirás mal do príncipe do teu povo.'),
('acf','atos',23,6,'E Paulo, sabendo que uma parte era de saduceus e outra de fariseus, clamou no conselho: Homens irmãos, eu sou fariseu, filho de fariseu; no tocante à esperança e ressurreição dos mortos sou julgado.'),
('acf','atos',23,7,'E, havendo dito isto, houve dissensão entre os fariseus e saduceus; e a multidão se dividiu.'),
('acf','atos',23,8,'Porque os saduceus dizem que não há ressurreição, nem anjo, nem espírito; mas os fariseus reconhecem uma e outra coisa.'),
('acf','atos',23,9,'E originou-se um grande clamor; e, levantando-se os escribas da parte dos fariseus, contendiam, dizendo: Nenhum mal achamos neste homem, e, se algum espírito ou anjo lhe falou, não lutemos contra Deus.'),
('acf','atos',23,10,'E, havendo grande dissensão, o tribuno, temendo que Paulo fosse despedaçado por eles, mandou descer a soldadesca, para que o tirassem do meio deles, e o levassem para a fortaleza.'),
('acf','atos',23,11,'E na noite seguinte, apresentando-se-lhe o Senhor, disse: Paulo, tem ânimo; porque, como de mim testificaste em Jerusalém, assim importa que testifiques também em Roma.'),
('acf','atos',23,12,'E, quando já era dia, alguns dos judeus fizeram uma conspiração, e juraram, dizendo que não comeriam nem beberiam enquanto não matassem a Paulo.'),
('acf','atos',23,13,'E eram mais de quarenta os que fizeram esta conjuração.'),
('acf','atos',23,14,'E estes foram ter com os principais dos sacerdotes e anciãos, e disseram: Conjuramo-nos, sob pena de maldição, a nada provarmos até que matemos a Paulo.'),
('acf','atos',23,15,'Agora, pois, vós, com o conselho, rogai ao tribuno que vo-lo traga amanhã, como que querendo saber mais alguma coisa de seus negócios, e, antes que chegue, estaremos prontos para o matar.'),
('acf','atos',23,16,'E o filho da irmã de Paulo, tendo ouvido acerca desta cilada, foi, e entrou na fortaleza, e o anunciou a Paulo.'),
('acf','atos',23,17,'E Paulo, chamando a si um dos centuriões, disse: Leva este jovem ao tribuno, porque tem alguma coisa que lhe comunicar.'),
('acf','atos',23,18,'Tomando-o ele, pois, o levou ao tribuno, e disse: O preso Paulo, chamando-me a si, rogou-me que trouxesse este jovem, que tem alguma coisa para dizer-te.'),
('acf','atos',23,19,'E o tribuno, tomando-o pela mão, e pondo-se à parte, perguntou-lhe em particular: Que tens que me contar?'),
('acf','atos',23,20,'E disse ele: Os judeus se concertaram rogar-te que amanhã leves Paulo ao conselho, como que tendo de inquirir dele mais alguma coisa ao certo.'),
('acf','atos',23,21,'Mas tu não os creias; porque mais de quarenta homens de entre eles lhe andam armando ciladas; os quais se obrigaram, sob pena de maldição, a não comer nem beber até que o tenham morto; e já estão apercebidos, esperando de ti promessa.'),
('acf','atos',23,22,'Então o tribuno despediu o jovem, mandando-lhe que a ninguém dissesse que lhe havia contado aquilo.'),
('acf','atos',23,23,'E, chamando dois centuriões, lhes disse: Aprontai para as três horas da noite duzentos soldados, e setenta de cavalaria, e duzentos archeiros para irem até Cesaréia;'),
('acf','atos',23,24,'E aparelhai animais, para que, pondo neles a Paulo, o levem salvo ao presidente Félix.'),
('acf','atos',23,25,'E escreveu uma carta, que continha isto:'),
('acf','atos',23,26,'Cláudio Lísias, a Félix, potentíssimo presidente, saúde.'),
('acf','atos',23,27,'Esse homem foi preso pelos judeus; e, estando já a ponto de ser morto por eles, sobrevim eu com a soldadesca, e o livrei, informado de que era romano.'),
('acf','atos',23,28,'E, querendo saber a causa por que o acusavam, o levei ao seu conselho.'),
('acf','atos',23,29,'E achei que o acusavam de algumas questões da sua lei; mas que nenhum crime havia nele digno de morte ou de prisão.'),
('acf','atos',23,30,'E, sendo-me notificado que os judeus haviam de armar ciladas a esse homem, logo to enviei, mandando também aos acusadores que perante ti digam o que tiverem contra ele. Passa bem.'),
('acf','atos',23,31,'Tomando, pois, os soldados a Paulo, como lhe fora mandado, o trouxeram de noite a Antipátride.'),
('acf','atos',23,32,'E no dia seguinte, deixando aos de cavalo irem com ele, tornaram à fortaleza.'),
('acf','atos',23,33,'Os quais, logo que chegaram a Cesaréia, e entregaram a carta ao presidente, lhe apresentaram Paulo.'),
('acf','atos',23,34,'E o presidente, lida a carta, perguntou de que província era; e, sabendo que era da Cilícia,'),
('acf','atos',23,35,'Disse: Ouvir-te-ei, quando também aqui vierem os teus acusadores. E mandou que o guardassem no pretório de Herodes.'),
('acf','atos',24,1,'E, cinco dias depois, o sumo sacerdote Ananias desceu com os anciãos, e um certo Tértulo, orador, os quais compareceram perante o presidente contra Paulo.'),
('acf','atos',24,2,'E, sendo chamado, Tértulo começou a acusá-lo, dizendo: Visto como por ti temos tanta paz e por tua prudência se fazem a este povo muitos e louváveis serviços,'),
('acf','atos',24,3,'Sempre e em todo o lugar, ó potentíssimo Félix, com todo o agradecimento o queremos reconhecer.'),
('acf','atos',24,4,'Mas, para que não te detenha muito, rogo-te que, conforme a tua eqüidade, nos ouças por pouco tempo.'),
('acf','atos',24,5,'Temos achado que este homem é uma peste, e promotor de sedições entre todos os judeus, por todo o mundo; e o principal defensor da seita dos nazarenos;'),
('acf','atos',24,6,'O qual intentou também profanar o templo; e nós o prendemos, e conforme a nossa lei o quisemos julgar.'),
('acf','atos',24,7,'Mas, sobrevindo o tribuno Lísias, no-lo tirou de entre as mãos com grande violência,'),
('acf','atos',24,8,'Mandando aos seus acusadores que viessem a ti; e dele tu mesmo, examinando-o, poderás entender tudo o de que o acusamos.'),
('acf','atos',24,9,'E também os judeus consentiam, dizendo serem estas coisas assim.'),
('acf','atos',24,10,'Paulo, porém, fazendo-lhe o presidente sinal que falasse, respondeu: Porque sei que já vai para muitos anos que desta nação és juiz, com tanto melhor ânimo respondo por mim.'),
('acf','atos',24,11,'Pois bem podes saber que não há mais de doze dias que subi a Jerusalém a adorar;'),
('acf','atos',24,12,'E não me acharam no templo falando com alguém, nem amotinando o povo nas sinagogas, nem na cidade.'),
('acf','atos',24,13,'Nem tampouco podem provar as coisas de que agora me acusam.'),
('acf','atos',24,14,'Mas confesso-te isto que, conforme aquele caminho que chamam seita, assim sirvo ao Deus de nossos pais, crendo tudo quanto está escrito na lei e nos profetas.'),
('acf','atos',24,15,'Tendo esperança em Deus, como estes mesmos também esperam, de que há de haver ressurreição de mortos, assim dos justos como dos injustos.'),
('acf','atos',24,16,'E por isso procuro sempre ter uma consciência sem ofensa, tanto para com Deus como para com os homens.'),
('acf','atos',24,17,'Ora, muitos anos depois, vim trazer à minha nação esmolas e ofertas.'),
('acf','atos',24,18,'Nisto me acharam já santificado no templo, não em ajuntamentos, nem com alvoroços, uns certos judeus da Ásia,'),
('acf','atos',24,19,'Os quais convinha que estivessem presentes perante ti, e me acusassem, se alguma coisa contra mim tivessem.'),
('acf','atos',24,20,'Ou digam estes mesmos, se acharam em mim alguma iniqüidade, quando compareci perante o conselho,'),
('acf','atos',24,21,'A não ser estas palavras que, estando entre eles, clamei: Hoje sou julgado por vós acerca da ressurreição dos mortos.'),
('acf','atos',24,22,'Então Félix, havendo ouvido estas coisas, lhes pôs dilação, dizendo: Havendo-me informado melhor deste Caminho, quando o tribuno Lísias tiver descido, então tomarei inteiro conhecimento dos vossos negócios.'),
('acf','atos',24,23,'E mandou ao centurião que o guardasse em prisão, tratando-o com brandura, e que a ninguém dos seus proibisse servi-lo ou vir ter com ele.'),
('acf','atos',24,24,'E alguns dias depois, vindo Félix com sua mulher Drusila, que era judia, mandou chamar a Paulo, e ouviu-o acerca da fé em Cristo.'),
('acf','atos',24,25,'E, tratando ele da justiça, e da temperança, e do juízo vindouro, Félix, espavorido, respondeu: Por agora vai-te, e em tendo oportunidade te chamarei.'),
('acf','atos',24,26,'Esperando ao mesmo tempo que Paulo lhe desse dinheiro, para que o soltasse; pelo que também muitas vezes o mandava chamar, e falava com ele.'),
('acf','atos',24,27,'Mas, passados dois anos, Félix teve por sucessor a Pórcio Festo; e, querendo Félix comprazer aos judeus, deixou a Paulo preso.'),
('acf','atos',25,1,'Entrando, pois, Festo na província, subiu dali a três dias de Cesaréia a Jerusalém.'),
('acf','atos',25,2,'E o sumo sacerdote e os principais dos judeus compareceram perante ele contra Paulo, e lhe rogaram,'),
('acf','atos',25,3,'Pedindo como favor contra ele que o fizesse vir a Jerusalém, armando ciladas para o matarem no caminho.'),
('acf','atos',25,4,'Mas Festo respondeu que Paulo estava guardado em Cesaréia, e que ele brevemente partiria para lá.'),
('acf','atos',25,5,'Os que, pois, disse, dentre vós, têm poder, desçam comigo e, se neste homem houver algum crime, acusem-no.'),
('acf','atos',25,6,'E, havendo-se demorado entre eles mais de dez dias, desceu a Cesaréia; e no dia seguinte, assentando-se no tribunal, mandou que trouxessem Paulo.'),
('acf','atos',25,7,'E, chegando ele, rodearam-no os judeus que haviam descido de Jerusalém, trazendo contra Paulo muitas e graves acusações, que não podiam provar.'),
('acf','atos',25,8,'Mas ele, em sua defesa, disse: Eu não pequei em coisa alguma contra a lei dos judeus, nem contra o templo, nem contra César.'),
('acf','atos',25,9,'Todavia Festo, querendo comprazer aos judeus, respondendo a Paulo, disse: Queres tu subir a Jerusalém, e ser lá perante mim julgado acerca destas coisas?'),
('acf','atos',25,10,'Mas Paulo disse: Estou perante o tribunal de César, onde convém que seja julgado; não fiz agravo algum aos judeus, como tu muito bem sabes.'),
('acf','atos',25,11,'Se fiz algum agravo, ou cometi alguma coisa digna de morte, não recuso morrer; mas, se nada há das coisas de que estes me acusam, ninguém me pode entregar a eles; apelo para César.'),
('acf','atos',25,12,'Então Festo, tendo falado com o conselho, respondeu: Apelaste para César? para César irás.'),
('acf','atos',25,13,'E, passados alguns dias, o rei Agripa e Berenice vieram a Cesaréia, a saudar Festo.'),
('acf','atos',25,14,'E, como ali ficassem muitos dias, Festo contou ao rei os negócios de Paulo, dizendo: Um certo homem foi deixado por Félix aqui preso,'),
('acf','atos',25,15,'Por cujo respeito os principais dos sacerdotes e os anciãos dos judeus, estando eu em Jerusalém, compareceram perante mim, pedindo sentença contra ele.'),
('acf','atos',25,16,'Aos quais respondi não ser costume dos romanos entregar algum homem à morte, sem que o acusado tenha presentes os seus acusadores, e possa defender-se da acusação.'),
('acf','atos',25,17,'De sorte que, chegando eles aqui juntos, no dia seguinte, sem fazer dilação alguma, assentado no tribunal, mandei que trouxessem o homem.'),
('acf','atos',25,18,'Acerca do qual, estando presentes os acusadores, nenhuma coisa apontaram daquelas que eu suspeitava.'),
('acf','atos',25,19,'Tinham, porém, contra ele algumas questões acerca da sua superstição, e de um tal Jesus, morto, que Paulo afirmava viver.'),
('acf','atos',25,20,'E, estando eu perplexo acerca da inquirição desta causa, disse se queria ir a Jerusalém, e lá ser julgado acerca destas coisas.'),
('acf','atos',25,21,'E, apelando Paulo para que fosse reservado ao conhecimento de Augusto, mandei que o guardassem até que o envie a César.'),
('acf','atos',25,22,'Então Agripa disse a Festo: Bem quisera eu também ouvir esse homem. E ele disse: Amanhã o ouvirás.'),
('acf','atos',25,23,'E, no dia seguinte, vindo Agripa e Berenice, com muito aparato, entraram no auditório com os tribunos e homens principais da cidade, sendo trazido Paulo por mandado de Festo.'),
('acf','atos',25,24,'E Festo disse: Rei Agripa, e todos os senhores que estais presentes conosco; aqui vedes um homem de quem toda a multidão dos judeus me tem falado, tanto em Jerusalém como aqui, clamando que não convém que viva mais.'),
('acf','atos',25,25,'Mas, achando eu que nenhuma coisa digna de morte fizera, e apelando ele mesmo também para Augusto, tenho determinado enviar-lho.'),
('acf','atos',25,26,'Do qual não tenho coisa alguma certa que escreva ao meu senhor, e por isso perante vós o trouxe, principalmente perante ti, ó rei Agripa, para que, depois de interrogado, tenha alguma coisa que escrever.'),
('acf','atos',25,27,'Porque me parece contra a razão enviar um preso, e não notificar contra ele as acusações.'),
('acf','atos',26,1,'Depois Agripa disse a Paulo: É permitido que te defendas. Então Paulo, estendendo a mão em sua defesa, respondeu:'),
('acf','atos',26,2,'Tenho-me por feliz, ó rei Agripa, de que perante ti me haja hoje de defender de todas as coisas de que sou acusado pelos judeus;'),
('acf','atos',26,3,'Mormente sabendo eu que tens conhecimento de todos os costumes e questões que há entre os judeus; por isso te rogo que me ouças com paciência.'),
('acf','atos',26,4,'Quanto à minha vida, desde a mocidade, como decorreu desde o princípio entre os da minha nação, em Jerusalém, todos os judeus a conhecem,'),
('acf','atos',26,5,'Sabendo de mim desde o princípio (se o quiserem testificar), que, conforme a mais severa seita da nossa religião, vivi fariseu.'),
('acf','atos',26,6,'E agora pela esperança da promessa que por Deus foi feita a nossos pais estou aqui e sou julgado.'),
('acf','atos',26,7,'À qual as nossas doze tribos esperam chegar, servindo a Deus continuamente, noite e dia. Por esta esperança, ó rei Agripa, eu sou acusado pelos judeus.'),
('acf','atos',26,8,'Pois quê? julga-se coisa incrível entre vós que Deus ressuscite os mortos?'),
('acf','atos',26,9,'Bem tinha eu imaginado que contra o nome de Jesus Nazareno devia eu praticar muitos atos;'),
('acf','atos',26,10,'O que também fiz em Jerusalém. E, havendo recebido autorização dos principais dos sacerdotes, encerrei muitos dos santos nas prisões; e quando os matavam eu dava o meu voto contra eles.'),
('acf','atos',26,11,'E, castigando-os muitas vezes por todas as sinagogas, os obriguei a blasfemar. E, enfurecido demasiadamente contra eles, até nas cidades estranhas os persegui.'),
('acf','atos',26,12,'Sobre o que, indo então a Damasco, com poder e comissão dos principais dos sacerdotes,'),
('acf','atos',26,13,'Ao meio-dia, ó rei, vi no caminho uma luz do céu, que excedia o esplendor do sol, cuja claridade me envolveu a mim e aos que iam comigo.'),
('acf','atos',26,14,'E, caindo nós todos por terra, ouvi uma voz que me falava, e em língua hebraica dizia: Saulo, Saulo, por que me persegues? Dura coisa te é recalcitrar contra os aguilhões.'),
('acf','atos',26,15,'E disse eu: Quem és, Senhor? E ele respondeu: Eu sou Jesus, a quem tu persegues;'),
('acf','atos',26,16,'Mas levanta-te e põe-te sobre teus pés, porque te apareci por isto, para te pôr por ministro e testemunha tanto das coisas que tens visto como daquelas pelas quais te aparecerei ainda;'),
('acf','atos',26,17,'Livrando-te deste povo, e dos gentios, a quem agora te envio,'),
('acf','atos',26,18,'Para lhes abrires os olhos, e das trevas os converteres à luz, e do poder de Satanás a Deus; a fim de que recebam a remissão de pecados, e herança entre os que são santificados pela fé em mim.'),
('acf','atos',26,19,'Por isso, ó rei Agripa, não fui desobediente à visão celestial.'),
('acf','atos',26,20,'Antes anunciei primeiramente aos que estão em Damasco e em Jerusalém, e por toda a terra da Judéia, e aos gentios, que se emendassem e se convertessem a Deus, fazendo obras dignas de arrependimento.'),
('acf','atos',26,21,'Por causa disto os judeus lançaram mão de mim no templo, e procuraram matar-me.'),
('acf','atos',26,22,'Mas, alcançando socorro de Deus, ainda até ao dia de hoje permaneço dando testemunho tanto a pequenos como a grandes, não dizendo nada mais do que o que os profetas e Moisés disseram que devia acontecer,'),
('acf','atos',26,23,'Isto é, que o Cristo devia padecer, e sendo o primeiro da ressurreição dentre os mortos, devia anunciar a luz a este povo e aos gentios.'),
('acf','atos',26,24,'E, dizendo ele isto em sua defesa, disse Festo em alta voz: Estás louco, Paulo; as muitas letras te fazem delirar.'),
('acf','atos',26,25,'Mas ele disse: Não deliro, ó potentíssimo Festo; antes digo palavras de verdade e de um são juízo.'),
('acf','atos',26,26,'Porque o rei, diante de quem também falo com ousadia, sabe estas coisas, pois não creio que nada disto lhe é oculto; porque isto não se fez em qualquer canto.'),
('acf','atos',26,27,'Crês tu nos profetas, ó rei Agripa? Bem sei que crês.'),
('acf','atos',26,28,'E disse Agripa a Paulo: Por pouco me queres persuadir a que me faça cristão!'),
('acf','atos',26,29,'E disse Paulo: Prouvera a Deus que, ou por pouco ou por muito, não somente tu, mas também todos quantos hoje me estão ouvindo, se tornassem tais qual eu sou, exceto estas cadeias.'),
('acf','atos',26,30,'E, dizendo ele isto, levantou-se o rei, o presidente, e Berenice, e os que com eles estavam assentados.'),
('acf','atos',26,31,'E, apartando-se dali falavam uns com os outros, dizendo: Este homem nada fez digno de morte ou de prisões.'),
('acf','atos',26,32,'E Agripa disse a Festo: Bem podia soltar-se este homem, se não houvera apelado para César.'),
('acf','atos',27,1,'E, como se determinou que havíamos de navegar para a Itália, entregaram Paulo, e alguns outros presos, a um centurião por nome Júlio, da coorte augusta.'),
('acf','atos',27,2,'E, embarcando nós em um navio adramitino, partimos navegando pelos lugares da costa da Ásia, estando conosco Aristarco, macedônio, de Tessalônica.'),
('acf','atos',27,3,'E chegamos no dia seguinte a Sidom, e Júlio, tratando Paulo humanamente, lhe permitiu ir ver os amigos, para que cuidassem dele.'),
('acf','atos',27,4,'E, partindo dali, fomos navegando abaixo de Chipre, porque os ventos eram contrários.'),
('acf','atos',27,5,'E, tendo atravessado o mar, ao longo da Cilícia e Panfília, chegamos a Mirra, na Lícia.'),
('acf','atos',27,6,'E, achando ali o centurião um navio de Alexandria, que navegava para a Itália, nos fez embarcar nele.'),
('acf','atos',27,7,'E, como por muitos dias navegássemos vagarosamente, havendo chegado apenas defronte de Cnido, não nos permitindo o vento ir mais adiante, navegamos abaixo de Creta, junto de Salmone.'),
('acf','atos',27,8,'E, consteando-a dificilmente, chegamos a um lugar chamando Bons Portos, perto do qual estava a cidade de Laséia.'),
('acf','atos',27,9,'E, passado muito tempo, e sendo já perigosa a navegação, pois, também o jejum já tinha passado, Paulo os admoestava,'),
('acf','atos',27,10,'Dizendo-lhes: Senhores, vejo que a navegação há de ser incômoda, e com muito dano, não só para o navio e carga, mas também para as nossas vidas.'),
('acf','atos',27,11,'Mas o centurião cria mais no piloto e no mestre, do que no que dizia Paulo.'),
('acf','atos',27,12,'E, como aquele porto não era cômodo para invernar, os mais deles foram de parecer que se partisse dali para ver se podiam chegar a Fenice, que é um porto de Creta que olha para o lado do vento da África e do Coro, e invernar ali.'),
('acf','atos',27,13,'E, soprando o sul brandamente, lhes pareceu terem já o que desejavam e, fazendo-se de vela, foram de muito perto costeando Creta.'),
('acf','atos',27,14,'Mas não muito depois deu nela um pé de vento, chamado Euro-aquilão.'),
('acf','atos',27,15,'E, sendo o navio arrebatado, e não podendo navegar contra o vento, dando de mão a tudo, nos deixamos ir à toa.'),
('acf','atos',27,16,'E, correndo abaixo de uma pequena ilha chamada Clauda, apenas pudemos ganhar o batel.'),
('acf','atos',27,17,'E, levado este para cima, usaram de todos os meios, cingindo o navio; e, temendo darem à costa na Sirte, amainadas as velas, assim foram à toa.'),
('acf','atos',27,18,'E, andando nós agitados por uma veemente tempestade, no dia seguinte aliviaram o navio.'),
('acf','atos',27,19,'E ao terceiro dia nós mesmos, com as nossas próprias mãos, lançamos ao mar a armação do navio.'),
('acf','atos',27,20,'E, não aparecendo, havia já muitos dias, nem sol nem estrelas, e caindo sobre nós uma não pequena tempestade, fugiu-nos toda a esperança de nos salvarmos.'),
('acf','atos',27,21,'E, havendo já muito que não se comia, então Paulo, pondo-se em pé no meio deles, disse: Fora, na verdade, razoável, ó senhores, ter-me ouvido a mim e não partir de Creta, e assim evitariam este incômodo e esta perda.'),
('acf','atos',27,22,'Mas agora vos admoesto a que tenhais bom ânimo, porque não se perderá a vida de nenhum de vós, mas somente o navio.'),
('acf','atos',27,23,'Porque esta mesma noite o anjo de Deus, de quem eu sou, e a quem sirvo, esteve comigo,'),
('acf','atos',27,24,'Dizendo: Paulo, não temas; importa que sejas apresentado a César, e eis que Deus te deu todos quantos navegam contigo.'),
('acf','atos',27,25,'Portanto, ó senhores, tende bom ânimo; porque creio em Deus, que há de acontecer assim como a mim me foi dito.'),
('acf','atos',27,26,'É contudo necessário irmos dar numa ilha.'),
('acf','atos',27,27,'E, quando chegou a décima quarta noite, sendo impelidos de um e outro lado no mar Adriático, lá pela meia-noite suspeitaram os marinheiros que estavam próximos de alguma terra.'),
('acf','atos',27,28,'E, lançando o prumo, acharam vinte braças; e, passando um pouco mais adiante, tornando a lançar o prumo, acharam quinze braças.'),
('acf','atos',27,29,'E, temendo ir dar em alguns rochedos, lançaram da popa quatro âncoras, desejando que viesse o dia.'),
('acf','atos',27,30,'Procurando, porém, os marinheiros fugir do navio, e tendo já deitado o batel ao mar, como que querendo lançar as âncoras pela proa,'),
('acf','atos',27,31,'Disse Paulo ao centurião e aos soldados: Se estes não ficarem no navio, não podereis salvar-vos.'),
('acf','atos',27,32,'Então os soldados cortaram os cabos do batel, e o deixaram cair.'),
('acf','atos',27,33,'E, entretanto que o dia vinha, Paulo exortava a todos a que comessem alguma coisa, dizendo: É já hoje o décimo quarto dia que esperais, e permaneceis sem comer, não havendo provado nada.'),
('acf','atos',27,34,'Portanto, exorto-vos a que comais alguma coisa, pois é para a vossa saúde; porque nem um cabelo cairá da cabeça de qualquer de vós.'),
('acf','atos',27,35,'E, havendo dito isto, tomando o pão, deu graças a Deus na presença de todos; e, partindo-o, começou a comer.'),
('acf','atos',27,36,'E, tendo já todos bom ânimo, puseram-se também a comer.'),
('acf','atos',27,37,'E éramos ao todo, no navio, duzentas e setenta e seis almas.'),
('acf','atos',27,38,'E, refeitos com a comida, aliviaram o navio, lançando o trigo ao mar.'),
('acf','atos',27,39,'E, sendo já dia, não conheceram a terra; enxergaram, porém, uma enseada que tinha praia, e consultaram-se sobre se deveriam encalhar nela o navio.'),
('acf','atos',27,40,'E, levantando as âncoras, deixaram-no ir ao mar, largando também as amarras do leme; e, alçando a vela maior ao vento, dirigiram-se para a praia.'),
('acf','atos',27,41,'Dando, porém, num lugar de dois mares, encalharam ali o navio; e, fixa a proa, ficou imóvel, mas a popa abria-se com a força das ondas.'),
('acf','atos',27,42,'Então a idéia dos soldados foi que matassem os presos para que nenhum fugisse, escapando a nado.'),
('acf','atos',27,43,'Mas o centurião, querendo salvar a Paulo, lhes estorvou este intento; e mandou que os que pudessem nadar se lançassem primeiro ao mar, e se salvassem em terra;'),
('acf','atos',27,44,'E os demais, uns em tábuas e outros em coisas do navio. E assim aconteceu que todos chegaram à terra a salvo.'),
('acf','atos',28,1,'E, havendo escapado, então souberam que a ilha se chamava Malta.'),
('acf','atos',28,2,'E os bárbaros usaram conosco de não pouca humanidade; porque, acendendo uma grande fogueira, nos recolheram a todos por causa da chuva que caía, e por causa do frio.'),
('acf','atos',28,3,'E, havendo Paulo ajuntado uma quantidade de vides, e pondo-as no fogo, uma víbora, fugindo do calor, lhe acometeu a mão.'),
('acf','atos',28,4,'E os bárbaros, vendo-lhe a víbora pendurada na mão, diziam uns aos outros: Certamente este homem é homicida, visto como, escapando do mar, a justiça não o deixa viver.'),
('acf','atos',28,5,'Mas, sacudindo ele a víbora no fogo, não sofreu nenhum mal.'),
('acf','atos',28,6,'E eles esperavam que viesse a inchar ou a cair morto de repente; mas tendo esperado já muito, e vendo que nenhum incômodo lhe sobrevinha, mudando de parecer, diziam que era um deus.'),
('acf','atos',28,7,'E ali, próximo daquele lugar, havia umas herdades que pertenciam ao principal da ilha, por nome Públio, o qual nos recebeu e hospedou benignamente por três dias.'),
('acf','atos',28,8,'E aconteceu estar de cama enfermo de febre e disenteria o pai de Públio, que Paulo foi ver, e, havendo orado, pôs as mãos sobre ele, e o curou.'),
('acf','atos',28,9,'Feito, pois, isto, vieram também ter com ele os demais que na ilha tinham enfermidades, e sararam.'),
('acf','atos',28,10,'Os quais nos distinguiram também com muitas honras; e, havendo de navegar, nos proveram das coisas necessárias.'),
('acf','atos',28,11,'E três meses depois partimos num navio de Alexandria que invernara na ilha, o qual tinha por insígnia Castor e Pólux.'),
('acf','atos',28,12,'E, chegando a Siracusa, ficamos ali três dias.'),
('acf','atos',28,13,'De onde, indo costeando, viemos a Régio; e soprando, um dia depois, um vento do sul, chegamos no segundo dia a Potéoli.'),
('acf','atos',28,14,'Onde, achando alguns irmãos, nos rogaram que por sete dias ficássemos com eles; e depois nos dirigimos a Roma.'),
('acf','atos',28,15,'E de lá, ouvindo os irmãos novas de nós, nos saíram ao encontro à Praça de Ápio e às Três Vendas, e Paulo, vendo-os, deu graças a Deus e tomou ânimo.'),
('acf','atos',28,16,'E, logo que chegamos a Roma, o centurião entregou os presos ao capitào da guarda; mas a Paulo se lhe permitiu morar por sua conta à parte, com o soldado que o guardava.'),
('acf','atos',28,17,'E aconteceu que, três dias depois, Paulo convocou os principais dos judeus, e, juntos eles, lhes disse: Homens irmãos, não havendo eu feito nada contra o povo, ou contra os ritos paternos, vim contudo preso desde Jerusalém, entregue nas mãos dos romanos;'),
('acf','atos',28,18,'Os quais, havendo-me examinado, queriam soltar-me, por não haver em mim crime algum de morte.'),
('acf','atos',28,19,'Mas, opondo-se os judeus, foi-me forçoso apelar para César, não tendo, contudo, de que acusar a minha nação.'),
('acf','atos',28,20,'Por esta causa vos chamei, para vos ver e falar; porque pela esperança de Israel estou com esta cadeia.'),
('acf','atos',28,21,'Então eles lhe disseram: Nós não recebemos acerca de ti carta alguma da Judéia, nem veio aqui algum dos irmãos, que nos anunciasse ou dissesse de ti mal algum.'),
('acf','atos',28,22,'No entanto bem quiséramos ouvir de ti o que sentes; porque, quanto a esta seita, notório nos é que em toda a parte se fala contra ela.'),
('acf','atos',28,23,'E, havendo-lhe eles assinalado um dia, muitos foram ter com ele à pousada, aos quais declarava com bom testemunho o reino de Deus, e procurava persuadi-los à fé em Jesus, tanto pela lei de Moisés como pelos profetas, desde a manhã até à tarde.'),
('acf','atos',28,24,'E alguns criam no que se dizia; mas outros não criam.'),
('acf','atos',28,25,'E, como ficaram entre si discordes, despediram-se, dizendo Paulo esta palavra: Bem falou o Espírito Santo a nossos pais pelo profeta Isaías,'),
('acf','atos',28,26,'Dizendo:Vai a este povo, e dize:De ouvido ouvireis, e de maneira nenhuma entendereis;E, vendo vereis, e de maneira nenhuma percebereis.'),
('acf','atos',28,27,'Porquanto o coração deste povo está endurecido,e com os ouvidos ouviram pesadamente,e fecharam os olhos,para que nunca com os olhos vejam,Nem com os ouvidos ouçam,Nem do coração entendam,E se convertam,E eu os cure.'),
('acf','atos',28,28,'Seja-vos, pois, notório que esta salvação de Deus é enviada aos gentios, e eles a ouvirão.'),
('acf','atos',28,29,'E, havendo ele dito estas palavras, partiram os judeus, tendo entre si grande contenda.'),
('acf','atos',28,30,'E Paulo ficou dois anos inteiros na sua própria habitação que alugara, e recebia todos quantos vinham vê-lo;'),
('acf','atos',28,31,'Pregando o reino de Deus, e ensinando com toda a liberdade as coisas pertencentes ao Senhor Jesus Cristo, sem impedimento algum.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','rm',1,1,'Paulo, servo de Jesus Cristo, chamado para apóstolo, separado para o evangelho de Deus.'),
('acf','rm',1,2,'O qual antes prometeu pelos seus profetas nas santas escrituras,'),
('acf','rm',1,3,'Acerca de seu Filho, que nasceu da descendência de Davi segundo a carne,'),
('acf','rm',1,4,'Declarado Filho de Deus em poder, segundo o Espírito de santificação, pela ressurreição dentre os mortos, Jesus Cristo, nosso Senhor,'),
('acf','rm',1,5,'Pelo qual recebemos a graça e o apostolado, para a obediência da fé entre todas as gentes pelo seu nome,'),
('acf','rm',1,6,'Entre as quais sois também vós chamados para serdes de Jesus Cristo.'),
('acf','rm',1,7,'A todos os que estais em Roma, amados de Deus, chamados santos: Graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.'),
('acf','rm',1,8,'Primeiramente dou graças ao meu Deus por Jesus Cristo, acerca de vós todos, porque em todo o mundo é anunciada a vossa fé.'),
('acf','rm',1,9,'Porque Deus, a quem sirvo em meu espírito, no evangelho de seu Filho, me é testemunha de como incessantemente faço menção de vós,'),
('acf','rm',1,10,'Pedindo sempre em minhas orações que nalgum tempo, pela vontade de Deus, se me ofereça boa ocasião de ir ter convosco.'),
('acf','rm',1,11,'Porque desejo ver-vos, para vos comunicar algum dom espiritual, a fim de que sejais confortados;'),
('acf','rm',1,12,'Isto é, para que juntamente convosco eu seja consolado pela fé mútua, assim vossa como minha.'),
('acf','rm',1,13,'Não quero, porém, irmãos, que ignoreis que muitas vezes propus ir ter convosco (mas até agora tenho sido impedido) para também ter entre vós algum fruto, como também entre os demais gentios.'),
('acf','rm',1,14,'Eu sou devedor, tanto a gregos como a bárbaros, tanto a sábios como a ignorantes.'),
('acf','rm',1,15,'E assim, quanto está em mim, estou pronto para também vos anunciar o evangelho, a vós que estais em Roma.'),
('acf','rm',1,16,'Porque não me envergonho do evangelho de Cristo, pois é o poder de Deus para salvação de todo aquele que crê; primeiro do judeu, e também do grego.'),
('acf','rm',1,17,'Porque nele se descobre a justiça de Deus de fé em fé, como está escrito: Mas o justo viverá pela fé.'),
('acf','rm',1,18,'Porque do céu se manifesta a ira de Deus sobre toda a impiedade e injustiça dos homens, que detêm a verdade em injustiça.'),
('acf','rm',1,19,'Porquanto o que de Deus se pode conhecer neles se manifesta, porque Deus lho manifestou.'),
('acf','rm',1,20,'Porque as suas coisas invisíveis, desde a criação do mundo, tanto o seu eterno poder, como a sua divindade, se entendem, e claramente se vêem pelas coisas que estão criadas, para que eles fiquem inescusáveis;'),
('acf','rm',1,21,'Porquanto, tendo conhecido a Deus, não o glorificaram como Deus, nem lhe deram graças, antes em seus discursos se desvaneceram, e o seu coração insensato se obscureceu.'),
('acf','rm',1,22,'Dizendo-se sábios, tornaram-se loucos.'),
('acf','rm',1,23,'E mudaram a glória do Deus incorruptível em semelhança da imagem de homem corruptível, e de aves, e de quadrúpedes, e de répteis.'),
('acf','rm',1,24,'Por isso também Deus os entregou às concupiscências de seus corações, à imundícia, para desonrarem seus corpos entre si;'),
('acf','rm',1,25,'Pois mudaram a verdade de Deus em mentira, e honraram e serviram mais a criatura do que o Criador, que é bendito eternamente. Amém.'),
('acf','rm',1,26,'Por isso Deus os abandonou às paixões infames. Porque até as suas mulheres mudaram o uso natural, no contrário à natureza.'),
('acf','rm',1,27,'E, semelhantemente, também os homens, deixando o uso natural da mulher, se inflamaram em sua sensualidade uns para com os outros, homens com homens, cometendo torpeza e recebendo em si mesmos a recompensa que convinha ao seu erro.'),
('acf','rm',1,28,'E, como eles não se importaram de ter conhecimento de Deus, assim Deus os entregou a um sentimento perverso, para fazerem coisas que não convêm;'),
('acf','rm',1,29,'Estando cheios de toda a iniqüidade, fornicação, malícia, avareza, maldade; cheios de inveja, homicídio, contenda, engano, malignidade;'),
('acf','rm',1,30,'Sendo murmuradores, detratores, aborrecedores de Deus, injuriadores, soberbos, presunçosos, inventores de males, desobedientes aos pais e às mães;'),
('acf','rm',1,31,'Néscios, infiéis nos contratos, sem afeição natural, irreconciliáveis, sem misericórdia;'),
('acf','rm',1,32,'Os quais, conhecendo o juízo de Deus (que são dignos de morte os que tais coisas praticam), não somente as fazem, mas também consentem aos que as fazem.'),
('acf','rm',2,1,'Portanto, és inescusável quando julgas, ó homem, quem quer que sejas, porque te condenas a ti mesmo naquilo em que julgas a outro; pois tu, que julgas, fazes o mesmo.'),
('acf','rm',2,2,'E bem sabemos que o juízo de Deus é segundo a verdade sobre os que tais coisas fazem.'),
('acf','rm',2,3,'E tu, ó homem, que julgas os que fazem tais coisas, cuidas que, fazendo-as tu, escaparás ao juízo de Deus?'),
('acf','rm',2,4,'Ou desprezas tu as riquezas da sua benignidade, e paciência e longanimidade, ignorando que a benignidade de Deus te leva ao arrependimento?'),
('acf','rm',2,5,'Mas, segundo a tua dureza e teu coração impenitente, entesouras ira para ti no dia da ira e da manifestação do juízo de Deus;'),
('acf','rm',2,6,'O qual recompensará cada um segundo as suas obras; a saber:'),
('acf','rm',2,7,'A vida eterna aos que, com perseverança em fazer bem, procuram glória, honra e incorrupção;'),
('acf','rm',2,8,'Mas a indignação e a ira aos que são contenciosos, desobedientes à verdade e obedientes à iniqüidade;'),
('acf','rm',2,9,'Tribulação e angústia sobre toda a alma do homem que faz o mal; primeiramente do judeu e também do grego;'),
('acf','rm',2,10,'Glória, porém, e honra e paz a qualquer que pratica o bem; primeiramente ao judeu e também ao grego;'),
('acf','rm',2,11,'Porque, para com Deus, não há acepção de pessoas.'),
('acf','rm',2,12,'Porque todos os que sem lei pecaram, sem lei também perecerão; e todos os que sob a lei pecaram, pela lei serão julgados.'),
('acf','rm',2,13,'Porque os que ouvem a lei não são justos diante de Deus, mas os que praticam a lei hão de ser justificados.'),
('acf','rm',2,14,'Porque, quando os gentios, que não têm lei, fazem naturalmente as coisas que são da lei, não tendo eles lei, para si mesmos são lei;'),
('acf','rm',2,15,'Os quais mostram a obra da lei escrita em seus corações, testificando juntamente a sua consciência, e os seus pensamentos, quer acusando-os, quer defendendo-os;'),
('acf','rm',2,16,'No dia em que Deus há de julgar os segredos dos homens, por Jesus Cristo, segundo o meu evangelho.'),
('acf','rm',2,17,'Eis que tu que tens por sobrenome judeu, e repousas na lei, e te glorias em Deus;'),
('acf','rm',2,18,'E sabes a sua vontade e aprovas as coisas excelentes, sendo instruído por lei;'),
('acf','rm',2,19,'E confias que és guia dos cegos, luz dos que estão em trevas,'),
('acf','rm',2,20,'Instruidor dos néscios, mestre de crianças, que tens a forma da ciência e da verdade na lei;'),
('acf','rm',2,21,'Tu, pois, que ensinas a outro, não te ensinas a ti mesmo? Tu, que pregas que não se deve furtar, furtas?'),
('acf','rm',2,22,'Tu, que dizes que não se deve adulterar, adulteras? Tu, que abominas os ídolos, cometes sacrilégio?'),
('acf','rm',2,23,'Tu, que te glorias na lei, desonras a Deus pela transgressão da lei?'),
('acf','rm',2,24,'Porque, como está escrito, o nome de Deus é blasfemado entre os gentios por causa de vós.'),
('acf','rm',2,25,'Porque a circuncisão é, na verdade, proveitosa, se tu guardares a lei; mas, se tu és transgressor da lei, a tua circuncisão se torna em incircuncisão.'),
('acf','rm',2,26,'Se, pois, a incircuncisão guardar os preceitos da lei, porventura a incircuncisão não será reputada como circuncisão?'),
('acf','rm',2,27,'E a incircuncisão que por natureza o é, se cumpre a lei, não te julgará porventura a ti, que pela letra e circuncisão és transgressor da lei?'),
('acf','rm',2,28,'Porque não é judeu o que o é exteriormente, nem é circuncisão a que o é exteriormente na carne.'),
('acf','rm',2,29,'Mas é judeu o que o é no interior, e circuncisão a que é do coração, no espírito, não na letra; cujo louvor não provém dos homens, mas de Deus.'),
('acf','rm',3,1,'Qual é logo a vantagem do judeu? Ou qual a utilidade da circuncisão?'),
('acf','rm',3,2,'Muita, em toda a maneira, porque, primeiramente, as palavras de Deus lhe foram confiadas.'),
('acf','rm',3,3,'Pois quê? Se alguns foram incrédulos, a sua incredulidade aniquilará a fidelidade de Deus?'),
('acf','rm',3,4,'De maneira nenhuma; sempre seja Deus verdadeiro, e todo o homem mentiroso; como está escrito:Para que sejas justificado em tuas palavras,E venças quando fores julgado.'),
('acf','rm',3,5,'E, se a nossa injustiça for causa da justiça de Deus, que diremos? Porventura será Deus injusto, trazendo ira sobre nós? (Falo como homem. )'),
('acf','rm',3,6,'De maneira nenhuma; de outro modo, como julgará Deus o mundo?'),
('acf','rm',3,7,'Mas, se pela minha mentira abundou mais a verdade de Deus para glória sua, por que sou eu ainda julgado também como pecador?'),
('acf','rm',3,8,'E por que não dizemos (como somos blasfemados, e como alguns dizem que dizemos): Façamos males, para que venham bens? A condenação desses é justa.'),
('acf','rm',3,9,'Pois quê? Somos nós mais excelentes? De maneira nenhuma, pois já dantes demonstramos que, tanto judeus como gregos, todos estão debaixo do pecado;'),
('acf','rm',3,10,'Como está escrito:Não há um justo, nem um sequer.'),
('acf','rm',3,11,'Não há ninguém que entenda;Não há ninguém que busque a Deus.'),
('acf','rm',3,12,'Todos se extraviaram, e juntamente se fizeram inúteis.Não há quem faça o bem, não há nem um só.'),
('acf','rm',3,13,'A sua garganta é um sepulcro aberto;Com as suas línguas tratam enganosamente;Peçonha de áspides está debaixo de seus lábios;'),
('acf','rm',3,14,'Cuja boca está cheia de maldição e amargura.'),
('acf','rm',3,15,'Os seus pés são ligeiros para derramar sangue.'),
('acf','rm',3,16,'Em seus caminhos há destruição e miséria;'),
('acf','rm',3,17,'E não conheceram o caminho da paz.'),
('acf','rm',3,18,'Não há temor de Deus diante de seus olhos.'),
('acf','rm',3,19,'Ora, nós sabemos que tudo o que a lei diz, aos que estão debaixo da lei o diz, para que toda a boca esteja fechada e todo o mundo seja condenável diante de Deus.'),
('acf','rm',3,20,'Por isso nenhuma carne será justificada diante dele pelas obras da lei, porque pela lei vem o conhecimento do pecado.'),
('acf','rm',3,21,'Mas agora se manifestou sem a lei a justiça de Deus, tendo o testemunho da lei e dos profetas;'),
('acf','rm',3,22,'Isto é, a justiça de Deus pela fé em Jesus Cristo para todos e sobre todos os que crêem; porque não há diferença.'),
('acf','rm',3,23,'Porque todos pecaram e destituídos estão da glória de Deus;'),
('acf','rm',3,24,'Sendo justificados gratuitamente pela sua graça, pela redenção que há em Cristo Jesus.'),
('acf','rm',3,25,'Ao qual Deus propôs para propiciação pela fé no seu sangue, para demonstrar a sua justiça pela remissão dos pecados dantes cometidos, sob a paciência de Deus;'),
('acf','rm',3,26,'Para demonstração da sua justiça neste tempo presente, para que ele seja justo e justificador daquele que tem fé em Jesus.'),
('acf','rm',3,27,'Onde está logo a jactância? É excluída. Por qual lei? Das obras? Não; mas pela lei da fé.'),
('acf','rm',3,28,'Concluímos, pois, que o homem é justificado pela fé sem as obras da lei.'),
('acf','rm',3,29,'É porventura Deus somente dos judeus? E não o é também dos gentios? Também dos gentios, certamente,'),
('acf','rm',3,30,'Visto que Deus é um só, que justifica pela fé a circuncisão, e por meio da fé a incircuncisão.'),
('acf','rm',3,31,'Anulamos, pois, a lei pela fé? De maneira nenhuma, antes estabelecemos a lei.'),
('acf','rm',4,1,'Que diremos, pois, ter alcançado Abraão, nosso pai segundo a carne?'),
('acf','rm',4,2,'Porque, se Abraão foi justificado pelas obras, tem de que se gloriar, mas não diante de Deus.'),
('acf','rm',4,3,'Pois, que diz a Escritura? Creu Abraão a Deus, e isso lhe foi imputado como justiça.'),
('acf','rm',4,4,'Ora, àquele que faz qualquer obra não lhe é imputado o galardão segundo a graça, mas segundo a dívida.'),
('acf','rm',4,5,'Mas, àquele que não pratica, mas crê naquele que justifica o ímpio, a sua fé lhe é imputada como justiça.'),
('acf','rm',4,6,'Assim também Davi declara bem-aventurado o homem a quem Deus imputa a justiça sem as obras, dizendo:'),
('acf','rm',4,7,'Bem-aventurados aqueles cujas maldades são perdoadas,E cujos pecados são cobertos.'),
('acf','rm',4,8,'Bem-aventurado o homem a quem o Senhor não imputa o pecado.'),
('acf','rm',4,9,'Vem, pois, esta bem-aventurança sobre a circuncisão somente, ou também sobre a incircuncisão? Porque dizemos que a fé foi imputada como justiça a Abraão.'),
('acf','rm',4,10,'Como lhe foi, pois, imputada? Estando na circuncisão ou na incircuncisão? Não na circuncisão, mas na incircuncisão.'),
('acf','rm',4,11,'E recebeu o sinal da circuncisão, selo da justiça da fé quando estava na incircuncisão, para que fosse pai de todos os que crêem, estando eles também na incircuncisão; a fim de que também a justiça lhes seja imputada;'),
('acf','rm',4,12,'E fosse pai da circuncisão, daqueles que não somente são da circuncisão, mas que também andam nas pisadas daquela fé que teve nosso pai Abraão, que tivera na incircuncisão.'),
('acf','rm',4,13,'Porque a promessa de que havia de ser herdeiro do mundo não foi feita pela lei a Abraão, ou à sua posteridade, mas pela justiça da fé.'),
('acf','rm',4,14,'Porque, se os que são da lei são herdeiros, logo a fé é vã e a promessa é aniquilada.'),
('acf','rm',4,15,'Porque a lei opera a ira. Porque onde não há lei também não há transgressão.'),
('acf','rm',4,16,'Portanto, é pela fé, para que seja segundo a graça, a fim de que a promessa seja firme a toda a posteridade, não somente à que é da lei, mas também à que é da fé que teve Abraão, o qual é pai de todos nós,'),
('acf','rm',4,17,'(Como está escrito: Por pai de muitas nações te constituí) perante aquele no qual creu, a saber, Deus, o qual vivifica os mortos, e chama as coisas que não são como se já fossem.'),
('acf','rm',4,18,'O qual, em esperança, creu contra a esperança, tanto que ele tornou-se pai de muitas nações, conforme o que lhe fora dito: Assim será a tua descendência.'),
('acf','rm',4,19,'E não enfraquecendo na fé, nào atentou para o seu próprio corpo já amortecido, pois era já de quase cem anos, nem tampouco para o amortecimento do ventre de Sara.'),
('acf','rm',4,20,'E não duvidou da promessa de Deus por incredulidade, mas foi fortificado na fé, dando glória a Deus,'),
('acf','rm',4,21,'E estando certíssimo de que o que ele tinha prometido também era poderoso para o fazer.'),
('acf','rm',4,22,'Assim isso lhe foi também imputado como justiça.'),
('acf','rm',4,23,'Ora, não só por causa dele está escrito, que lhe fosse tomado em conta,'),
('acf','rm',4,24,'Mas também por nós, a quem será tomado em conta, os que cremos naquele que dentre os mortos ressuscitou a Jesus nosso Senhor;'),
('acf','rm',4,25,'O qual por nossos pecados foi entregue, e ressuscitou para nossa justificação.'),
('acf','rm',5,1,'Tendo sido, pois, justificados pela fé, temos paz com Deus, por nosso Senhor Jesus Cristo;'),
('acf','rm',5,2,'Pelo qual também temos entrada pela fé a esta graça, na qual estamos firmes, e nos gloriamos na esperança da glória de Deus.'),
('acf','rm',5,3,'E não somente isto, mas também nos gloriamos nas tribulações; sabendo que a tribulação produz a paciência,'),
('acf','rm',5,4,'E a paciência a experiência, e a experiência a esperança.'),
('acf','rm',5,5,'E a esperança não traz confusão, porquanto o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.'),
('acf','rm',5,6,'Porque Cristo, estando nós ainda fracos, morreu a seu tempo pelos ímpios.'),
('acf','rm',5,7,'Porque apenas alguém morrerá por um justo; pois poderá ser que pelo bom alguém ouse morrer.'),
('acf','rm',5,8,'Mas Deus prova o seu amor para conosco, em que Cristo morreu por nós, sendo nós ainda pecadores.'),
('acf','rm',5,9,'Logo muito mais agora, tendo sido justificados pelo seu sangue, seremos por ele salvos da ira.'),
('acf','rm',5,10,'Porque se nós, sendo inimigos, fomos reconciliados com Deus pela morte de seu Filho, muito mais, tendo sido já reconciliados, seremos salvos pela sua vida.'),
('acf','rm',5,11,'E não somente isto, mas também nos gloriamos em Deus por nosso Senhor Jesus Cristo, pelo qual agora alcançamos a reconciliação.'),
('acf','rm',5,12,'Portanto, como por um homem entrou o pecado no mundo, e pelo pecado a morte, assim também a morte passou a todos os homens por isso que todos pecaram.'),
('acf','rm',5,13,'Porque até à lei estava o pecado no mundo, mas o pecado não é imputado, não havendo lei.'),
('acf','rm',5,14,'No entanto, a morte reinou desde Adão até Moisés, até sobre aqueles que não tinham pecado à semelhança da transgressão de Adão, o qual é a figura daquele que havia de vir.'),
('acf','rm',5,15,'Mas não é assim o dom gratuito como a ofensa. Porque, se pela ofensa de um morreram muitos, muito mais a graça de Deus, e o dom pela graça, que é de um só homem, Jesus Cristo, abundou sobre muitos.'),
('acf','rm',5,16,'E não foi assim o dom como a ofensa, por um só que pecou. Porque o juízo veio de uma só ofensa, na verdade, para condenação, mas o dom gratuito veio de muitas ofensas para justificação.'),
('acf','rm',5,17,'Porque, se pela ofensa de um só, a morte reinou por esse, muito mais os que recebem a abundância da graça, e do dom da justiça, reinarão em vida por um só, Jesus Cristo.'),
('acf','rm',5,18,'Pois assim como por uma só ofensa veio o juízo sobre todos os homens para condenação, assim também por um só ato de justiça veio a graça sobre todos os homens para justificação de vida.'),
('acf','rm',5,19,'Porque, como pela desobediência de um só homem, muitos foram feitos pecadores, assim pela obediência de um muitos serão feitos justos.'),
('acf','rm',5,20,'Veio, porém, a lei para que a ofensa abundasse; mas, onde o pecado abundou, superabundou a graça;'),
('acf','rm',5,21,'Para que, assim como o pecado reinou na morte, também a graça reinasse pela justiça para a vida eterna, por Jesus Cristo nosso Senhor.'),
('acf','rm',6,1,'Que diremos pois? Permaneceremos no pecado, para que a graça abunde?'),
('acf','rm',6,2,'De modo nenhum. Nós, que estamos mortos para o pecado, como viveremos ainda nele?'),
('acf','rm',6,3,'Ou não sabeis que todos quantos fomos batizados em Jesus Cristo fomos batizados na sua morte?'),
('acf','rm',6,4,'De sorte que fomos sepultados com ele pelo batismo na morte; para que, como Cristo foi ressuscitado dentre os mortos, pela glória do Pai, assim andemos nós também em novidade de vida.'),
('acf','rm',6,5,'Porque, se fomos plantados juntamente com ele na semelhança da sua morte, também o seremos na da sua ressurreição;'),
('acf','rm',6,6,'Sabendo isto, que o nosso homem velho foi com ele crucificado, para que o corpo do pecado seja desfeito, para que não sirvamos mais ao pecado.'),
('acf','rm',6,7,'Porque aquele que está morto está justificado do pecado.'),
('acf','rm',6,8,'Ora, se já morremos com Cristo, cremos que também com ele viveremos;'),
('acf','rm',6,9,'Sabendo que, tendo sido Cristo ressuscitado dentre os mortos, já não morre; a morte não mais tem domínio sobre ele.'),
('acf','rm',6,10,'Pois, quanto a ter morrido, de uma vez morreu para o pecado; mas, quanto a viver, vive para Deus.'),
('acf','rm',6,11,'Assim também vós considerai-vos certamente mortos para o pecado, mas vivos para Deus em Cristo Jesus nosso Senhor.'),
('acf','rm',6,12,'Não reine, portanto, o pecado em vosso corpo mortal, para lhe obedecerdes em suas concupiscências;'),
('acf','rm',6,13,'Nem tampouco apresenteis os vossos membros ao pecado por instrumentos de iniqüidade; mas apresentai-vos a Deus, como vivos dentre mortos, e os vossos membros a Deus, como instrumentos de justiça.'),
('acf','rm',6,14,'Porque o pecado não terá domínio sobre vós, pois não estais debaixo da lei, mas debaixo da graça.'),
('acf','rm',6,15,'Pois que? Pecaremos porque não estamos debaixo da lei, mas debaixo da graça? De modo nenhum.'),
('acf','rm',6,16,'Não sabeis vós que a quem vos apresentardes por servos para lhe obedecer, sois servos daquele a quem obedeceis, ou do pecado para a morte, ou da obediência para a justiça?'),
('acf','rm',6,17,'Mas graças a Deus que, tendo sido servos do pecado, obedecestes de coração à forma de doutrina a que fostes entregues.'),
('acf','rm',6,18,'E, libertados do pecado, fostes feitos servos da justiça.'),
('acf','rm',6,19,'Falo como homem, pela fraqueza da vossa carne; pois que, assim como apresentastes os vossos membros para servirem à imundícia, e à maldade para maldade, assim apresentai agora os vossos membros para servirem à justiça para santificação.'),
('acf','rm',6,20,'Porque, quando éreis servos do pecado, estáveis livres da justiça.'),
('acf','rm',6,21,'E que fruto tínheis então das coisas de que agora vos envergonhais? Porque o fim delas é a morte.'),
('acf','rm',6,22,'Mas agora, libertados do pecado, e feitos servos de Deus, tendes o vosso fruto para santificação, e por fim a vida eterna.'),
('acf','rm',6,23,'Porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna, por Cristo Jesus nosso Senhor.'),
('acf','rm',7,1,'Não sabeis vós, irmãos (pois que falo aos que sabem a lei), que a lei tem domínio sobre o homem por todo o tempo que vive?'),
('acf','rm',7,2,'Porque a mulher que está sujeita ao marido, enquanto ele viver, está-lhe ligada pela lei; mas, morto o marido, está livre da lei do marido.'),
('acf','rm',7,3,'De sorte que, vivendo o marido, será chamada adúltera se for de outro marido; mas, morto o marido, livre está da lei, e assim não será adúltera, se for de outro marido.'),
('acf','rm',7,4,'Assim, meus irmãos, também vós estais mortos para a lei pelo corpo de Cristo, para que sejais de outro, daquele que ressuscitou dentre os mortos, a fim de que demos fruto para Deus.'),
('acf','rm',7,5,'Porque, quando estávamos na carne, as paixões dos pecados, que são pela lei, operavam em nossos membros para darem fruto para a morte.'),
('acf','rm',7,6,'Mas agora temos sido libertados da lei, tendo morrido para aquilo em que estávamos retidos; para que sirvamos em novidade de espírito, e não na velhice da letra.'),
('acf','rm',7,7,'Que diremos pois? É a lei pecado? De modo nenhum. Mas eu não conheci o pecado senão pela lei; porque eu não conheceria a concupiscência, se a lei não dissesse: Não cobiçarás.'),
('acf','rm',7,8,'Mas o pecado, tomando ocasião pelo mandamento, operou em mim toda a concupiscência; porquanto sem a lei estava morto o pecado.'),
('acf','rm',7,9,'E eu, nalgum tempo, vivia sem lei, mas, vindo o mandamento, reviveu o pecado, e eu morri.'),
('acf','rm',7,10,'E o mandamento que era para vida, achei eu que me era para morte.'),
('acf','rm',7,11,'Porque o pecado, tomando ocasião pelo mandamento, me enganou, e por ele me matou.'),
('acf','rm',7,12,'E assim a lei é santa, e o mandamento santo, justo e bom.'),
('acf','rm',7,13,'Logo tornou-se-me o bom em morte? De modo nenhum; mas o pecado, para que se mostrasse pecado, operou em mim a morte pelo bem; a fim de que pelo mandamento o pecado se fizesse excessivamente maligno.'),
('acf','rm',7,14,'Porque bem sabemos que a lei é espiritual; mas eu sou carnal, vendido sob o pecado.'),
('acf','rm',7,15,'Porque o que faço não o aprovo; pois o que quero isso não faço, mas o que aborreço isso faço.'),
('acf','rm',7,16,'E, se faço o que não quero, consinto com a lei, que é boa.'),
('acf','rm',7,17,'De maneira que agora já não sou eu que faço isto, mas o pecado que habita em mim.'),
('acf','rm',7,18,'Porque eu sei que em mim, isto é, na minha carne, não habita bem algum; e com efeito o querer está em mim, mas não consigo realizar o bem.'),
('acf','rm',7,19,'Porque não faço o bem que quero, mas o mal que não quero esse faço.'),
('acf','rm',7,20,'Ora, se eu faço o que não quero, já o não faço eu, mas o pecado que habita em mim.'),
('acf','rm',7,21,'Acho então esta lei em mim, que, quando quero fazer o bem, o mal está comigo.'),
('acf','rm',7,22,'Porque, segundo o homem interior, tenho prazer na lei de Deus;'),
('acf','rm',7,23,'Mas vejo nos meus membros outra lei, que batalha contra a lei do meu entendimento, e me prende debaixo da lei do pecado que está nos meus membros.'),
('acf','rm',7,24,'Miserável homem que eu sou! quem me livrará do corpo desta morte?'),
('acf','rm',7,25,'Dou graças a Deus por Jesus Cristo nosso Senhor. Assim que eu mesmo com o entendimento sirvo à lei de Deus, mas com a carne à lei do pecado.'),
('acf','rm',8,1,'Portanto, agora nenhuma condenação há para os que estão em Cristo Jesus, que não andam segundo a carne, mas segundo o Espírito.'),
('acf','rm',8,2,'Porque a lei do Espírito de vida, em Cristo Jesus, me livrou da lei do pecado e da morte.'),
('acf','rm',8,3,'Porquanto o que era impossível à lei, visto como estava enferma pela carne, Deus, enviando o seu Filho em semelhança da carne do pecado, pelo pecado condenou o pecado na carne;'),
('acf','rm',8,4,'Para que a justiça da lei se cumprisse em nós, que não andamos segundo a carne, mas segundo o Espírito.'),
('acf','rm',8,5,'Porque os que são segundo a carne inclinam-se para as coisas da carne; mas os que são segundo o Espírito para as coisas do Espírito.'),
('acf','rm',8,6,'Porque a inclinação da carne é morte; mas a inclinação do Espírito é vida e paz.'),
('acf','rm',8,7,'Porquanto a inclinação da carne é inimizade contra Deus, pois não é sujeita à lei de Deus, nem, em verdade, o pode ser.'),
('acf','rm',8,8,'Portanto, os que estão na carne não podem agradar a Deus.'),
('acf','rm',8,9,'Vós, porém, não estais na carne, mas no Espírito, se é que o Espírito de Deus habita em vós. Mas, se alguém não tem o Espírito de Cristo, esse tal não é dele.'),
('acf','rm',8,10,'E, se Cristo está em vós, o corpo, na verdade, está morto por causa do pecado, mas o espírito vive por causa da justiça.'),
('acf','rm',8,11,'E, se o Espírito daquele que dentre os mortos ressuscitou a Jesus habita em vós, aquele que dentre os mortos ressuscitou a Cristo também vivificará os vossos corpos mortais, pelo seu Espírito que em vós habita.'),
('acf','rm',8,12,'De maneira que, irmãos, somos devedores, não à carne para viver segundo a carne.'),
('acf','rm',8,13,'Porque, se viverdes segundo a carne, morrereis; mas, se pelo Espírito mortificardes as obras do corpo, vivereis.'),
('acf','rm',8,14,'Porque todos os que são guiados pelo Espírito de Deus esses são filhos de Deus.'),
('acf','rm',8,15,'Porque não recebestes o espírito de escravidão, para outra vez estardes em temor, mas recebestes o Espírito de adoção de filhos, pelo qual clamamos: Aba, Pai.'),
('acf','rm',8,16,'O mesmo Espírito testifica com o nosso espírito que somos filhos de Deus.'),
('acf','rm',8,17,'E, se nós somos filhos, somos logo herdeiros também, herdeiros de Deus, e co-herdeiros de Cristo: se é certo que com ele padecemos, para que também com ele sejamos glorificados.'),
('acf','rm',8,18,'Porque para mim tenho por certo que as aflições deste tempo presente não são para comparar com a glória que em nós há de ser revelada.'),
('acf','rm',8,19,'Porque a ardente expectação da criatura espera a manifestação dos filhos de Deus.'),
('acf','rm',8,20,'Porque a criação ficou sujeita à vaidade, não por sua vontade, mas por causa do que a sujeitou,'),
('acf','rm',8,21,'Na esperança de que também a mesma criatura será libertada da servidão da corrupção, para a liberdade da glória dos filhos de Deus.'),
('acf','rm',8,22,'Porque sabemos que toda a criação geme e está juntamente com dores de parto até agora.'),
('acf','rm',8,23,'E não só ela, mas nós mesmos, que temos as primícias do Espírito, também gememos em nós mesmos, esperando a adoção, a saber, a redenção do nosso corpo.'),
('acf','rm',8,24,'Porque em esperança fomos salvos. Ora a esperança que se vê não é esperança; porque o que alguém vê como o esperará?'),
('acf','rm',8,25,'Mas, se esperamos o que não vemos, com paciência o esperamos.'),
('acf','rm',8,26,'E da mesma maneira também o Espírito ajuda as nossas fraquezas; porque não sabemos o que havemos de pedir como convém, mas o mesmo Espírito intercede por nós com gemidos inexprimíveis.'),
('acf','rm',8,27,'E aquele que examina os corações sabe qual é a intenção do Espírito; e é ele que segundo Deus intercede pelos santos.'),
('acf','rm',8,28,'E sabemos que todas as coisas contribuem juntamente para o bem daqueles que amam a Deus, daqueles que são chamados segundo o seu propósito.'),
('acf','rm',8,29,'Porque os que dantes conheceu também os predestinou para serem conformes à imagem de seu Filho, a fim de que ele seja o primogênito entre muitos irmãos.'),
('acf','rm',8,30,'E aos que predestinou a estes também chamou; e aos que chamou a estes também justificou; e aos que justificou a estes também glorificou.'),
('acf','rm',8,31,'Que diremos, pois, a estas coisas? Se Deus é por nós, quem será contra nós?'),
('acf','rm',8,32,'Aquele que nem mesmo a seu próprio Filho poupou, antes o entregou por todos nós, como nos não dará também com ele todas as coisas?'),
('acf','rm',8,33,'Quem intentará acusação contra os escolhidos de Deus? É Deus quem os justifica.'),
('acf','rm',8,34,'Quem é que condena? Pois é Cristo quem morreu, ou antes quem ressuscitou dentre os mortos, o qual está à direita de Deus, e também intercede por nós.'),
('acf','rm',8,35,'Quem nos separará do amor de Cristo? A tribulação, ou a angústia, ou a perseguição, ou a fome, ou a nudez, ou o perigo, ou a espada?'),
('acf','rm',8,36,'Como está escrito:Por amor de ti somos entregues à morte todo o dia;Somos reputados como ovelhas para o matadouro.'),
('acf','rm',8,37,'Mas em todas estas coisas somos mais do que vencedores, por aquele que nos amou.'),
('acf','rm',8,38,'Porque estou certo de que, nem a morte, nem a vida, nem os anjos, nem os principados, nem as potestades, nem o presente, nem o porvir,'),
('acf','rm',8,39,'Nem a altura, nem a profundidade, nem alguma outra criatura nos poderá separar do amor de Deus, que está em Cristo Jesus nosso Senhor.'),
('acf','rm',9,1,'Em Cristo digo a verdade, não minto (dando-me testemunho a minha consciência no Espírito Santo):'),
('acf','rm',9,2,'Que tenho grande tristeza e contínua dor no meu coração.'),
('acf','rm',9,3,'Porque eu mesmo poderia desejar ser anátema de Cristo, por amor de meus irmãos, que são meus parentes segundo a carne;'),
('acf','rm',9,4,'Que são israelitas, dos quais é a adoção de filhos, e a glória, e as alianças, e a lei, e o culto, e as promessas;'),
('acf','rm',9,5,'Dos quais são os pais, e dos quais é Cristo segundo a carne, o qual é sobre todos, Deus bendito eternamente. Amém.'),
('acf','rm',9,6,'Não que a palavra de Deus haja faltado, porque nem todos os que são de Israel são israelitas;'),
('acf','rm',9,7,'Nem por serem descendência de Abraão são todos filhos; mas: Em Isaque será chamada a tua descendência.'),
('acf','rm',9,8,'Isto é, não são os filhos da carne que são filhos de Deus, mas os filhos da promessa são contados como descendência.'),
('acf','rm',9,9,'Porque a palavra da promessa é esta: Por este tempo virei, e Sara terá um filho.'),
('acf','rm',9,10,'E não somente esta, mas também Rebeca, quando concebeu de um, de Isaque, nosso pai;'),
('acf','rm',9,11,'Porque, não tendo eles ainda nascido, nem tendo feito bem ou mal (para que o propósito de Deus, segundo a eleição, ficasse firme, não por causa das obras, mas por aquele que chama),'),
('acf','rm',9,12,'Foi-lhe dito a ela: O maior servirá ao menor.'),
('acf','rm',9,13,'Como está escrito: Amei a Jacó, e odiei a Esaú.'),
('acf','rm',9,14,'Que diremos pois? que há injustiça da parte de Deus? De maneira nenhuma.'),
('acf','rm',9,15,'Pois diz a Moisés: Compadecer-me-ei de quem me compadecer, e terei misericórdia de quem eu tiver misericórdia.'),
('acf','rm',9,16,'Assim, pois, isto não depende do que quer, nem do que corre, mas de Deus, que se compadece.'),
('acf','rm',9,17,'Porque diz a Escritura a Faraó: Para isto mesmo te levantei; para em ti mostrar o meu poder, e para que o meu nome seja anunciado em toda a terra.'),
('acf','rm',9,18,'Logo, pois, compadece-se de quem quer, e endurece a quem quer.'),
('acf','rm',9,19,'Dir-me-ás então: Por que se queixa ele ainda? Porquanto, quem tem resistido à sua vontade?'),
('acf','rm',9,20,'Mas, ó homem, quem és tu, que a Deus replicas? Porventura a coisa formada dirá ao que a formou: Por que me fizeste assim?'),
('acf','rm',9,21,'Ou não tem o oleiro poder sobre o barro, para da mesma massa fazer um vaso para honra e outro para desonra?'),
('acf','rm',9,22,'E que direis se Deus, querendo mostrar a sua ira, e dar a conhecer o seu poder, suportou com muita paciência os vasos da ira, preparados para a perdição;'),
('acf','rm',9,23,'Para que também desse a conhecer as riquezas da sua glória nos vasos de misericórdia, que para glória já dantes preparou,'),
('acf','rm',9,24,'Os quais somos nós, a quem também chamou, não só dentre os judeus, mas também dentre os gentios?'),
('acf','rm',9,25,'Como também diz em Oséias:Chamarei meu povo ao que não era meu povo;E amada à que não era amada.'),
('acf','rm',9,26,'E sucederá que no lugar em que lhes foi dito:Vós não sois meu povo;Aí serão chamados filhos do Deus vivo.'),
('acf','rm',9,27,'Também Isaías clama acerca de Israel: Ainda que o número dos filhos de Israel seja como a areia do mar, o remanescente é que será salvo.'),
('acf','rm',9,28,'Porque ele completará a obra e abreviá-la-á em justiça; porque o Senhor fará breve a obra sobre a terra.'),
('acf','rm',9,29,'E como antes disse Isaías:Se o Senhor dos Exércitos nos não deixara descendência,Teríamos nos tornado como Sodoma, e teríamos sido feitos como Gomorra.'),
('acf','rm',9,30,'Que diremos pois? Que os gentios, que não buscavam a justiça, alcançaram a justiça? Sim, mas a justiça que é pela fé.'),
('acf','rm',9,31,'Mas Israel, que buscava a lei da justiça, não chegou à lei da justiça.'),
('acf','rm',9,32,'Por quê? Porque não foi pela fé, mas como que pelas obras da lei; pois tropeçaram na pedra de tropeço;'),
('acf','rm',9,33,'Como está escrito:Eis que eu ponho em Sião uma pedra de tropeço, e uma rocha de escândalo;E todo aquele que crer nela não será confundido.'),
('acf','rm',10,1,'Irmãos, o bom desejo do meu coração e a oração a Deus por Israel é para sua salvação.'),
('acf','rm',10,2,'Porque lhes dou testemunho de que têm zelo de Deus, mas não com entendimento.'),
('acf','rm',10,3,'Porquanto, não conhecendo a justiça de Deus, e procurando estabelecer a sua própria justiça, não se sujeitaram à justiça de Deus.'),
('acf','rm',10,4,'Porque o fim da lei é Cristo para justiça de todo aquele que crê.'),
('acf','rm',10,5,'Ora, Moisés descreve a justiça que é pela lei, dizendo: O homem que fizer estas coisas viverá por elas.'),
('acf','rm',10,6,'Mas a justiça que é pela fé diz assim: Não digas em teu coração: Quem subirá ao céu? (isto é, a trazer do alto a Cristo. )'),
('acf','rm',10,7,'Ou: Quem descerá ao abismo? (isto é, a tornar a trazer dentre os mortos a Cristo. )'),
('acf','rm',10,8,'Mas que diz? A palavra está junto de ti, na tua boca e no teu coração; esta é a palavra da fé, que pregamos,'),
('acf','rm',10,9,'A saber: Se com a tua boca confessares ao Senhor Jesus, e em teu coração creres que Deus o ressuscitou dentre os mortos, serás salvo.'),
('acf','rm',10,10,'Visto que com o coração se crê para a justiça, e com a boca se faz confissão para a salvação.'),
('acf','rm',10,11,'Porque a Escritura diz: Todo aquele que nele crer não será confundido.'),
('acf','rm',10,12,'Porquanto não há diferença entre judeu e grego; porque um mesmo é o Senhor de todos, rico para com todos os que o invocam.'),
('acf','rm',10,13,'Porque todo aquele que invocar o nome do Senhor será salvo.'),
('acf','rm',10,14,'Como, pois, invocarão aquele em quem não creram? e como crerão naquele de quem não ouviram? e como ouvirão, se não há quem pregue?'),
('acf','rm',10,15,'E como pregarão, se não forem enviados? como está escrito: Quão formosos os pés dos que anunciam o evangelho de paz; dos que trazem alegres novas de boas coisas.'),
('acf','rm',10,16,'Mas nem todos têm obedecido ao evangelho; pois Isaías diz: Senhor, quem creu na nossa pregação?'),
('acf','rm',10,17,'De sorte que a fé é pelo ouvir, e o ouvir pela palavra de Deus.'),
('acf','rm',10,18,'Mas digo: Porventura não ouviram? Sim, por certo, pois Por toda a terra saiu a voz deles,E as suas palavras até aos confins do mundo.'),
('acf','rm',10,19,'Mas digo: Porventura Israel não o soube? Primeiramente diz Moisés:Eu vos porei em ciúmes com aqueles que não são povo,Com gente insensata vos provocarei à ira.'),
('acf','rm',10,20,'E Isaías ousadamente diz:Fui achado pelos que não me buscavam,Fui manifestado aos que por mim não perguntavam.'),
('acf','rm',10,21,'Mas para Israel diz:Todo o dia estendi as minhas mãos a um povo rebelde e contradizente.'),
('acf','rm',11,1,'Digo, pois: Porventura rejeitou Deus o seu povo? De modo nenhum; porque também eu sou israelita, da descendência de Abraão, da tribo de Benjamim.'),
('acf','rm',11,2,'Deus não rejeitou o seu povo, que antes conheceu. Ou não sabeis o que a Escritura diz de Elias, como fala a Deus contra Israel, dizendo:'),
('acf','rm',11,3,'Senhor, mataram os teus profetas, e derribaram os teus altares; e só eu fiquei, e buscam a minha alma?'),
('acf','rm',11,4,'Mas que lhe diz a resposta divina? Reservei para mim sete mil homens, que não dobraram os joelhos a Baal.'),
('acf','rm',11,5,'Assim, pois, também agora neste tempo ficou um remanescente, segundo a eleição da graça.'),
('acf','rm',11,6,'Mas se é por graça, já não é pelas obras; de outra maneira, a graça já não é graça. Se, porém, é pelas obras, já não é mais graça; de outra maneira a obra já não é obra.'),
('acf','rm',11,7,'Pois quê? O que Israel buscava não o alcançou; mas os eleitos o alcançaram, e os outros foram endurecidos.'),
('acf','rm',11,8,'Como está escrito: Deus lhes deu espírito de profundo sono, olhos para não verem, e ouvidos para não ouvirem, até ao dia de hoje.'),
('acf','rm',11,9,'E Davi diz: Torne-se-lhes a sua mesa em laço, e em armadilha, E em tropeço, por sua retribuição;'),
('acf','rm',11,10,'Escureçam-se-lhes os olhos para não verem, E encurvem-se-lhes continuamente as costas.'),
('acf','rm',11,11,'Digo, pois: Porventura tropeçaram, para que caíssem? De modo nenhum, mas pela sua queda veio a salvação aos gentios, para os incitar à emulação.'),
('acf','rm',11,12,'E se a sua queda é a riqueza do mundo, e a sua diminuição a riqueza dos gentios, quanto mais a sua plenitude!'),
('acf','rm',11,13,'Porque convosco falo, gentios, que, enquanto for apóstolo dos gentios, exalto o meu ministério;'),
('acf','rm',11,14,'Para ver se de alguma maneira posso incitar à emulação os da minha carne e salvar alguns deles.'),
('acf','rm',11,15,'Porque, se a sua rejeição é a reconciliação do mundo, qual será a sua admissão, senão a vida dentre os mortos?'),
('acf','rm',11,16,'E, se as primícias são santas, também a massa o é; se a raiz é santa, também os ramos o são.'),
('acf','rm',11,17,'E se alguns dos ramos foram quebrados, e tu, sendo zambujeiro, foste enxertado em lugar deles, e feito participante da raiz e da seiva da oliveira,'),
('acf','rm',11,18,'Não te glories contra os ramos; e, se contra eles te gloriares, não és tu que sustentas a raiz, mas a raiz a ti.'),
('acf','rm',11,19,'Dirás, pois: Os ramos foram quebrados, para que eu fosse enxertado.'),
('acf','rm',11,20,'Está bem; pela sua incredulidade foram quebrados, e tu estás em pé pela fé. Então não te ensoberbeças, mas teme.'),
('acf','rm',11,21,'Porque, se Deus não poupou os ramos naturais, teme que não te poupe a ti também.'),
('acf','rm',11,22,'Considera, pois, a bondade e a severidade de Deus: para com os que caíram, severidade; mas para contigo, benignidade, se permaneceres na sua benignidade; de outra maneira também tu serás cortado.'),
('acf','rm',11,23,'E também eles, se não permanecerem na incredulidade, serão enxertados; porque poderoso é Deus para os tornar a enxertar.'),
('acf','rm',11,24,'Porque, se tu foste cortado do natural zambujeiro e, contra a natureza, enxertado na boa oliveira, quanto mais esses, que são naturais, serão enxertados na sua própria oliveira!'),
('acf','rm',11,25,'Porque não quero, irmãos, que ignoreis este segredo (para que não presumais de vós mesmos): que o endurecimento veio em parte sobre Israel, até que a plenitude dos gentios haja entrado.'),
('acf','rm',11,26,'E assim todo o Israel será salvo, como está escrito: De Sião virá o Libertador, E desviará de Jacó as impiedades.'),
('acf','rm',11,27,'E esta será a minha aliança com eles, Quando eu tirar os seus pecados.'),
('acf','rm',11,28,'Assim que, quanto ao evangelho, são inimigos por causa de vós; mas, quanto à eleição, amados por causa dos pais.'),
('acf','rm',11,29,'Porque os dons e a vocação de Deus são sem arrependimento.'),
('acf','rm',11,30,'Porque assim como vós também antigamente fostes desobedientes a Deus, mas agora alcançastes misericórdia pela desobediência deles,'),
('acf','rm',11,31,'Assim também estes agora foram desobedientes, para também alcançarem misericórdia pela misericórdia a vós demonstrada.'),
('acf','rm',11,32,'Porque Deus encerrou a todos debaixo da desobediência, para com todos usar de misericórdia.'),
('acf','rm',11,33,'Ó profundidade das riquezas, tanto da sabedoria, como da ciência de Deus! Quão insondáveis são os seus juízos, e quão inescrutáveis os seus caminhos!'),
('acf','rm',11,34,'Por que quem compreendeu a mente do Senhor? ou quem foi seu conselheiro?'),
('acf','rm',11,35,'Ou quem lhe deu primeiro a ele, para que lhe seja recompensado?'),
('acf','rm',11,36,'Porque dele e por ele, e para ele, são todas as coisas; glória, pois, a ele eternamente. Amém.'),
('acf','rm',12,1,'Rogo-vos, pois, irmãos, pela compaixão de Deus, que apresenteis os vossos corpos em sacrifício vivo, santo e agradável a Deus, que é o vosso culto racional.'),
('acf','rm',12,2,'E não sede conformados com este mundo, mas sede transformados pela renovação do vosso entendimento, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus.'),
('acf','rm',12,3,'Porque pela graça que me é dada, digo a cada um dentre vós que não pense de si mesmo além do que convém; antes, pense com moderação, conforme a medida da fé que Deus repartiu a cada um.'),
('acf','rm',12,4,'Porque assim como em um corpo temos muitos membros, e nem todos os membros têm a mesma operação,'),
('acf','rm',12,5,'Assim nós, que somos muitos, somos um só corpo em Cristo, mas individualmente somos membros uns dos outros.'),
('acf','rm',12,6,'De modo que, tendo diferentes dons, segundo a graça que nos é dada, se é profecia, seja ela segundo a medida da fé;'),
('acf','rm',12,7,'Se é ministério, seja em ministrar; se é ensinar, haja dedicação ao ensino;'),
('acf','rm',12,8,'Ou o que exorta, use esse dom em exortar; o que reparte, faça-o com liberalidade; o que preside, com cuidado; o que exercita misericórdia, com alegria.'),
('acf','rm',12,9,'O amor seja não fingido. Aborrecei o mal e apegai-vos ao bem.'),
('acf','rm',12,10,'Amai-vos cordialmente uns aos outros com amor fraternal, preferindo-vos em honra uns aos outros.'),
('acf','rm',12,11,'Não sejais vagarosos no cuidado; sede fervorosos no espírito, servindo ao Senhor;'),
('acf','rm',12,12,'Alegrai-vos na esperança, sede pacientes na tribulação, perseverai na oração;'),
('acf','rm',12,13,'Comunicai com os santos nas suas necessidades, segui a hospitalidade;'),
('acf','rm',12,14,'Abençoai aos que vos perseguem, abençoai, e não amaldiçoeis.'),
('acf','rm',12,15,'Alegrai-vos com os que se alegram; e chorai com os que choram;'),
('acf','rm',12,16,'Sede unânimes entre vós; não ambicioneis coisas altas, mas acomodai-vos às humildes; não sejais sábios em vós mesmos;'),
('acf','rm',12,17,'A ninguém torneis mal por mal; procurai as coisas honestas, perante todos os homens.'),
('acf','rm',12,18,'Se for possível, quanto estiver em vós, tende paz com todos os homens.'),
('acf','rm',12,19,'Não vos vingueis a vós mesmos, amados, mas dai lugar à ira, porque está escrito: Minha é a vingança; eu recompensarei, diz o Senhor.'),
('acf','rm',12,20,'Portanto, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber; porque, fazendo isto, amontoarás brasas de fogo sobre a sua cabeça.'),
('acf','rm',12,21,'Não te deixes vencer do mal, mas vence o mal com o bem.'),
('acf','rm',13,1,'Toda a alma esteja sujeita às potestades superiores; porque não há potestade que não venha de Deus; e as potestades que há foram ordenadas por Deus.'),
('acf','rm',13,2,'Por isso quem resiste à potestade resiste à ordenação de Deus; e os que resistem trarão sobre si mesmos a condenação.'),
('acf','rm',13,3,'Porque os magistrados não são terror para as boas obras, mas para as más. Queres tu, pois, não temer a potestade? Faze o bem, e terás louvor dela.'),
('acf','rm',13,4,'Porque ela é ministro de Deus para teu bem. Mas, se fizeres o mal, teme, pois não traz debalde a espada; porque é ministro de Deus, e vingador para castigar o que faz o mal.'),
('acf','rm',13,5,'Portanto é necessário que lhe estejais sujeitos, não somente pelo castigo, mas também pela consciência.'),
('acf','rm',13,6,'Por esta razão também pagais tributos, porque são ministros de Deus, atendendo sempre a isto mesmo.'),
('acf','rm',13,7,'Portanto, dai a cada um o que deveis: a quem tributo, tributo; a quem imposto, imposto; a quem temor, temor; a quem honra, honra.'),
('acf','rm',13,8,'A ninguém devais coisa alguma, a não ser o amor com que vos ameis uns aos outros; porque quem ama aos outros cumpriu a lei.'),
('acf','rm',13,9,'Com efeito: Não adulterarás, não matarás, não furtarás, não darás falso testemunho, não cobiçarás; e se há algum outro mandamento, tudo nesta palavra se resume: Amarás ao teu próximo como a ti mesmo.'),
('acf','rm',13,10,'O amor não faz mal ao próximo. De sorte que o cumprimento da lei é o amor.'),
('acf','rm',13,11,'E isto digo, conhecendo o tempo, que já é hora de despertarmos do sono; porque a nossa salvação está agora mais perto de nós do que quando aceitamos a fé.'),
('acf','rm',13,12,'A noite é passada, e o dia é chegado. Rejeitemos, pois, as obras das trevas, e vistamo-nos das armas da luz.'),
('acf','rm',13,13,'Andemos honestamente, como de dia; não em glutonarias, nem em bebedeiras, nem em desonestidades, nem em dissoluções, nem em contendas e inveja.'),
('acf','rm',13,14,'Mas revesti-vos do Senhor Jesus Cristo, e não tenhais cuidado da carne em suas concupiscências.'),
('acf','rm',14,1,'Ora, quanto ao que está enfermo na fé, recebei-o, não em contendas sobre dúvidas.'),
('acf','rm',14,2,'Porque um crê que de tudo se pode comer, e outro, que é fraco, come legumes.'),
('acf','rm',14,3,'O que come não despreze o que não come; e o que não come, não julgue o que come; porque Deus o recebeu por seu.'),
('acf','rm',14,4,'Quem és tu, que julgas o servo alheio? Para seu próprio senhor ele está em pé ou cai. Mas estará firme, porque poderoso é Deus para o firmar.'),
('acf','rm',14,5,'Um faz diferença entre dia e dia, mas outro julga iguais todos os dias. Cada um esteja inteiramente seguro em sua própria mente.'),
('acf','rm',14,6,'Aquele que faz caso do dia, para o Senhor o faz e o que não faz caso do dia para o Senhor o não faz. O que come, para o Senhor come, porque dá graças a Deus; e o que não come, para o Senhor não come, e dá graças a Deus.'),
('acf','rm',14,7,'Porque nenhum de nós vive para si, e nenhum morre para si.'),
('acf','rm',14,8,'Porque, se vivemos, para o Senhor vivemos; se morremos, para o Senhor morremos. De sorte que, ou vivamos ou morramos, somos do Senhor.'),
('acf','rm',14,9,'Porque foi para isto que morreu Cristo, e ressurgiu, e tornou a viver, para ser Senhor, tanto dos mortos, como dos vivos.'),
('acf','rm',14,10,'Mas tu, por que julgas teu irmão? Ou tu, também, por que desprezas teu irmão? Pois todos havemos de comparecer ante o tribunal de Cristo.'),
('acf','rm',14,11,'Porque está escrito:Como eu vivo, diz o Senhor, que todo o joelho se dobrará a mim,E toda a língua confessará a Deus.'),
('acf','rm',14,12,'De maneira que cada um de nós dará conta de si mesmo a Deus.'),
('acf','rm',14,13,'Assim que não nos julguemos mais uns aos outros; antes seja o vosso propósito não pôr tropeço ou escândalo ao irmão.'),
('acf','rm',14,14,'Eu sei, e estou certo no Senhor Jesus, que nenhuma coisa é de si mesma imunda, a não ser para aquele que a tem por imunda; para esse é imunda.'),
('acf','rm',14,15,'Mas, se por causa da comida se contrista teu irmão, já não andas conforme o amor. Não destruas por causa da tua comida aquele por quem Cristo morreu.'),
('acf','rm',14,16,'Não seja, pois, blasfemado o vosso bem;'),
('acf','rm',14,17,'Porque o reino de Deus não é comida nem bebida, mas justiça, e paz, e alegria no Espírito Santo.'),
('acf','rm',14,18,'Porque quem nisto serve a Cristo agradável é a Deus e aceito aos homens.'),
('acf','rm',14,19,'Sigamos, pois, as coisas que servem para a paz e para a edificação de uns para com os outros.'),
('acf','rm',14,20,'Não destruas por causa da comida a obra de Deus. É verdade que tudo é limpo, mas mal vai para o homem que come com escândalo.'),
('acf','rm',14,21,'Bom é não comer carne, nem beber vinho, nem fazer outras coisas em que teu irmão tropece, ou se escandalize, ou se enfraqueça.'),
('acf','rm',14,22,'Tens tu fé? Tem-na em ti mesmo diante de Deus. Bem-aventurado aquele que não se condena a si mesmo naquilo que aprova.'),
('acf','rm',14,23,'Mas aquele que tem dúvidas, se come está condenado, porque não come por fé; e tudo o que não é de fé é pecado.'),
('acf','rm',15,1,'Mas nós, que somos fortes, devemos suportar as fraquezas dos fracos, e não agradar a nós mesmos.'),
('acf','rm',15,2,'Portanto cada um de nós agrade ao seu próximo no que é bom para edificação.'),
('acf','rm',15,3,'Porque também Cristo não agradou a si mesmo, mas, como está escrito: Sobre mim caíram as injúrias dos que te injuriavam.'),
('acf','rm',15,4,'Porque tudo o que dantes foi escrito, para nosso ensino foi escrito, para que pela paciência e consolação das Escrituras tenhamos esperança.'),
('acf','rm',15,5,'Ora, o Deus de paciência e consolação vos conceda o mesmo sentimento uns para com os outros, segundo Cristo Jesus,'),
('acf','rm',15,6,'Para que concordes, a uma boca, glorifiqueis ao Deus e Pai de nosso Senhor Jesus Cristo.'),
('acf','rm',15,7,'Portanto recebei-vos uns aos outros, como também Cristo nos recebeu para glória de Deus.'),
('acf','rm',15,8,'Digo, pois, que Jesus Cristo foi ministro da circuncisão, por causa da verdade de Deus, para que confirmasse as promessas feitas aos pais;'),
('acf','rm',15,9,'E para que os gentios glorifiquem a Deus pela sua misericórdia, como está escrito:Portanto eu te louvarei entre os gentios,E cantarei ao teu nome.'),
('acf','rm',15,10,'E outra vez diz:Alegrai-vos, gentios, com o seu povo.'),
('acf','rm',15,11,'E outra vez:Louvai ao Senhor, todos os gentios,E celebrai-o todos os povos.'),
('acf','rm',15,12,'Outra vez diz Isaías:Uma raiz em Jessé haverá,E naquele que se levantar para reger os gentios,Os gentios esperarão.'),
('acf','rm',15,13,'Ora o Deus de esperança vos encha de todo o gozo e paz em crença, para que abundeis em esperança pela virtude do Espírito Santo.'),
('acf','rm',15,14,'Eu próprio, meus irmãos, certo estou, a respeito de vós, que vós mesmos estais cheios de bondade, cheios de todo o conhecimento, podendo admoestar-vos uns aos outros.'),
('acf','rm',15,15,'Mas, irmãos, em parte vos escrevi mais ousadamente, como para vos trazer outra vez isto à memória, pela graça que por Deus me foi dada;'),
('acf','rm',15,16,'Que seja ministro de Jesus Cristo para os gentios, ministrando o evangelho de Deus, para que seja agradável a oferta dos gentios, santificada pelo Espírito Santo.'),
('acf','rm',15,17,'De sorte que tenho glória em Jesus Cristo nas coisas que pertencem a Deus.'),
('acf','rm',15,18,'Porque não ousarei dizer coisa alguma, que Cristo por mim não tenha feito, para fazer obedientes os gentios, por palavra e por obras;'),
('acf','rm',15,19,'Pelo poder dos sinais e prodígios, e pela virtude do Espírito de Deus; de maneira que desde Jerusalém, e arredores, até ao Ilírico, tenho pregado o evangelho de Jesus Cristo.'),
('acf','rm',15,20,'E desta maneira me esforcei por anunciar o evangelho, não onde Cristo foi nomeado, para não edificar sobre fundamento alheio;'),
('acf','rm',15,21,'Antes, como está escrito:Aqueles a quem não foi anunciado, o verão,E os que não ouviram o entenderão.'),
('acf','rm',15,22,'Por isso também muitas vezes tenho sido impedido de ir ter convosco.'),
('acf','rm',15,23,'Mas agora, que não tenho mais demora nestes sítios, e tendo já há muitos anos grande desejo de ir ter convosco,'),
('acf','rm',15,24,'Quando partir para Espanha irei ter convosco; pois espero que de passagem vos verei, e que para lá seja encaminhado por vós, depois de ter gozado um pouco da vossa companhia.'),
('acf','rm',15,25,'Mas agora vou a Jerusalém para ministrar aos santos.'),
('acf','rm',15,26,'Porque pareceu bem à macedônia e à Acaia fazerem uma coleta para os pobres dentre os santos que estão em Jerusalém.'),
('acf','rm',15,27,'Isto lhes pareceu bem, como devedores que são para com eles. Porque, se os gentios foram participantes dos seus bens espirituais, devem também ministrar-lhes os temporais.'),
('acf','rm',15,28,'Assim que, concluído isto, e havendo-lhes consignado este fruto, de lá, passando por vós, irei à Espanha.'),
('acf','rm',15,29,'E bem sei que, indo ter convosco, chegarei com a plenitude da bênção do evangelho de Cristo.'),
('acf','rm',15,30,'E rogo-vos, irmãos, por nosso Senhor Jesus Cristo e pelo amor do Espírito, que combatais comigo nas vossas orações por mim a Deus;'),
('acf','rm',15,31,'Para que seja livre dos rebeldes que estão na Judéia, e que esta minha administração, que em Jerusalém faço, seja bem aceita pelos santos;'),
('acf','rm',15,32,'A fim de que, pela vontade de Deus, chegue a vós com alegria, e possa recrear-me convosco.'),
('acf','rm',15,33,'E o Deus de paz seja com todos vós. Amém.'),
('acf','rm',16,1,'Recomendo-vos, pois, Febe, nossa irmã, a qual serve na igreja que está em Cencréia,'),
('acf','rm',16,2,'Para que a recebais no Senhor, como convém aos santos, e a ajudeis em qualquer coisa que de vós necessitar; porque tem hospedado a muitos, como também a mim mesmo.'),
('acf','rm',16,3,'Saudai a Priscila e a Áqüila, meus cooperadores em Cristo Jesus,'),
('acf','rm',16,4,'Os quais pela minha vida expuseram as suas cabeças; o que não só eu lhes agradeço, mas também todas as igrejas dos gentios.'),
('acf','rm',16,5,'Saudai também a igreja que está em sua casa. Saudai a Epêneto, meu amado, que é as primícias da Acáia em Cristo.'),
('acf','rm',16,6,'Saudai a Maria, que trabalhou muito por nós.'),
('acf','rm',16,7,'Saudai a Andrônico e a Júnias, meus parentes e meus companheiros na prisão, os quais se distinguiram entre os apóstolos e que foram antes de mim em Cristo.'),
('acf','rm',16,8,'Saudai a Amplias, meu amado no Senhor.'),
('acf','rm',16,9,'Saudai a Urbano, nosso cooperador em Cristo, e a Estáquis, meu amado.'),
('acf','rm',16,10,'Saudai a Apeles, aprovado em Cristo. Saudai aos da família de Aristóbulo.'),
('acf','rm',16,11,'Saudai a Herodião, meu parente. Saudai aos da família de Narciso, os que estão no Senhor.'),
('acf','rm',16,12,'Saudai a Trifena e a Trifosa, as quais trabalham no Senhor. Saudai à amada Pérside, a qual muito trabalhou no Senhor.'),
('acf','rm',16,13,'Saudai a Rufo, eleito no Senhor, e a sua mãe e minha.'),
('acf','rm',16,14,'Saudai a Asíncrito, a Flegonte, a Hermes, a Pátrobas, a Hermas, e aos irmãos que estão com eles.'),
('acf','rm',16,15,'Saudai a Filólogo e a Júlia, a Nereu e a sua irmã, e a Olimpas, e a todos os santos que com eles estão.'),
('acf','rm',16,16,'Saudai-vos uns aos outros com santo ósculo. As igrejas de Cristo vos saúdam.'),
('acf','rm',16,17,'E rogo-vos, irmãos, que noteis os que promovem dissensões e escândalos contra a doutrina que aprendestes; desviai-vos deles.'),
('acf','rm',16,18,'Porque os tais não servem a nosso Senhor Jesus Cristo, mas ao seu ventre; e com suaves palavras e lisonjas enganam os corações dos simples.'),
('acf','rm',16,19,'Quanto à vossa obediência, é ela conhecida de todos. Comprazo-me, pois, em vós; e quero que sejais sábios no bem, mas simples no mal.'),
('acf','rm',16,20,'E o Deus de paz esmagará em breve Satanás debaixo dos vossos pés. A graça de nosso Senhor Jesus Cristo seja convosco. Amém.'),
('acf','rm',16,21,'Saúdam-vos Timóteo, meu cooperador, e Lúcio, Jasom e Sosípatro, meus parentes.'),
('acf','rm',16,22,'Eu, Tércio, que esta carta escrevi, vos saúdo no Senhor.'),
('acf','rm',16,23,'Saúda-vos Gaio, meu hospedeiro, e de toda a igreja. Saúda-vos Erasto, procurador da cidade, e também o irmão Quarto.'),
('acf','rm',16,24,'A graça de nosso Senhor Jesus Cristo seja com todos vós. Amém.'),
('acf','rm',16,25,'Ora, àquele que é poderoso para vos confirmar segundo o meu evangelho e a pregação de Jesus Cristo, conforme a revelação do mistério que desde tempos eternos esteve oculto,'),
('acf','rm',16,26,'Mas que se manifestou agora, e se notificou pelas Escrituras dos profetas, segundo o mandamento do Deus eterno, a todas as nações para obediência da fé;'),
('acf','rm',16,27,'Ao único Deus, sábio, seja dada glória por Jesus Cristo para todo o sempre. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1co',1,1,'Paulo (chamado apóstolo de Jesus Cristo, pela vontade de Deus), e o irmão Sóstenes,'),
('acf','1co',1,2,'À igreja de Deus que está em Corinto, aos santificados em Cristo Jesus, chamados santos, com todos os que em todo o lugar invocam o nome de nosso Senhor Jesus Cristo, Senhor deles e nosso:'),
('acf','1co',1,3,'Graça e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.'),
('acf','1co',1,4,'Sempre dou graças ao meu Deus por vós pela graça de Deus que vos foi dada em Jesus Cristo.'),
('acf','1co',1,5,'Porque em tudo fostes enriquecidos nele, em toda a palavra e em todo o conhecimento'),
('acf','1co',1,6,'(Como o testemunho de Cristo foi mesmo confirmado entre vós).'),
('acf','1co',1,7,'De maneira que nenhum dom vos falta, esperando a manifestação de nosso Senhor Jesus Cristo,'),
('acf','1co',1,8,'O qual vos confirmará também até ao fim, para serdes irrepreensíveis no dia de nosso Senhor Jesus Cristo.'),
('acf','1co',1,9,'Fiel é Deus, pelo qual fostes chamados para a comunhão de seu Filho Jesus Cristo nosso Senhor.'),
('acf','1co',1,10,'Rogo-vos, porém, irmãos, pelo nome de nosso Senhor Jesus Cristo, que digais todos uma mesma coisa, e que não haja entre vós dissensões; antes sejais unidos em um mesmo pensamento e em um mesmo parecer.'),
('acf','1co',1,11,'Porque a respeito de vós, irmãos meus, me foi comunicado pelos da família de Cloé que há contendas entre vós.'),
('acf','1co',1,12,'Quero dizer com isto, que cada um de vós diz: Eu sou de Paulo, e eu de Apolo, e eu de Cefas, e eu de Cristo.'),
('acf','1co',1,13,'Está Cristo dividido? foi Paulo crucificado por vós? ou fostes vós batizados em nome de Paulo?'),
('acf','1co',1,14,'Dou graças a Deus, porque a nenhum de vós batizei, senão a Crispo e a Gaio,'),
('acf','1co',1,15,'Para que ninguém diga que fostes batizados em meu nome.'),
('acf','1co',1,16,'E batizei também a família de Estéfanas; além destes, não sei se batizei algum outro.'),
('acf','1co',1,17,'Porque Cristo enviou-me, não para batizar, mas para evangelizar; não em sabedoria de palavras, para que a cruz de Cristo se não faça vã.'),
('acf','1co',1,18,'Porque a palavra da cruz é loucura para os que perecem; mas para nós, que somos salvos, é o poder de Deus.'),
('acf','1co',1,19,'Porque está escrito: Destruirei a sabedoria dos sábios, E aniquilarei a inteligência dos inteligentes.'),
('acf','1co',1,20,'Onde está o sábio? Onde está o escriba? Onde está o inquiridor deste século? Porventura não tornou Deus louca a sabedoria deste mundo?'),
('acf','1co',1,21,'Visto como na sabedoria de Deus o mundo não conheceu a Deus pela sua sabedoria, aprouve a Deus salvar os crentes pela loucura da pregação.'),
('acf','1co',1,22,'Porque os judeus pedem sinal, e os gregos buscam sabedoria;'),
('acf','1co',1,23,'Mas nós pregamos a Cristo crucificado, que é escândalo para os judeus, e loucura para os gregos.'),
('acf','1co',1,24,'Mas para os que são chamados, tanto judeus como gregos, lhes pregamos a Cristo, poder de Deus, e sabedoria de Deus.'),
('acf','1co',1,25,'Porque a loucura de Deus é mais sábia do que os homens; e a fraqueza de Deus é mais forte do que os homens.'),
('acf','1co',1,26,'Porque, vede, irmãos, a vossa vocação, que não são muitos os sábios segundo a carne, nem muitos os poderosos, nem muitos os nobres que são chamados.'),
('acf','1co',1,27,'Mas Deus escolheu as coisas loucas deste mundo para confundir as sábias; e Deus escolheu as coisas fracas deste mundo para confundir as fortes;'),
('acf','1co',1,28,'E Deus escolheu as coisas vis deste mundo, e as desprezíveis, e as que não são, para aniquilar as que são;'),
('acf','1co',1,29,'Para que nenhuma carne se glorie perante ele.'),
('acf','1co',1,30,'Mas vós sois dele, em Jesus Cristo, o qual para nós foi feito por Deus sabedoria, e justiça, e santificação, e redenção;'),
('acf','1co',1,31,'Para que, como está escrito: Aquele que se gloria glorie-se no Senhor.'),
('acf','1co',2,1,'E eu, irmãos, quando fui ter convosco, anunciando-vos o testemunho de Deus, não fui com sublimidade de palavras ou de sabedoria.'),
('acf','1co',2,2,'Porque nada me propus saber entre vós, senão a Jesus Cristo, e este crucificado.'),
('acf','1co',2,3,'E eu estive convosco em fraqueza, e em temor, e em grande tremor.'),
('acf','1co',2,4,'E a minha palavra, e a minha pregação, não consistiram em palavras persuasivas de sabedoria humana, mas em demonstração de Espírito e de poder;'),
('acf','1co',2,5,'Para que a vossa fé não se apoiasse em sabedoria dos homens, mas no poder de Deus.'),
('acf','1co',2,6,'Todavia falamos sabedoria entre os perfeitos; não, porém, a sabedoria deste mundo, nem dos príncipes deste mundo, que se aniquilam;'),
('acf','1co',2,7,'Mas falamos a sabedoria de Deus, oculta em mistério, a qual Deus ordenou antes dos séculos para nossa glória;'),
('acf','1co',2,8,'A qual nenhum dos príncipes deste mundo conheceu; porque, se a conhecessem, nunca crucificariam ao Senhor da glória.'),
('acf','1co',2,9,'Mas, como está escrito:As coisas que o olho não viu, e o ouvido não ouviu,e não subiram ao coração do homem,são as que Deus preparou para os que o amam.'),
('acf','1co',2,10,'Mas Deus no-las revelou pelo seu Espírito; porque o Espírito penetra todas as coisas, ainda as profundezas de Deus.'),
('acf','1co',2,11,'Porque, qual dos homens sabe as coisas do homem, senão o espírito do homem, que nele está? Assim também ninguém sabe as coisas de Deus, senão o Espírito de Deus.'),
('acf','1co',2,12,'Mas nós não recebemos o espírito do mundo, mas o Espírito que provém de Deus, para que pudéssemos conhecer o que nos é dado gratuitamente por Deus.'),
('acf','1co',2,13,'As quais também falamos, não com palavras que a sabedoria humana ensina, mas com as que o Espírito Santo ensina, comparando as coisas espirituais com as espirituais.'),
('acf','1co',2,14,'Ora, o homem natural não compreende as coisas do Espírito de Deus, porque lhe parecem loucura; e não pode entendê-las, porque elas se discernem espiritualmente.'),
('acf','1co',2,15,'Mas o que é espiritual discerne bem tudo, e ele de ninguém é discernido.'),
('acf','1co',2,16,'Porque, quem conheceu a mente do Senhor, para que possa instruí-lo? Mas nós temos a mente de Cristo.'),
('acf','1co',3,1,'E eu, irmãos, não vos pude falar como a espirituais, mas como a carnais, como a meninos em Cristo.'),
('acf','1co',3,2,'Com leite vos criei, e não com carne, porque ainda não podíeis, nem tampouco ainda agora podeis,'),
('acf','1co',3,3,'Porque ainda sois carnais; pois, havendo entre vós inveja, contendas e dissensões, não sois porventura carnais, e não andais segundo os homens?'),
('acf','1co',3,4,'Porque, dizendo um: Eu sou de Paulo; e outro: Eu de Apolo; porventura não sois carnais?'),
('acf','1co',3,5,'Pois, quem é Paulo, e quem é Apolo, senão ministros pelos quais crestes, e conforme o que o Senhor deu a cada um?'),
('acf','1co',3,6,'Eu plantei, Apolo regou; mas Deus deu o crescimento.'),
('acf','1co',3,7,'Por isso, nem o que planta é alguma coisa, nem o que rega, mas Deus, que dá o crescimento.'),
('acf','1co',3,8,'Ora, o que planta e o que rega são um; mas cada um receberá o seu galardão segundo o seu trabalho.'),
('acf','1co',3,9,'Porque nós somos cooperadores de Deus; vós sois lavoura de Deus e edifício de Deus.'),
('acf','1co',3,10,'Segundo a graça de Deus que me foi dada, pus eu, como sábio arquiteto, o fundamento, e outro edifica sobre ele; mas veja cada um como edifica sobre ele.'),
('acf','1co',3,11,'Porque ninguém pode pôr outro fundamento além do que já está posto, o qual é Jesus Cristo.'),
('acf','1co',3,12,'E, se alguém sobre este fundamento formar um edifício de ouro, prata, pedras preciosas, madeira, feno, palha,'),
('acf','1co',3,13,'A obra de cada um se manifestará; na verdade o dia a declarará, porque pelo fogo será descoberta; e o fogo provará qual seja a obra de cada um.'),
('acf','1co',3,14,'Se a obra que alguém edificou nessa parte permanecer, esse receberá galardão.'),
('acf','1co',3,15,'Se a obra de alguém se queimar, sofrerá detrimento; mas o tal será salvo, todavia como pelo fogo.'),
('acf','1co',3,16,'Não sabeis vós que sois o templo de Deus e que o Espírito de Deus habita em vós?'),
('acf','1co',3,17,'Se alguém destruir o templo de Deus, Deus o destruirá; porque o templo de Deus, que sois vós, é santo.'),
('acf','1co',3,18,'Ninguém se engane a si mesmo. Se alguém dentre vós se tem por sábio neste mundo, faça-se louco para ser sábio.'),
('acf','1co',3,19,'Porque a sabedoria deste mundo é loucura diante de Deus; pois está escrito: Ele apanha os sábios na sua própria astúcia.'),
('acf','1co',3,20,'E outra vez: O Senhor conhece os pensamentos dos sábios, que são vãos.'),
('acf','1co',3,21,'Portanto, ninguém se glorie nos homens; porque tudo é vosso;'),
('acf','1co',3,22,'Seja Paulo, seja Apolo, seja Cefas, seja o mundo, seja a vida, seja a morte, seja o presente, seja o futuro; tudo é vosso,'),
('acf','1co',3,23,'E vós de Cristo, e Cristo de Deus.'),
('acf','1co',4,1,'Que os homens nos considerem como ministros de Cristo, e despenseiros dos mistérios de Deus.'),
('acf','1co',4,2,'Além disso requer-se dos despenseiros que cada um se ache fiel.'),
('acf','1co',4,3,'Todavia, a mim mui pouco se me dá de ser julgado por vós, ou por algum juízo humano; nem eu tampouco a mim mesmo me julgo.'),
('acf','1co',4,4,'Porque em nada me sinto culpado; mas nem por isso me considero justificado, pois quem me julga é o Senhor.'),
('acf','1co',4,5,'Portanto, nada julgueis antes de tempo, até que o Senhor venha, o qual também trará à luz as coisas ocultas das trevas, e manifestará os desígnios dos corações; e então cada um receberá de Deus o louvor.'),
('acf','1co',4,6,'E eu, irmãos, apliquei estas coisas, por semelhança, a mim e a Apolo, por amor de vós; para que em nós aprendais a não ir além do que está escrito, não vos ensoberbecendo a favor de um contra outro.'),
('acf','1co',4,7,'Porque, quem te faz diferente? E que tens tu que não tenhas recebido? E, se o recebeste, por que te glorias, como se não o houveras recebido?'),
('acf','1co',4,8,'Já estais fartos! já estais ricos! sem nós reinais! e quisera reinásseis para que também nós viéssemos a reinar convosco!'),
('acf','1co',4,9,'Porque tenho para mim, que Deus a nós, apóstolos, nos pôs por últimos, como condenados à morte; pois somos feitos espetáculo ao mundo, aos anjos, e aos homens.'),
('acf','1co',4,10,'Nós somos loucos por amor de Cristo, e vós sábios em Cristo; nós fracos, e vós fortes; vós ilustres, e nós vis.'),
('acf','1co',4,11,'Até esta presente hora sofremos fome, e sede, e estamos nus, e recebemos bofetadas, e não temos pousada certa,'),
('acf','1co',4,12,'E nos afadigamos, trabalhando com nossas próprias mãos. Somos injuriados, e bendizemos; somos perseguidos, e sofremos;'),
('acf','1co',4,13,'Somos blasfemados, e rogamos; até ao presente temos chegado a ser como o lixo deste mundo, e como a escória de todos.'),
('acf','1co',4,14,'Não escrevo estas coisas para vos envergonhar; mas admoesto-vos como meus filhos amados.'),
('acf','1co',4,15,'Porque ainda que tivésseis dez mil aios em Cristo, não teríeis, contudo, muitos pais; porque eu pelo evangelho vos gerei em Jesus Cristo.'),
('acf','1co',4,16,'Admoesto-vos, portanto, a que sejais meus imitadores.'),
('acf','1co',4,17,'Por esta causa vos mandei Timóteo, que é meu filho amado, e fiel no Senhor, o qual vos lembrará os meus caminhos em Cristo, como por toda a parte ensino em cada igreja.'),
('acf','1co',4,18,'Mas alguns andam ensoberbecidos, como se eu não houvesse de ir ter convosco.'),
('acf','1co',4,19,'Mas em breve irei ter convosco, se o Senhor quiser, e então conhecerei, não as palavras dos que andam ensoberbecidos, mas o poder.'),
('acf','1co',4,20,'Porque o reino de Deus não consiste em palavras, mas em poder.'),
('acf','1co',4,21,'Que quereis? Irei ter convosco com vara ou com amor e espírito de mansidão?'),
('acf','1co',5,1,'Geralmente se ouve que há entre vós fornicação, e fornicação tal, que nem ainda entre os gentios se nomeia, como é haver quem possua a mulher de seu pai.'),
('acf','1co',5,2,'Estais ensoberbecidos, e nem ao menos vos entristecestes por não ter sido dentre vós tirado quem cometeu tal ação.'),
('acf','1co',5,3,'Eu, na verdade, ainda que ausente no corpo, mas presente no espírito, já determinei, como se estivesse presente, que o que tal ato praticou,'),
('acf','1co',5,4,'Em nome de nosso Senhor Jesus Cristo, juntos vós e o meu espírito, pelo poder de nosso Senhor Jesus Cristo,'),
('acf','1co',5,5,'Seja, este tal, entregue a Satanás para destruição da carne, para que o espírito seja salvo no dia do Senhor Jesus.'),
('acf','1co',5,6,'Não é boa a vossa jactância. Não sabeis que um pouco de fermento faz levedar toda a massa?'),
('acf','1co',5,7,'Alimpai-vos, pois, do fermento velho, para que sejais uma nova massa, assim como estais sem fermento. Porque Cristo, nossa páscoa, foi sacrificado por nós.'),
('acf','1co',5,8,'Por isso façamos a festa, não com o fermento velho, nem com o fermento da maldade e da malícia, mas com os ázimos da sinceridade e da verdade.'),
('acf','1co',5,9,'Já por carta vos tenho escrito, que não vos associeis com os que se prostituem;'),
('acf','1co',5,10,'Isto não quer dizer absolutamente com os devassos deste mundo, ou com os avarentos, ou com os roubadores, ou com os idólatras; porque então vos seria necessário sair do mundo.'),
('acf','1co',5,11,'Mas agora vos escrevi que não vos associeis com aquele que, dizendo-se irmão, for devasso, ou avarento, ou idólatra, ou maldizente, ou beberrão, ou roubador; com o tal nem ainda comais.'),
('acf','1co',5,12,'Porque, que tenho eu em julgar também os que estão de fora? Não julgais vós os que estão dentro?'),
('acf','1co',5,13,'Mas Deus julga os que estão de fora. Tirai pois dentre vós a esse iníquo.'),
('acf','1co',6,1,'Ousa algum de vós, tendo algum negócio contra outro, ir a juízo perante os injustos, e não perante os santos?'),
('acf','1co',6,2,'Não sabeis vós que os santos hão de julgar o mundo? Ora, se o mundo deve ser julgado por vós, sois porventura indignos de julgar as coisas mínimas?'),
('acf','1co',6,3,'Não sabeis vós que havemos de julgar os anjos? Quanto mais as coisas pertencentes a esta vida?'),
('acf','1co',6,4,'Então, se tiverdes negócios em juízo, pertencentes a esta vida, pondes para julga-los os que são de menos estima na igreja?'),
('acf','1co',6,5,'Para vos envergonhar o digo. Não há, pois, entre vós sábios, nem mesmo um, que possa julgar entre seus irmãos?'),
('acf','1co',6,6,'Mas o irmão vai a juízo com o irmão, e isto perante infiéis.'),
('acf','1co',6,7,'Na verdade é já realmente uma falta entre vós, terdes demandas uns contra os outros. Por que não sofreis antes a injustiça? Por que não sofreis antes o dano?'),
('acf','1co',6,8,'Mas vós mesmos fazeis a injustiça e fazeis o dano, e isto aos irmãos.'),
('acf','1co',6,9,'Não sabeis que os injustos não hão de herdar o reino de Deus?'),
('acf','1co',6,10,'Não erreis: nem os devassos, nem os idólatras, nem os adúlteros, nem os efeminados, nem os sodomitas, nem os ladrões, nem os avarentos, nem os bêbados, nem os maldizentes, nem os roubadores herdarão o reino de Deus.'),
('acf','1co',6,11,'E é o que alguns têm sido; mas haveis sido lavados, mas haveis sido santificados, mas haveis sido justificados em nome do Senhor Jesus, e pelo Espírito do nosso Deus.'),
('acf','1co',6,12,'Todas as coisas me são lícitas, mas nem todas as coisas convêm. Todas as coisas me são lícitas, mas eu não me deixarei dominar por nenhuma.'),
('acf','1co',6,13,'Os alimentos são para o estômago e o estômago para os alimentos; Deus, porém, aniquilará tanto um como os outros. Mas o corpo não é para a fornicação, senão para o Senhor, e o Senhor para o corpo.'),
('acf','1co',6,14,'Ora, Deus, que também ressuscitou o Senhor, nos ressuscitará a nós pelo seu poder.'),
('acf','1co',6,15,'Não sabeis vós que os vossos corpos são membros de Cristo? Tomarei, pois, os membros de Cristo, e os farei membros de uma meretriz? Não, por certo.'),
('acf','1co',6,16,'Ou não sabeis que o que se ajunta com a meretriz, faz-se um corpo com ela? Porque serão, disse, dois numa só carne.'),
('acf','1co',6,17,'Mas o que se ajunta com o Senhor é um mesmo espírito.'),
('acf','1co',6,18,'Fugi da fornicação. Todo o pecado que o homem comete é fora do corpo; mas o que fornica peca contra o seu próprio corpo.'),
('acf','1co',6,19,'Ou não sabeis que o vosso corpo é o templo do Espírito Santo, que habita em vós, proveniente de Deus, e que não sois de vós mesmos?'),
('acf','1co',6,20,'Porque fostes comprados por bom preço; glorificai, pois, a Deus no vosso corpo, e no vosso espírito, os quais pertencem a Deus.'),
('acf','1co',7,1,'Ora, quanto às coisas que me escrevestes, bom seria que o homem não tocasse em mulher;'),
('acf','1co',7,2,'Mas, por causa da fornicação, cada um tenha a sua própria mulher, e cada uma tenha o seu próprio marido.'),
('acf','1co',7,3,'O marido pague à mulher a devida benevolência, e da mesma sorte a mulher ao marido.'),
('acf','1co',7,4,'A mulher não tem poder sobre o seu próprio corpo, mas tem-no o marido; e também da mesma maneira o marido não tem poder sobre o seu próprio corpo, mas tem-no a mulher.'),
('acf','1co',7,5,'Não vos priveis um ao outro, senão por consentimento mútuo por algum tempo, para vos aplicardes ao jejum e à oração; e depois ajuntai-vos outra vez, para que Satanás não vos tente pela vossa incontinência.'),
('acf','1co',7,6,'Digo, porém, isto como que por permissão e não por mandamento.'),
('acf','1co',7,7,'Porque quereria que todos os homens fossem como eu mesmo; mas cada um tem de Deus o seu próprio dom, um de uma maneira e outro de outra.'),
('acf','1co',7,8,'Digo, porém, aos solteiros e às viúvas, que lhes é bom se ficarem como eu.'),
('acf','1co',7,9,'Mas, se não podem conter-se, casem-se. Porque é melhor casar do que abrasar-se.'),
('acf','1co',7,10,'Todavia, aos casados mando, não eu mas o Senhor, que a mulher não se aparte do marido.'),
('acf','1co',7,11,'Se, porém, se apartar, que fique sem casar, ou que se reconcilie com o marido; e que o marido não deixe a mulher.'),
('acf','1co',7,12,'Mas aos outros digo eu, não o Senhor: Se algum irmão tem mulher descrente, e ela consente em habitar com ele, não a deixe.'),
('acf','1co',7,13,'E se alguma mulher tem marido descrente, e ele consente em habitar com ela, não o deixe.'),
('acf','1co',7,14,'Porque o marido descrente é santificado pela mulher; e a mulher descrente é santificada pelo marido; de outra sorte os vossos filhos seriam imundos; mas agora são santos.'),
('acf','1co',7,15,'Mas, se o descrente se apartar, aparte-se; porque neste caso o irmão, ou irmã, não está sujeito à servidão; mas Deus chamou-nos para a paz.'),
('acf','1co',7,16,'Porque, de onde sabes, ó mulher, se salvarás teu marido? ou, de onde sabes, ó marido, se salvarás tua mulher?'),
('acf','1co',7,17,'E assim cada um ande como Deus lhe repartiu, cada um como o Senhor o chamou. É o que ordeno em todas as igrejas.'),
('acf','1co',7,18,'É alguém chamado, estando circuncidado? fique circuncidado. É alguém chamado estando incircuncidado? não se circuncide.'),
('acf','1co',7,19,'A circuncisão é nada e a incircuncisão nada é, mas, sim, a observância dos mandamentos de Deus.'),
('acf','1co',7,20,'Cada um fique na vocação em que foi chamado.'),
('acf','1co',7,21,'Foste chamado sendo servo? não te dê cuidado; e, se ainda podes ser livre, aproveita a ocasião.'),
('acf','1co',7,22,'Porque o que é chamado pelo Senhor, sendo servo, é liberto do Senhor; e da mesma maneira também o que é chamado sendo livre, servo é de Cristo.'),
('acf','1co',7,23,'Fostes comprados por bom preço; não vos façais servos dos homens.'),
('acf','1co',7,24,'Irmãos, cada um fique diante de Deus no estado em que foi chamado.'),
('acf','1co',7,25,'Ora, quanto às virgens, não tenho mandamento do Senhor; dou, porém, o meu parecer, como quem tem alcançado misericórdia do Senhor para ser fiel.'),
('acf','1co',7,26,'Tenho, pois, por bom, por causa da instante necessidade, que é bom para o homem o estar assim.'),
('acf','1co',7,27,'Estás ligado à mulher? não busques separar-te. Estás livre de mulher? não busques mulher.'),
('acf','1co',7,28,'Mas, se te casares, não pecas; e, se a virgem se casar, não peca. Todavia os tais terão tribulações na carne, e eu quereria poupar-vos.'),
('acf','1co',7,29,'Isto, porém, vos digo, irmãos, que o tempo se abrevia; o que resta é que também os que têm mulheres sejam como se não as tivessem;'),
('acf','1co',7,30,'E os que choram, como se não chorassem; e os que folgam, como se não folgassem; e os que compram, como se não possuíssem;'),
('acf','1co',7,31,'E os que usam deste mundo, como se dele não abusassem, porque a aparência deste mundo passa.'),
('acf','1co',7,32,'E bem quisera eu que estivésseis sem cuidado. O solteiro cuida das coisas do Senhor, em como há de agradar ao Senhor;'),
('acf','1co',7,33,'Mas o que é casado cuida das coisas do mundo, em como há de agradar à mulher.'),
('acf','1co',7,34,'Há diferença entre a mulher casada e a virgem. A solteira cuida das coisas do Senhor para ser santa, tanto no corpo como no espírito; porém, a casada cuida das coisas do mundo, em como há de agradar ao marido.'),
('acf','1co',7,35,'E digo isto para proveito vosso; não para vos enlaçar, mas para o que é decente e conveniente, para vos unirdes ao Senhor sem distração alguma.'),
('acf','1co',7,36,'Mas, se alguém julga que trata indignamente a sua virgem, se tiver passado a flor da idade, e se for necessário, que faça o tal o que quiser; não peca; casem-se.'),
('acf','1co',7,37,'Todavia o que está firme em seu coração, não tendo necessidade, mas com poder sobre a sua própria vontade, se resolveu no seu coração guardar a sua virgem, faz bem.'),
('acf','1co',7,38,'De sorte que, o que a dá em casamento faz bem; mas o que não a dá em casamento faz melhor.'),
('acf','1co',7,39,'A mulher casada está ligada pela lei todo o tempo que o seu marido vive; mas, se falecer o seu marido fica livre para casar com quem quiser, contanto que seja no Senhor.'),
('acf','1co',7,40,'Será, porém, mais bem-aventurada se ficar assim, segundo o meu parecer, e também eu cuido que tenho o Espírito de Deus.'),
('acf','1co',8,1,'Ora, no tocante às coisas sacrificadas aos ídolos, sabemos que todos temos ciência. A ciência incha, mas o amor edifica.'),
('acf','1co',8,2,'E, se alguém cuida saber alguma coisa, ainda não sabe como convém saber.'),
('acf','1co',8,3,'Mas, se alguém ama a Deus, esse é conhecido dele.'),
('acf','1co',8,4,'Assim que, quanto ao comer das coisas sacrificadas aos ídolos, sabemos que o ídolo nada é no mundo, e que não há outro Deus, senão um só.'),
('acf','1co',8,5,'Porque, ainda que haja também alguns que se chamem deuses, quer no céu quer na terra (como há muitos deuses e muitos senhores),'),
('acf','1co',8,6,'Todavia para nós há um só Deus, o Pai, de quem é tudo e para quem nós vivemos; e um só Senhor, Jesus Cristo, pelo qual são todas as coisas, e nós por ele.'),
('acf','1co',8,7,'Mas nem em todos há conhecimento; porque alguns até agora comem, com consciência do ídolo, coisas sacrificadas ao ídolo; e a sua consciência, sendo fraca, fica contaminada.'),
('acf','1co',8,8,'Ora a comida não nos faz agradáveis a Deus, porque, se comemos, nada temos de mais e, se não comemos, nada nos falta.'),
('acf','1co',8,9,'Mas vede que essa liberdade não seja de alguma maneira escândalo para os fracos.'),
('acf','1co',8,10,'Porque, se alguém te vir a ti, que tens ciência, sentado à mesa no templo dos ídolos, não será a consciência do que é fraco induzida a comer das coisas sacrificadas aos ídolos?'),
('acf','1co',8,11,'E pela tua ciência perecerá o irmão fraco, pelo qual Cristo morreu.'),
('acf','1co',8,12,'Ora, pecando assim contra os irmãos, e ferindo a sua fraca consciência, pecais contra Cristo.'),
('acf','1co',8,13,'Por isso, se a comida escandalizar a meu irmão, nunca mais comerei carne, para que meu irmão não se escandalize.'),
('acf','1co',9,1,'Não sou eu apóstolo? Não sou livre? Não vi eu a Jesus Cristo Senhor nosso? Não sois vós a minha obra no Senhor?'),
('acf','1co',9,2,'Se eu não sou apóstolo para os outros, ao menos o sou para vós; porque vós sois o selo do meu apostolado no Senhor.'),
('acf','1co',9,3,'Esta é minha defesa para com os que me condenam.'),
('acf','1co',9,4,'Não temos nós direito de comer e beber?'),
('acf','1co',9,5,'Não temos nós direito de levar conosco uma esposa crente, como também os demais apóstolos, e os irmãos do Senhor, e Cefas?'),
('acf','1co',9,6,'Ou só eu e Barnabé não temos direito de deixar de trabalhar?'),
('acf','1co',9,7,'Quem jamais milita à sua própria custa? Quem planta a vinha e não come do seu fruto? Ou quem apascenta o gado e não se alimenta do leite do gado?'),
('acf','1co',9,8,'Digo eu isto segundo os homens? Ou não diz a lei também o mesmo?'),
('acf','1co',9,9,'Porque na lei de Moisés está escrito: Não atarás a boca ao boi que trilha o grão. Porventura tem Deus cuidado dos bois?'),
('acf','1co',9,10,'Ou não o diz certamente por nós? Certamente que por nós está escrito; porque o que lavra deve lavrar com esperança e o que debulha deve debulhar com esperança de ser participante.'),
('acf','1co',9,11,'Se nós vos semeamos as coisas espirituais, será muito que de vós recolhamos as carnais?'),
('acf','1co',9,12,'Se outros participam deste poder sobre vós, por que não, e mais justamente, nós? Mas nós não usamos deste direito; antes suportamos tudo, para não pormos impedimento algum ao evangelho de Cristo.'),
('acf','1co',9,13,'Não sabeis vós que os que administram o que é sagrado comem do que é do templo? E que os que de contínuo estão junto ao altar, participam do altar?'),
('acf','1co',9,14,'Assim ordenou também o Senhor aos que anunciam o evangelho, que vivam do evangelho.'),
('acf','1co',9,15,'Mas eu de nenhuma destas coisas usei, e não escrevi isto para que assim se faça comigo; porque melhor me fora morrer, do que alguém fazer vã esta minha glória.'),
('acf','1co',9,16,'Porque, se anuncio o evangelho, não tenho de que me gloriar, pois me é imposta essa obrigação; e ai de mim, se não anunciar o evangelho!'),
('acf','1co',9,17,'E por isso, se o faço de boa mente, terei prêmio; mas, se de má vontade, apenas uma dispensação me é confiada.'),
('acf','1co',9,18,'Logo, que prêmio tenho? Que, evangelizando, proponha de graça o evangelho de Cristo para não abusar do meu poder no evangelho.'),
('acf','1co',9,19,'Porque, sendo livre para com todos, fiz-me servo de todos para ganhar ainda mais.'),
('acf','1co',9,20,'E fiz-me como judeu para os judeus, para ganhar os judeus; para os que estão debaixo da lei, como se estivesse debaixo da lei, para ganhar os que estão debaixo da lei.'),
('acf','1co',9,21,'Para os que estão sem lei, como se estivesse sem lei (não estando sem lei para com Deus, mas debaixo da lei de Cristo), para ganhar os que estão sem lei.'),
('acf','1co',9,22,'Fiz-me como fraco para os fracos, para ganhar os fracos. Fiz-me tudo para todos, para por todos os meios chegar a salvar alguns.'),
('acf','1co',9,23,'E eu faço isto por causa do evangelho, para ser também participante dele.'),
('acf','1co',9,24,'Não sabeis vós que os que correm no estádio, todos, na verdade, correm, mas um só leva o prêmio? Correi de tal maneira que o alcanceis.'),
('acf','1co',9,25,'E todo aquele que luta de tudo se abstém; eles o fazem para alcançar uma coroa corruptível; nós, porém, uma incorruptível.'),
('acf','1co',9,26,'Pois eu assim corro, não como a coisa incerta; assim combato, não como batendo no ar.'),
('acf','1co',9,27,'Antes subjugo o meu corpo, e o reduzo à servidão, para que, pregando aos outros, eu mesmo não venha de alguma maneira a ficar reprovado.'),
('acf','1co',10,1,'Ora, irmãos, não quero que ignoreis que nossos pais estiveram todos debaixo da nuvem, e todos passaram pelo mar.'),
('acf','1co',10,2,'E todos foram batizados em Moisés, na nuvem e no mar,'),
('acf','1co',10,3,'E todos comeram de uma mesma comida espiritual,'),
('acf','1co',10,4,'E beberam todos de uma mesma bebida espiritual, porque bebiam da pedra espiritual que os seguia; e a pedra era Cristo.'),
('acf','1co',10,5,'Mas Deus não se agradou da maior parte deles, por isso foram prostrados no deserto.'),
('acf','1co',10,6,'E estas coisas foram-nos feitas em figura, para que não cobicemos as coisas más, como eles cobiçaram.'),
('acf','1co',10,7,'Não vos façais, pois, idólatras, como alguns deles, conforme está escrito: O povo assentou-se a comer e a beber, e levantou-se para folgar.'),
('acf','1co',10,8,'E não nos forniquemos, como alguns deles fizeram; e caíram num dia vinte e três mil.'),
('acf','1co',10,9,'E não tentemos a Cristo, como alguns deles também tentaram, e pereceram pelas serpentes.'),
('acf','1co',10,10,'E não murmureis, como também alguns deles murmuraram, e pereceram pelo destruidor.'),
('acf','1co',10,11,'Ora, tudo isto lhes sobreveio como figuras, e estão escritas para aviso nosso, para quem já são chegados os fins dos séculos.'),
('acf','1co',10,12,'Aquele, pois, que cuida estar em pé, olhe não caia.'),
('acf','1co',10,13,'Não veio sobre vós tentação, senão humana; mas fiel é Deus, que não vos deixará tentar acima do que podeis, antes com a tentação dará também o escape, para que a possais suportar.'),
('acf','1co',10,14,'Portanto, meus amados, fugi da idolatria.'),
('acf','1co',10,15,'Falo como a entendidos; julgai vós mesmos o que digo.'),
('acf','1co',10,16,'Porventura o cálice de bênção, que abençoamos, não é a comunhão do sangue de Cristo? O pão que partimos não é porventura a comunhão do corpo de Cristo?'),
('acf','1co',10,17,'Porque nós, sendo muitos, somos um só pão e um só corpo, porque todos participamos do mesmo pão.'),
('acf','1co',10,18,'Vede a Israel segundo a carne; os que comem os sacrifícios não são porventura participantes do altar?'),
('acf','1co',10,19,'Mas que digo? Que o ídolo é alguma coisa? Ou que o sacrificado ao ídolo é alguma coisa?'),
('acf','1co',10,20,'Antes digo que as coisas que os gentios sacrificam, as sacrificam aos demônios, e não a Deus. E não quero que sejais participantes com os demônios.'),
('acf','1co',10,21,'Não podeis beber o cálice do Senhor e o cálice dos demônios; não podeis ser participantes da mesa do Senhor e da mesa dos demônios.'),
('acf','1co',10,22,'Ou irritaremos o Senhor? Somos nós mais fortes do que ele?'),
('acf','1co',10,23,'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são lícitas, mas nem todas as coisas edificam.'),
('acf','1co',10,24,'Ninguém busque o proveito próprio; antes cada um o que é de outrem.'),
('acf','1co',10,25,'Comei de tudo quanto se vende no açougue, sem perguntar nada, por causa da consciência.'),
('acf','1co',10,26,'Porque a terra é do Senhor e toda a sua plenitude.'),
('acf','1co',10,27,'E, se algum dos infiéis vos convidar, e quiserdes ir, comei de tudo o que se puser diante de vós, sem nada perguntar, por causa da consciência.'),
('acf','1co',10,28,'Mas, se alguém vos disser: Isto foi sacrificado aos ídolos, não comais, por causa daquele que vos advertiu e por causa da consciência; porque a terra é do Senhor, e toda a sua plenitude.'),
('acf','1co',10,29,'Digo, porém, a consciência, não a tua, mas a do outro. Pois por que há de a minha liberdade ser julgada pela consciência de outrem?'),
('acf','1co',10,30,'E, se eu com graça participo, por que sou blasfemado naquilo por que dou graças?'),
('acf','1co',10,31,'Portanto, quer comais quer bebais, ou façais outra qualquer coisa, fazei tudo para glória de Deus.'),
('acf','1co',10,32,'Portai-vos de modo que não deis escândalo nem aos judeus, nem aos gregos, nem à igreja de Deus.'),
('acf','1co',10,33,'Como também eu em tudo agrado a todos, não buscando o meu próprio proveito, mas o de muitos, para que assim se possam salvar.'),
('acf','1co',11,1,'Sede meus imitadores, como também eu de Cristo.'),
('acf','1co',11,2,'E louvo-vos, irmãos, porque em tudo vos lembrais de mim, e retendes os preceitos como vo-los entreguei.'),
('acf','1co',11,3,'Mas quero que saibais que Cristo é a cabeça de todo o homem, e o homem a cabeça da mulher; e Deus a cabeça de Cristo.'),
('acf','1co',11,4,'Todo o homem que ora ou profetiza, tendo a cabeça coberta, desonra a sua própria cabeça.'),
('acf','1co',11,5,'Mas toda a mulher que ora ou profetiza com a cabeça descoberta, desonra a sua própria cabeça, porque é como se estivesse rapada.'),
('acf','1co',11,6,'Portanto, se a mulher não se cobre com véu, tosquie-se também. Mas, se para a mulher é coisa indecente tosquiar-se ou rapar-se, que ponha o véu.'),
('acf','1co',11,7,'O homem, pois, não deve cobrir a cabeça, porque é a imagem e glória de Deus, mas a mulher é a glória do homem.'),
('acf','1co',11,8,'Porque o homem não provém da mulher, mas a mulher do homem.'),
('acf','1co',11,9,'Porque também o homem não foi criado por causa da mulher, mas a mulher por causa do homem.'),
('acf','1co',11,10,'Portanto, a mulher deve ter sobre a cabeça sinal de poderio, por causa dos anjos.'),
('acf','1co',11,11,'Todavia, nem o homem é sem a mulher, nem a mulher sem o homem, no Senhor.'),
('acf','1co',11,12,'Porque, como a mulher provém do homem, assim também o homem provém da mulher, mas tudo vem de Deus.'),
('acf','1co',11,13,'Julgai entre vós mesmos: é decente que a mulher ore a Deus descoberta?'),
('acf','1co',11,14,'Ou não vos ensina a mesma natureza que é desonra para o homem ter cabelo crescido?'),
('acf','1co',11,15,'Mas ter a mulher cabelo crescido lhe é honroso, porque o cabelo lhe foi dado em lugar de véu.'),
('acf','1co',11,16,'Mas, se alguém quiser ser contencioso, nós não temos tal costume, nem as igrejas de Deus.'),
('acf','1co',11,17,'Nisto, porém, que vou dizer-vos não vos louvo; porquanto vos ajuntais, não para melhor, senão para pior.'),
('acf','1co',11,18,'Porque antes de tudo ouço que, quando vos ajuntais na igreja, há entre vós dissensões; e em parte o creio.'),
('acf','1co',11,19,'E até importa que haja entre vós heresias, para que os que são sinceros se manifestem entre vós.'),
('acf','1co',11,20,'De sorte que, quando vos ajuntais num lugar, não é para comer a ceia do Senhor.'),
('acf','1co',11,21,'Porque, comendo, cada um toma antecipadamente a sua própria ceia; e assim um tem fome e outro embriaga-se.'),
('acf','1co',11,22,'Não tendes porventura casas para comer e para beber? Ou desprezais a igreja de Deus, e envergonhais os que nada têm? Que vos direi? Louvar-vos-ei? Nisto não vos louvo.'),
('acf','1co',11,23,'Porque eu recebi do Senhor o que também vos ensinei: que o Senhor Jesus, na noite em que foi traído, tomou o pão;'),
('acf','1co',11,24,'E, tendo dado graças, o partiu e disse: Tomai, comei; isto é o meu corpo que é partido por vós; fazei isto em memória de mim.'),
('acf','1co',11,25,'Semelhantemente também, depois de cear, tomou o cálice, dizendo: Este cálice é o novo testamento no meu sangue; fazei isto, todas as vezes que beberdes, em memória de mim.'),
('acf','1co',11,26,'Porque todas as vezes que comerdes este pão e beberdes este cálice anunciais a morte do Senhor, até que venha.'),
('acf','1co',11,27,'Portanto, qualquer que comer este pão, ou beber o cálice do Senhor indignamente, será culpado do corpo e do sangue do Senhor.'),
('acf','1co',11,28,'Examine-se, pois, o homem a si mesmo, e assim coma deste pão e beba deste cálice.'),
('acf','1co',11,29,'Porque o que come e bebe indignamente, come e bebe para sua própria condenação, não discernindo o corpo do Senhor.'),
('acf','1co',11,30,'Por causa disto há entre vós muitos fracos e doentes, e muitos que dormem.'),
('acf','1co',11,31,'Porque, se nós nos julgássemos a nós mesmos, não seríamos julgados.'),
('acf','1co',11,32,'Mas, quando somos julgados, somos repreendidos pelo Senhor, para não sermos condenados com o mundo.'),
('acf','1co',11,33,'Portanto, meus irmãos, quando vos ajuntais para comer, esperai uns pelos outros.'),
('acf','1co',11,34,'Mas, se algum tiver fome, coma em casa, para que não vos ajunteis para condenação. Quanto às demais coisas, ordená-las-ei quando for.'),
('acf','1co',12,1,'Acerca dos dons espirituais, não quero, irmãos, que sejais ignorantes.'),
('acf','1co',12,2,'Vós bem sabeis que éreis gentios, levados aos ídolos mudos, conforme éreis guiados.'),
('acf','1co',12,3,'Portanto, vos quero fazer compreender que ninguém que fala pelo Espírito de Deus diz: Jesus é anátema, e ninguém pode dizer que Jesus é o Senhor, senão pelo Espírito Santo.'),
('acf','1co',12,4,'Ora, há diversidade de dons, mas o Espírito é o mesmo.'),
('acf','1co',12,5,'E há diversidade de ministérios, mas o Senhor é o mesmo.'),
('acf','1co',12,6,'E há diversidade de operações, mas é o mesmo Deus que opera tudo em todos.'),
('acf','1co',12,7,'Mas a manifestação do Espírito é dada a cada um, para o que for útil.'),
('acf','1co',12,8,'Porque a um pelo Espírito é dada a palavra da sabedoria; e a outro, pelo mesmo Espírito, a palavra da ciência;'),
('acf','1co',12,9,'E a outro, pelo mesmo Espírito, a fé; e a outro, pelo mesmo Espírito, os dons de curar;'),
('acf','1co',12,10,'E a outro a operação de maravilhas; e a outro a profecia; e a outro o dom de discernir os espíritos; e a outro a variedade de línguas; e a outro a interpretação das línguas.'),
('acf','1co',12,11,'Mas um só e o mesmo Espírito opera todas estas coisas, repartindo particularmente a cada um como quer.'),
('acf','1co',12,12,'Porque, assim como o corpo é um, e tem muitos membros, e todos os membros, sendo muitos, são um só corpo, assim é Cristo também.'),
('acf','1co',12,13,'Pois todos nós fomos batizados em um Espírito, formando um corpo, quer judeus, quer gregos, quer servos, quer livres, e todos temos bebido de um Espírito.'),
('acf','1co',12,14,'Porque também o corpo não é um só membro, mas muitos.'),
('acf','1co',12,15,'Se o pé disser: Porque não sou mão, não sou do corpo; não será por isso do corpo?'),
('acf','1co',12,16,'E se a orelha disser: Porque não sou olho não sou do corpo; não será por isso do corpo?'),
('acf','1co',12,17,'Se todo o corpo fosse olho, onde estaria o ouvido? Se todo fosse ouvido, onde estaria o olfato?'),
('acf','1co',12,18,'Mas agora Deus colocou os membros no corpo, cada um deles como quis.'),
('acf','1co',12,19,'E, se todos fossem um só membro, onde estaria o corpo?'),
('acf','1co',12,20,'Assim, pois, há muitos membros, mas um corpo.'),
('acf','1co',12,21,'E o olho não pode dizer à mão: Não tenho necessidade de ti; nem ainda a cabeça aos pés: Não tenho necessidade de vós.'),
('acf','1co',12,22,'Antes, os membros do corpo que parecem ser os mais fracos são necessários;'),
('acf','1co',12,23,'E os que reputamos serem menos honrosos no corpo, a esses honramos muito mais; e aos que em nós são menos decorosos damos muito mais honra.'),
('acf','1co',12,24,'Porque os que em nós são mais nobres não têm necessidade disso, mas Deus assim formou o corpo, dando muito mais honra ao que tinha falta dela;'),
('acf','1co',12,25,'Para que não haja divisão no corpo, mas antes tenham os membros igual cuidado uns dos outros.'),
('acf','1co',12,26,'De maneira que, se um membro padece, todos os membros padecem com ele; e, se um membro é honrado, todos os membros se regozijam com ele.'),
('acf','1co',12,27,'Ora, vós sois o corpo de Cristo, e seus membros em particular.'),
('acf','1co',12,28,'E a uns pôs Deus na igreja, primeiramente apóstolos, em segundo lugar profetas, em terceiro doutores, depois milagres, depois dons de curar, socorros, governos, variedades de línguas.'),
('acf','1co',12,29,'Porventura são todos apóstolos? são todos profetas? são todos doutores? são todos operadores de milagres?'),
('acf','1co',12,30,'Têm todos o dom de curar? falam todos diversas línguas? interpretam todos?'),
('acf','1co',12,31,'Portanto, procurai com zelo os melhores dons; e eu vos mostrarei um caminho mais excelente.'),
('acf','1co',13,1,'Ainda que eu falasse as línguas dos homens e dos anjos, e não tivesse amor, seria como o metal que soa ou como o sino que tine.'),
('acf','1co',13,2,'E ainda que tivesse o dom de profecia, e conhecesse todos os mistérios e toda a ciência, e ainda que tivesse toda a fé, de maneira tal que transportasse os montes, e não tivesse amor, nada seria.'),
('acf','1co',13,3,'E ainda que distribuísse toda a minha fortuna para sustento dos pobres, e ainda que entregasse o meu corpo para ser queimado, e não tivesse amor, nada disso me aproveitaria.'),
('acf','1co',13,4,'O amor é sofredor, é benigno; o amor não é invejoso; o amor não trata com leviandade, não se ensoberbece.'),
('acf','1co',13,5,'Não se porta com indecência, não busca os seus interesses, não se irrita, não suspeita mal;'),
('acf','1co',13,6,'Não folga com a injustiça, mas folga com a verdade;'),
('acf','1co',13,7,'Tudo sofre, tudo crê, tudo espera, tudo suporta.'),
('acf','1co',13,8,'O amor nunca falha; mas havendo profecias, serão aniquiladas; havendo línguas, cessarão; havendo ciência, desaparecerá;'),
('acf','1co',13,9,'Porque, em parte, conhecemos, e em parte profetizamos;'),
('acf','1co',13,10,'Mas, quando vier o que é perfeito, então o que o é em parte será aniquilado.'),
('acf','1co',13,11,'Quando eu era menino, falava como menino, sentia como menino, discorria como menino, mas, logo que cheguei a ser homem, acabei com as coisas de menino.'),
('acf','1co',13,12,'Porque agora vemos por espelho em enigma, mas então veremos face a face; agora conheço em parte, mas então conhecerei como também sou conhecido.'),
('acf','1co',13,13,'Agora, pois, permanecem a fé, a esperança e o amor, estes três, mas o maior destes é o amor.'),
('acf','1co',14,1,'Segui o amor, e procurai com zelo os dons espirituais, mas principalmente o de profetizar.'),
('acf','1co',14,2,'Porque o que fala em língua desconhecida não fala aos homens, senão a Deus; porque ninguém o entende, e em espírito fala mistérios.'),
('acf','1co',14,3,'Mas o que profetiza fala aos homens, para edificação, exortação e consolação.'),
('acf','1co',14,4,'O que fala em língua desconhecida edifica-se a si mesmo, mas o que profetiza edifica a igreja.'),
('acf','1co',14,5,'E eu quero que todos vós faleis em línguas, mas muito mais que profetizeis; porque o que profetiza é maior do que o que fala em línguas, a não ser que também interprete para que a igreja receba edificação.'),
('acf','1co',14,6,'E agora, irmãos, se eu for ter convosco falando em línguas, que vos aproveitaria, se não vos falasse ou por meio da revelação, ou da ciência, ou da profecia, ou da doutrina?'),
('acf','1co',14,7,'Da mesma sorte, se as coisas inanimadas, que fazem som, seja flauta, seja cítara, não formarem sons distintos, como se conhecerá o que se toca com a flauta ou com a cítara?'),
('acf','1co',14,8,'Porque, se a trombeta der sonido incerto, quem se preparará para a batalha?'),
('acf','1co',14,9,'Assim também vós, se com a língua não pronunciardes palavras bem inteligíveis, como se entenderá o que se diz? porque estareis como que falando ao ar.'),
('acf','1co',14,10,'Há, por exemplo, tanta espécie de vozes no mundo, e nenhuma delas é sem significação.'),
('acf','1co',14,11,'Mas, se eu ignorar o sentido da voz, serei bárbaro para aquele a quem falo, e o que fala será bárbaro para mim.'),
('acf','1co',14,12,'Assim também vós, como desejais dons espirituais, procurai abundar neles, para edificação da igreja.'),
('acf','1co',14,13,'Por isso, o que fala em língua desconhecida, ore para que a possa interpretar.'),
('acf','1co',14,14,'Porque, se eu orar em língua desconhecida, o meu espírito ora bem, mas o meu entendimento fica sem fruto.'),
('acf','1co',14,15,'Que farei, pois? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.'),
('acf','1co',14,16,'De outra maneira, se tu bendisseres com o espírito, como dirá o que ocupa o lugar de indouto, o Amém, sobre a tua ação de graças, visto que não sabe o que dizes?'),
('acf','1co',14,17,'Porque realmente tu dás bem as graças, mas o outro não é edificado.'),
('acf','1co',14,18,'Dou graças ao meu Deus, porque falo mais línguas do que vós todos.'),
('acf','1co',14,19,'Todavia eu antes quero falar na igreja cinco palavras na minha própria inteligência, para que possa também instruir os outros, do que dez mil palavras em língua desconhecida.'),
('acf','1co',14,20,'Irmãos, não sejais meninos no entendimento, mas sede meninos na malícia, e adultos no entendimento.'),
('acf','1co',14,21,'Está escrito na lei: Por gente de outras línguas, e por outros lábios, falarei a este povo; e ainda assim me não ouvirão, diz o Senhor.'),
('acf','1co',14,22,'De sorte que as línguas são um sinal, não para os fiéis, mas para os infiéis; e a profecia não é sinal para os infiéis, mas para os fiéis.'),
('acf','1co',14,23,'Se, pois, toda a igreja se congregar num lugar, e todos falarem em línguas, e entrarem indoutos ou infiéis, não dirão porventura que estais loucos?'),
('acf','1co',14,24,'Mas, se todos profetizarem, e algum indouto ou infiel entrar, de todos é convencido, de todos é julgado.'),
('acf','1co',14,25,'E, portanto, os segredos do seu coração ficam manifestos, e assim, lançando-se sobre o seu rosto, adorará a Deus, publicando que Deus está verdadeiramente entre vós.'),
('acf','1co',14,26,'Que fareis pois, irmãos? Quando vos ajuntais, cada um de vós tem salmo, tem doutrina, tem revelação, tem língua, tem interpretação. Faça-se tudo para edificação.'),
('acf','1co',14,27,'E, se alguém falar em língua desconhecida, faça-se isso por dois, ou quando muito três, e por sua vez, e haja intérprete.'),
('acf','1co',14,28,'Mas, se não houver intérprete, esteja calado na igreja, e fale consigo mesmo, e com Deus.'),
('acf','1co',14,29,'E falem dois ou três profetas, e os outros julguem.'),
('acf','1co',14,30,'Mas, se a outro, que estiver assentado, for revelada alguma coisa, cale-se o primeiro.'),
('acf','1co',14,31,'Porque todos podereis profetizar, uns depois dos outros; para que todos aprendam, e todos sejam consolados.'),
('acf','1co',14,32,'E os espíritos dos profetas estão sujeitos aos profetas.'),
('acf','1co',14,33,'Porque Deus não é Deus de confusão, senão de paz, como em todas as igrejas dos santos.'),
('acf','1co',14,34,'As vossas mulheres estejam caladas nas igrejas; porque não lhes é permitido falar; mas estejam sujeitas, como também ordena a lei.'),
('acf','1co',14,35,'E, se querem aprender alguma coisa, interroguem em casa a seus próprios maridos; porque é vergonhoso que as mulheres falem na igreja.'),
('acf','1co',14,36,'Porventura saiu dentre vós a palavra de Deus? Ou veio ela somente para vós?'),
('acf','1co',14,37,'Se alguém cuida ser profeta, ou espiritual, reconheça que as coisas que vos escrevo são mandamentos do Senhor.'),
('acf','1co',14,38,'Mas, se alguém ignora isto, que ignore.'),
('acf','1co',14,39,'Portanto, irmãos, procurai, com zelo, profetizar, e não proibais falar línguas.'),
('acf','1co',14,40,'Mas faça-se tudo decentemente e com ordem.'),
('acf','1co',15,1,'Também vos notifico, irmãos, o evangelho que já vos tenho anunciado; o qual também recebestes, e no qual também permaneceis.'),
('acf','1co',15,2,'Pelo qual também sois salvos se o retiverdes tal como vo-lo tenho anunciado; se não é que crestes em vão.'),
('acf','1co',15,3,'Porque primeiramente vos entreguei o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras,'),
('acf','1co',15,4,'E que foi sepultado, e que ressuscitou ao terceiro dia, segundo as Escrituras.'),
('acf','1co',15,5,'E que foi visto por Cefas, e depois pelos doze.'),
('acf','1co',15,6,'Depois foi visto, uma vez, por mais de quinhentos irmãos, dos quais vive ainda a maior parte, mas alguns já dormem também.'),
('acf','1co',15,7,'Depois foi visto por Tiago, depois por todos os apóstolos.'),
('acf','1co',15,8,'E por derradeiro de todos me apareceu também a mim, como a um abortivo.'),
('acf','1co',15,9,'Porque eu sou o menor dos apóstolos, que não sou digno de ser chamado apóstolo, pois que persegui a igreja de Deus.'),
('acf','1co',15,10,'Mas pela graça de Deus sou o que sou; e a sua graça para comigo não foi vã, antes trabalhei muito mais do que todos eles; todavia não eu, mas a graça de Deus, que está comigo.'),
('acf','1co',15,11,'Então, ou seja eu ou sejam eles, assim pregamos e assim haveis crido.'),
('acf','1co',15,12,'Ora, se se prega que Cristo ressuscitou dentre os mortos, como dizem alguns dentre vós que não há ressurreição de mortos?'),
('acf','1co',15,13,'E, se não há ressurreição de mortos, também Cristo não ressuscitou.'),
('acf','1co',15,14,'E, se Cristo não ressuscitou, logo é vã a nossa pregação, e também é vã a vossa fé.'),
('acf','1co',15,15,'E assim somos também considerados como falsas testemunhas de Deus, pois testificamos de Deus, que ressuscitou a Cristo, ao qual, porém, não ressuscitou, se, na verdade, os mortos não ressuscitam.'),
('acf','1co',15,16,'Porque, se os mortos não ressuscitam, também Cristo não ressuscitou.'),
('acf','1co',15,17,'E, se Cristo não ressuscitou, é vã a vossa fé, e ainda permaneceis nos vossos pecados.'),
('acf','1co',15,18,'E também os que dormiram em Cristo estão perdidos.'),
('acf','1co',15,19,'Se esperamos em Cristo só nesta vida, somos os mais miseráveis de todos os homens.'),
('acf','1co',15,20,'Mas de fato Cristo ressuscitou dentre os mortos, e foi feito as primícias dos que dormem.'),
('acf','1co',15,21,'Porque assim como a morte veio por um homem, também a ressurreição dos mortos veio por um homem.'),
('acf','1co',15,22,'Porque, assim como todos morrem em Adão, assim também todos serão vivificados em Cristo.'),
('acf','1co',15,23,'Mas cada um por sua ordem: Cristo as primícias, depois os que são de Cristo, na sua vinda.'),
('acf','1co',15,24,'Depois virá o fim, quando tiver entregado o reino a Deus, ao Pai, e quando houver aniquilado todo o império, e toda a potestade e força.'),
('acf','1co',15,25,'Porque convém que reine até que haja posto a todos os inimigos debaixo de seus pés.'),
('acf','1co',15,26,'Ora, o último inimigo que há de ser aniquilado é a morte.'),
('acf','1co',15,27,'Porque todas as coisas sujeitou debaixo de seus pés. Mas, quando diz que todas as coisas lhe estão sujeitas, claro está que se excetua aquele que lhe sujeitou todas as coisas.'),
('acf','1co',15,28,'E, quando todas as coisas lhe estiverem sujeitas, então também o mesmo Filho se sujeitará àquele que todas as coisas lhe sujeitou, para que Deus seja tudo em todos.'),
('acf','1co',15,29,'Doutra maneira, que farão os que se batizam pelos mortos, se absolutamente os mortos não ressuscitam? Por que se batizam eles então pelos mortos?'),
('acf','1co',15,30,'Por que estamos nós também a toda a hora em perigo?'),
('acf','1co',15,31,'Eu protesto que cada dia morro, gloriando-me em vós, irmãos, por Cristo Jesus nosso Senhor.'),
('acf','1co',15,32,'Se, como homem, combati em Éfeso contra as bestas, que me aproveita isso, se os mortos não ressuscitam? Comamos e bebamos, que amanhã morreremos.'),
('acf','1co',15,33,'Não vos enganeis: as más conversações corrompem os bons costumes.'),
('acf','1co',15,34,'Vigiai justamente e não pequeis; porque alguns ainda não têm o conhecimento de Deus; digo-o para vergonha vossa.'),
('acf','1co',15,35,'Mas alguém dirá: Como ressuscitarão os mortos? E com que corpo virão?'),
('acf','1co',15,36,'Insensato! o que tu semeias não é vivificado, se primeiro não morrer.'),
('acf','1co',15,37,'E, quando semeias, não semeias o corpo que há de nascer, mas o simples grão, como de trigo, ou de outra qualquer semente.'),
('acf','1co',15,38,'Mas Deus dá-lhe o corpo como quer, e a cada semente o seu próprio corpo.'),
('acf','1co',15,39,'Nem toda a carne é uma mesma carne, mas uma é a carne dos homens, e outra a carne dos animais, e outra a dos peixes e outra a das aves.'),
('acf','1co',15,40,'E há corpos celestes e corpos terrestres, mas uma é a glória dos celestes e outra a dos terrestres.'),
('acf','1co',15,41,'Uma é a glória do sol, e outra a glória da lua, e outra a glória das estrelas; porque uma estrela difere em glória de outra estrela.'),
('acf','1co',15,42,'Assim também a ressurreição dentre os mortos. Semeia-se o corpo em corrupção; ressuscitará em incorrupção.'),
('acf','1co',15,43,'Semeia-se em ignomínia, ressuscitará em glória. Semeia-se em fraqueza, ressuscitará com vigor.'),
('acf','1co',15,44,'Semeia-se corpo natural, ressuscitará corpo espiritual. Se há corpo natural, há também corpo espiritual.'),
('acf','1co',15,45,'Assim está também escrito: O primeiro homem, Adão, foi feito em alma vivente; o último Adão em espírito vivificante.'),
('acf','1co',15,46,'Mas não é primeiro o espiritual, senão o natural; depois o espiritual.'),
('acf','1co',15,47,'O primeiro homem, da terra, é terreno; o segundo homem, o Senhor, é do céu.'),
('acf','1co',15,48,'Qual o terreno, tais são também os terrestres; e, qual o celestial, tais também os celestiais.'),
('acf','1co',15,49,'E, assim como trouxemos a imagem do terreno, assim traremos também a imagem do celestial.'),
('acf','1co',15,50,'E agora digo isto, irmãos: que a carne e o sangue não podem herdar o reino de Deus, nem a corrupção herdar a incorrupção.'),
('acf','1co',15,51,'Eis aqui vos digo um mistério: Na verdade, nem todos dormiremos, mas todos seremos transformados;'),
('acf','1co',15,52,'Num momento, num abrir e fechar de olhos, ante a última trombeta; porque a trombeta soará, e os mortos ressuscitarão incorruptíveis, e nós seremos transformados.'),
('acf','1co',15,53,'Porque convém que isto que é corruptível se revista da incorruptibilidade, e que isto que é mortal se revista da imortalidade.'),
('acf','1co',15,54,'E, quando isto que é corruptível se revestir da incorruptibilidade, e isto que é mortal se revestir da imortalidade, então cumprir-se-á a palavra que está escrita: Tragada foi a morte na vitória.'),
('acf','1co',15,55,'Onde está, ó morte, o teu aguilhão? Onde está, ó inferno, a tua vitória?'),
('acf','1co',15,56,'Ora, o aguilhão da morte é o pecado, e a força do pecado é a lei.'),
('acf','1co',15,57,'Mas graças a Deus que nos dá a vitória por nosso Senhor Jesus Cristo.'),
('acf','1co',15,58,'Portanto, meus amados irmãos, sede firmes e constantes, sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.'),
('acf','1co',16,1,'Ora, quanto à coleta que se faz para os santos, fazei vós também o mesmo que ordenei às igrejas da Galácia.'),
('acf','1co',16,2,'No primeiro dia da semana cada um de vós ponha de parte o que puder ajuntar, conforme a sua prosperidade, para que não se façam as coletas quando eu chegar.'),
('acf','1co',16,3,'E, quando tiver chegado, mandarei os que por cartas aprovardes, para levar a vossa dádiva a Jerusalém.'),
('acf','1co',16,4,'E, se valer a pena que eu também vá, irão comigo.'),
('acf','1co',16,5,'Irei, porém, ter convosco depois de ter passado pela macedônia (porque tenho de passar pela macedônia).'),
('acf','1co',16,6,'E bem pode ser que fique convosco, e passe também o inverno, para que me acompanheis aonde quer que eu for.'),
('acf','1co',16,7,'Porque não vos quero agora ver de passagem, mas espero ficar convosco algum tempo, se o Senhor o permitir.'),
('acf','1co',16,8,'Ficarei, porém, em Éfeso até ao Pentecostes;'),
('acf','1co',16,9,'Porque uma porta grande e eficaz se me abriu; e há muitos adversários.'),
('acf','1co',16,10,'E, se Timóteo for, vede que esteja sem temor convosco; porque trabalha na obra do Senhor, como eu também.'),
('acf','1co',16,11,'Portanto, ninguém o despreze, mas acompanhai-o em paz, para que venha ter comigo; pois o espero com os irmãos.'),
('acf','1co',16,12,'E, acerca do irmão Apolo, roguei-lhe muito que fosse com os irmãos ter convosco, mas, na verdade, não teve vontade de ir agora; irá, porém, quando se lhe oferecer boa ocasião.'),
('acf','1co',16,13,'Vigiai, estai firmes na fé; portai-vos varonilmente, e fortalecei-vos.'),
('acf','1co',16,14,'Todas as vossas coisas sejam feitas com amor.'),
('acf','1co',16,15,'Agora vos rogo, irmãos (sabeis que a família de Estéfanas é as primícias da Acaia, e que se tem dedicado ao ministério dos santos),'),
('acf','1co',16,16,'Que também vos sujeiteis aos tais, e a todo aquele que auxilia na obra e trabalha.'),
('acf','1co',16,17,'Folgo, porém, com a vinda de Estéfanas, de Fortunato e de Acaico; porque estes supriram o que da vossa parte me faltava.'),
('acf','1co',16,18,'Porque recrearam o meu espírito e o vosso. Reconhecei, pois, aos tais.'),
('acf','1co',16,19,'As igrejas da Ásia vos saúdam. Saúdam-vos afetuosamente no Senhor áqüila e Priscila, com a igreja que está em sua casa.'),
('acf','1co',16,20,'Todos os irmãos vos saúdam. Saudai-vos uns aos outros com ósculo santo.'),
('acf','1co',16,21,'Saudação da minha própria mão, de Paulo.'),
('acf','1co',16,22,'Se alguém não ama ao Senhor Jesus Cristo, seja anátema. Maranata!'),
('acf','1co',16,23,'A graça do Senhor Jesus Cristo seja convosco.'),
('acf','1co',16,24,'O meu amor seja com todos vós em Cristo Jesus. Amém.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2co',1,1,'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, e o irmão Timóteo, à igreja de Deus, que está em Corinto, com todos os santos que estão em toda a Acaia.'),
('acf','2co',1,2,'Graça a vós e paz da parte de Deus nosso Pai, e da do Senhor Jesus Cristo.'),
('acf','2co',1,3,'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias e o Deus de toda a consolação;'),
('acf','2co',1,4,'Que nos consola em toda a nossa tribulação, para que também possamos consolar os que estiverem em alguma tribulação, com a consolação com que nós mesmos somos consolados por Deus.'),
('acf','2co',1,5,'Porque, como as aflições de Cristo são abundantes em nós, assim também é abundante a nossa consolação por meio de Cristo.'),
('acf','2co',1,6,'Mas, se somos atribulados, é para vossa consolação e salvação; ou, se somos consolados, para vossa consolação é, a qual se opera suportando com paciência as mesmas aflições que nós também padecemos;'),
('acf','2co',1,7,'E a nossa esperança acerca de vós é firme, sabendo que, como sois participantes das aflições, assim o sereis também da consolação.'),
('acf','2co',1,8,'Porque não queremos, irmãos, que ignoreis a tribulação que nos sobreveio na Ásia, pois que fomos sobremaneira agravados mais do que podíamos suportar, de modo tal que até da vida desesperamos.'),
('acf','2co',1,9,'Mas já em nós mesmos tínha- mos a sentença de morte, para que não confiássemos em nós, mas em Deus, que ressuscita os mortos;'),
('acf','2co',1,10,'O qual nos livrou de tão grande morte, e livra; em quem esperamos que também nos livrará ainda,'),
('acf','2co',1,11,'Ajudando-nos também vós com orações por nós, para que pela mercê, que por muitas pessoas nos foi feita, por muitas também sejam dadas graças a nosso respeito.'),
('acf','2co',1,12,'Porque a nossa glória é esta: o testemunho da nossa consciência, de que com simplicidade e sinceridade de Deus, não com sabedoria carnal, mas na graça de Deus, temos vivido no mundo, e de modo particular convosco.'),
('acf','2co',1,13,'Porque nenhumas outras coisas vos escrevemos, senão as que já sabeis ou também reconheceis; e espero que também até ao fim as reconhecereis.'),
('acf','2co',1,14,'Como também já em parte reconhecestes em nós, que somos a vossa glória, como também vós sereis a nossa no dia do Senhor Jesus.'),
('acf','2co',1,15,'E com esta confiança quis primeiro ir ter convosco, para que tivésseis uma segunda graça;'),
('acf','2co',1,16,'E por vós passar à macedônia, e da macedônia ir outra vez ter convosco, e ser guiado por vós à Judéia.'),
('acf','2co',1,17,'E, deliberando isto, usei porventura de leviandade? Ou o que delibero, o delibero segundo a carne, para que haja em mim sim, sim, e não, não?'),
('acf','2co',1,18,'Antes, como Deus é fiel, a nossa palavra para convosco não foi sim e não.'),
('acf','2co',1,19,'Porque o Filho de Deus, Jesus Cristo, que entre vós foi pregado por nós, isto é, por mim, Silvano e Timóteo, não foi sim e não; mas nele houve sim.'),
('acf','2co',1,20,'Porque todas quantas promessas há de Deus, são nele sim, e por ele o Amém, para glória de Deus por nós.'),
('acf','2co',1,21,'Mas o que nos confirma convosco em Cristo, e o que nos ungiu, é Deus,'),
('acf','2co',1,22,'O qual também nos selou e deu o penhor do Espírito em nossos corações.'),
('acf','2co',1,23,'Invoco, porém, a Deus por testemunha sobre a minha alma, que para vos poupar não tenho até agora ido a Corinto;'),
('acf','2co',1,24,'Não que tenhamos domínio sobre a vossa fé, mas porque somos cooperadores de vosso gozo; porque pela fé estais em pé.'),
('acf','2co',2,1,'Mas deliberei isto comigo mesmo: não ir mais ter convosco em tristeza.'),
('acf','2co',2,2,'Porque, se eu vos entristeço, quem é que me alegrará, senão aquele que por mim foi contristado?'),
('acf','2co',2,3,'E escrevi-vos isto mesmo, para que, quando lá for, não tenha tristeza da parte dos que deveriam alegrar-me; confiando em vós todos, que a minha alegria é a de todos vós.'),
('acf','2co',2,4,'Porque em muita tribulação e angústia do coração vos escrevi, com muitas lágrimas, não para que vos entristecêsseis, mas para que conhecêsseis o amor que abundantemente vos tenho.'),
('acf','2co',2,5,'Porque, se alguém me contristou, não me contristou a mim senão em parte, para vos não sobrecarregar a vós todos.'),
('acf','2co',2,6,'Basta-lhe ao tal esta repreensão feita por muitos.'),
('acf','2co',2,7,'De maneira que pelo contrário deveis antes perdoar-lhe e consolá-lo, para que o tal não seja de modo algum devorado de demasiada tristeza.'),
('acf','2co',2,8,'Por isso vos rogo que confirmeis para com ele o vosso amor.'),
('acf','2co',2,9,'E para isso vos escrevi também, para por esta prova saber se sois obedientes em tudo.'),
('acf','2co',2,10,'E a quem perdoardes alguma coisa, também eu; porque, o que eu também perdoei, se é que tenho perdoado, por amor de vós o fiz na presença de Cristo; para que não sejamos vencidos por Satanás;'),
('acf','2co',2,11,'Porque não ignoramos os seus ardís.'),
('acf','2co',2,12,'Ora, quando cheguei a Trôade para pregar o evangelho de Cristo, e abrindo-se-me uma porta no Senhor,'),
('acf','2co',2,13,'Não tive descanso no meu espírito, porque não achei ali meu irmão Tito; mas, despedindo-me deles, parti para a macedônia.'),
('acf','2co',2,14,'E graças a Deus, que sempre nos faz triunfar em Cristo, e por meio de nós manifesta em todo o lugar a fragrância do seu conhecimento.'),
('acf','2co',2,15,'Porque para Deus somos o bom perfume de Cristo, nos que se salvam e nos que se perdem.'),
('acf','2co',2,16,'Para estes certamente cheiro de morte para morte; mas para aqueles cheiro de vida para vida. E para estas coisas quem é idôneo?'),
('acf','2co',2,17,'Porque nós não somos, como muitos, falsificadores da palavra de Deus, antes falamos de Cristo com sinceridade, como de Deus na presença de Deus.'),
('acf','2co',3,1,'Porventura começamos outra vez a louvar-nos a nós mesmos? Ou necessitamos, como alguns, de cartas de recomendação para vós, ou de recomendação de vós?'),
('acf','2co',3,2,'Vós sois a nossa carta, escrita em nossos corações, conhecida e lida por todos os homens.'),
('acf','2co',3,3,'Porque já é manifesto que vós sois a carta de Cristo, ministrada por nós, e escrita, não com tinta, mas com o Espírito do Deus vivo, não em tábuas de pedra, mas nas tábuas de carne do coração.'),
('acf','2co',3,4,'E é por Cristo que temos tal confiança em Deus;'),
('acf','2co',3,5,'Não que sejamos capazes, por nós, de pensar alguma coisa, como de nós mesmos; mas a nossa capacidade vem de Deus,'),
('acf','2co',3,6,'O qual nos fez também capazes de ser ministros de um novo testamento, não da letra, mas do espírito; porque a letra mata e o espírito vivifica.'),
('acf','2co',3,7,'E, se o ministério da morte, gravado com letras em pedras, veio em glória, de maneira que os filhos de Israel não podiam fitar os olhos na face de Moisés, por causa da glória do seu rosto, a qual era transitória,'),
('acf','2co',3,8,'Como não será de maior glória o ministério do Espírito?'),
('acf','2co',3,9,'Porque, se o ministério da condenação foi glorioso, muito mais excederá em glória o ministério da justiça.'),
('acf','2co',3,10,'Porque também o que foi glorificado nesta parte não foi glorificado, por causa desta excelente glória.'),
('acf','2co',3,11,'Porque, se o que era transitório foi para glória, muito mais é em glória o que permanece.'),
('acf','2co',3,12,'Tendo, pois, tal esperança, usamos de muita ousadia no falar.'),
('acf','2co',3,13,'E não somos como Moisés, que punha um véu sobre a sua face, para que os filhos de Israel não olhassem firmemente para o fim daquilo que era transitório.'),
('acf','2co',3,14,'Mas os seus sentidos foram endurecidos; porque até hoje o mesmo véu está por levantar na lição do velho testamento, o qual foi por Cristo abolido;'),
('acf','2co',3,15,'E até hoje, quando é lido Moisés, o véu está posto sobre o coração deles.'),
('acf','2co',3,16,'Mas, quando se converterem ao Senhor, então o véu se tirará.'),
('acf','2co',3,17,'Ora, o Senhor é o Espírito; e onde está o Espírito do Senhor, aí há liberdade.'),
('acf','2co',3,18,'Mas todos nós, com rosto descoberto, refletindo como um espelho a glória do Senhor, somos transformados de glória em glória na mesma imagem, como pelo Espírito do Senhor.'),
('acf','2co',4,1,'Por isso, tendo este ministério, segundo a misericórdia que nos foi feita, não desfalecemos;'),
('acf','2co',4,2,'Antes, rejeitamos as coisas que por vergonha se ocultam, não andando com astúcia nem falsificando a palavra de Deus; e assim nos recomendamos à consciência de todo o homem, na presença de Deus, pela manifestação da verdade.'),
('acf','2co',4,3,'Mas, se ainda o nosso evangelho está encoberto, para os que se perdem está encoberto.'),
('acf','2co',4,4,'Nos quais o deus deste século cegou os entendimentos dos incrédulos, para que lhes não resplandeça a luz do evangelho da glória de Cristo, que é a imagem de Deus.'),
('acf','2co',4,5,'Porque não nos pregamos a nós mesmos, mas a Cristo Jesus, o Senhor; e nós mesmos somos vossos servos por amor de Jesus.'),
('acf','2co',4,6,'Porque Deus, que disse que das trevas resplandecesse a luz, é quem resplandeceu em nossos corações, para iluminação do conhecimento da glória de Deus, na face de Jesus Cristo.'),
('acf','2co',4,7,'Temos, porém, este tesouro em vasos de barro, para que a excelência do poder seja de Deus, e não de nós.'),
('acf','2co',4,8,'Em tudo somos atribulados, mas não angustiados; perplexos, mas não desanimados.'),
('acf','2co',4,9,'Perseguidos, mas não desamparados; abatidos, mas não destruídos;'),
('acf','2co',4,10,'Trazendo sempre por toda a parte a mortificação do Senhor Jesus no nosso corpo, para que a vida de Jesus se manifeste também nos nossos corpos;'),
('acf','2co',4,11,'E assim nós, que vivemos, estamos sempre entregues à morte por amor de Jesus, para que a vida de Jesus se manifeste também na nossa carne mortal.'),
('acf','2co',4,12,'De maneira que em nós opera a morte, mas em vós a vida.'),
('acf','2co',4,13,'E temos portanto o mesmo espírito de fé, como está escrito: Cri, por isso falei; nós cremos também, por isso também falamos.'),
('acf','2co',4,14,'Sabendo que o que ressuscitou o Senhor Jesus nos ressuscitará também por Jesus, e nos apresentará convosco.'),
('acf','2co',4,15,'Porque tudo isto é por amor de vós, para que a graça, multiplicada por meio de muitos, faça abundar a ação de graças para glória de Deus.'),
('acf','2co',4,16,'Por isso não desfalecemos; mas, ainda que o nosso homem exterior se corrompa, o interior, contudo, se renova de dia em dia.'),
('acf','2co',4,17,'Porque a nossa leve e momentânea tribulação produz para nós um peso eterno de glória mui excelente;'),
('acf','2co',4,18,'Não atentando nós nas coisas que se vêem, mas nas que se não vêem; porque as que se vêem são temporais, e as que se não vêem são eternas.'),
('acf','2co',5,1,'Porque sabemos que, se a nossa casa terrestre deste tabernáculo se desfizer, temos de Deus um edifício, uma casa não feita por mãos, eterna, nos céus.'),
('acf','2co',5,2,'E por isso também gememos, desejando ser revestidos da nossa habitação, que é do céu;'),
('acf','2co',5,3,'Se, todavia, estando vestidos, não formos achados nus.'),
('acf','2co',5,4,'Porque também nós, os que estamos neste tabernáculo, gememos carregados; não porque queremos ser despidos, mas revestidos, para que o mortal seja absorvido pela vida.'),
('acf','2co',5,5,'Ora, quem para isto mesmo nos preparou foi Deus, o qual nos deu também o penhor do Espírito.'),
('acf','2co',5,6,'Por isso estamos sempre de bom ânimo, sabendo que, enquanto estamos no corpo, vivemos ausentes do Senhor'),
('acf','2co',5,7,'(Porque andamos por fé, e não por vista).'),
('acf','2co',5,8,'Mas temos confiança e desejamos antes deixar este corpo, para habitar com o Senhor.'),
('acf','2co',5,9,'Pois que muito desejamos também ser-lhe agradáveis, quer presentes, quer ausentes.'),
('acf','2co',5,10,'Porque todos devemos comparecer ante o tribunal de Cristo, para que cada um receba segundo o que tiver feito por meio do corpo, ou bem, ou mal.'),
('acf','2co',5,11,'Assim que, sabendo o temor que se deve ao Senhor, persuadimos os homens à fé, mas somos manifestos a Deus; e espero que nas vossas consciências sejamos também manifestos.'),
('acf','2co',5,12,'Porque não nos recomendamos outra vez a vós; mas damo-vos ocasião de vos gloriardes de nós, para que tenhais que responder aos que se gloriam na aparência e não no coração.'),
('acf','2co',5,13,'Porque, se enlouquecemos, é para Deus; e, se conservamos o juízo, é para vós.'),
('acf','2co',5,14,'Porque o amor de Cristo nos constrange, julgando nós assim: que, se um morreu por todos, logo todos morreram.'),
('acf','2co',5,15,'E ele morreu por todos, para que os que vivem não vivam mais para si, mas para aquele que por eles morreu e ressuscitou.'),
('acf','2co',5,16,'Assim que daqui por diante a ninguém conhecemos segundo a carne, e, ainda que também tenhamos conhecido Cristo segundo a carne, contudo agora já não o conhecemos deste modo.'),
('acf','2co',5,17,'Assim que, se alguém está em Cristo, nova criatura é; as coisas velhas já passaram; eis que tudo se fez novo.'),
('acf','2co',5,18,'E tudo isto provém de Deus, que nos reconciliou consigo mesmo por Jesus Cristo, e nos deu o ministério da reconciliação;'),
('acf','2co',5,19,'Isto é, Deus estava em Cristo reconciliando consigo o mundo, não lhes imputando os seus pecados; e pôs em nós a palavra da reconciliação.'),
('acf','2co',5,20,'De sorte que somos embaixadores da parte de Cristo, como se Deus por nós rogasse. Rogamo-vos, pois, da parte de Cristo, que vos reconcilieis com Deus.'),
('acf','2co',5,21,'Àquele que não conheceu pecado, o fez pecado por nós; para que nele fôssemos feitos justiça de Deus.'),
('acf','2co',6,1,'E nós, cooperando também com ele, vos exortamos a que não recebais a graça de Deus em vão'),
('acf','2co',6,2,'(Porque diz:Ouvi-te em tempo aceitável e socorri-te no dia da salvação;eis aqui agora o tempo aceitável, eis aqui agora o dia da salvação).'),
('acf','2co',6,3,'Não dando nós escândalo em coisa alguma, para que o nosso ministério não seja censurado;'),
('acf','2co',6,4,'Antes, como ministros de Deus, tornando-nos recomendáveis em tudo; na muita paciência, nas aflições, nas necessidades, nas angústias,'),
('acf','2co',6,5,'Nos açoites, nas prisões, nos tumultos, nos trabalhos, nas vigílias, nos jejuns,'),
('acf','2co',6,6,'Na pureza, na ciência, na longanimidade, na benignidade, no Espírito Santo, no amor não fingido,'),
('acf','2co',6,7,'Na palavra da verdade, no poder de Deus, pelas armas da justiça, à direita e à esquerda,'),
('acf','2co',6,8,'Por honra e por desonra, por infâmia e por boa fama; como enganadores, e sendo verdadeiros;'),
('acf','2co',6,9,'Como desconhecidos, mas sendo bem conhecidos; como morrendo, e eis que vivemos; como castigados, e não mortos;'),
('acf','2co',6,10,'Como contristados, mas sempre alegres; como pobres, mas enriquecendo a muitos; como nada tendo, e possuindo tudo.'),
('acf','2co',6,11,'Ó coríntios, a nossa boca está aberta para vós, o nosso coração está dilatado.'),
('acf','2co',6,12,'Não estais estreitados em nós; mas estais estreitados nos vossos próprios afetos.'),
('acf','2co',6,13,'Ora, em recompensa disto, (falo como a filhos) dilatai-vos também vós.'),
('acf','2co',6,14,'Não vos prendais a um jugo desigual com os infiéis; porque, que sociedade tem a justiça com a injustiça? E que comunhão tem a luz com as trevas?'),
('acf','2co',6,15,'E que concórdia há entre Cristo e Belial? Ou que parte tem o fiel com o infiel?'),
('acf','2co',6,16,'E que consenso tem o templo de Deus com os ídolos? Porque vós sois o templo do Deus vivente, como Deus disse: Neles habitarei, e entre eles andarei; e eu serei o seu Deus e eles serão o meu povo.'),
('acf','2co',6,17,'Por isso saí do meio deles, e apartai-vos, diz o Senhor;E não toqueis nada imundo,E eu vos receberei;'),
('acf','2co',6,18,'E eu serei para vós Pai,E vós sereis para mim filhos e filhas, Diz o Senhor Todo-Poderoso.'),
('acf','2co',7,1,'Ora, amados, pois que temos tais promessas, purifiquemo-nos de toda a imundícia da carne e do espírito, aperfeiçoando a santificação no temor de Deus.'),
('acf','2co',7,2,'Recebei-nos em vossos corações; a ninguém agravamos, a ninguém corrompemos, de ninguém buscamos o nosso proveito.'),
('acf','2co',7,3,'Não digo isto para vossa condenação; pois já antes tinha dito que estais em nossos corações para juntamente morrer e viver.'),
('acf','2co',7,4,'Grande é a ousadia da minha fala para convosco, e grande a minha jactância a respeito de vós; estou cheio de consolação; transbordo de gozo em todas as nossas tribulações.'),
('acf','2co',7,5,'Porque, mesmo quando chegamos à macedônia, a nossa carne não teve repouso algum; antes em tudo fomos atribulados: por fora combates, temores por dentro.'),
('acf','2co',7,6,'Mas Deus, que consola os abatidos, nos consolou com a vinda de Tito.'),
('acf','2co',7,7,'E não somente com a sua vinda, mas também pela consolação com que foi consolado por vós, contando-nos as vossas saudades, o vosso choro, o vosso zelo por mim, de maneira que muito me regozijei.'),
('acf','2co',7,8,'Porquanto, ainda que vos contristei com a minha carta, não me arrependo, embora já me tivesse arrependido por ver que aquela carta vos contristou, ainda que por pouco tempo.'),
('acf','2co',7,9,'Agora folgo, não porque fostes contristados, mas porque fostes contristados para arrependimento; pois fostes contristados segundo Deus; de maneira que por nós não padecestes dano em coisa alguma.'),
('acf','2co',7,10,'Porque a tristeza segundo Deus opera arrependimento para a salvação, da qual ninguém se arrepende; mas a tristeza do mundo opera a morte.'),
('acf','2co',7,11,'Porque, quanto cuidado não produziu isto mesmo em vós que, segundo Deus, fostes contristados! que apologia, que indignação, que temor, que saudades, que zelo, que vingança! Em tudo mostrastes estar puros neste negócio.'),
('acf','2co',7,12,'Portanto, ainda que vos escrevi, não foi por causa do que fez o agravo, nem por causa do que sofreu o agravo, mas para que o vosso grande cuidado por nós fosse manifesto diante de Deus.'),
('acf','2co',7,13,'Por isso fomos consolados pela vossa consolação, e muito mais nos alegramos pela alegria de Tito, porque o seu espírito foi recreado por vós todos.'),
('acf','2co',7,14,'Porque, se nalguma coisa me gloriei de vós para com ele, não fiquei envergonhado; mas, como vos dissemos tudo com verdade, também a nossa glória para com Tito se achou verdadeira.'),
('acf','2co',7,15,'E o seu entranhável afeto para convosco é mais abundante, lembrando-se da obediência de vós todos, e de como o recebestes com temor e tremor.'),
('acf','2co',7,16,'Regozijo-me de em tudo poder confiar em vós.'),
('acf','2co',8,1,'Também, irmãos, vos fazemos conhecer a graça de Deus dada às igrejas da macedônia;'),
('acf','2co',8,2,'Como em muita prova de tribulação houve abundância do seu gozo, e como a sua profunda pobreza abundou em riquezas da sua generosidade.'),
('acf','2co',8,3,'Porque, segundo o seu poder (o que eu mesmo testifico) e ainda acima do seu poder, deram voluntariamente.'),
('acf','2co',8,4,'Pedindo-nos com muitos rogos que aceitássemos a graça e a comunicação deste serviço, que se fazia para com os santos.'),
('acf','2co',8,5,'E não somente fizeram como nós esperávamos, mas a si mesmos se deram primeiramente ao Senhor, e depois a nós, pela vontade de Deus.'),
('acf','2co',8,6,'De maneira que exortamos a Tito que, assim como antes tinha começado, assim também acabasse esta graça entre vós.'),
('acf','2co',8,7,'Portanto, assim como em tudo abundais em fé, e em palavra, e em ciência, e em toda a diligência, e em vosso amor para conosco, assim também abundeis nesta graça.'),
('acf','2co',8,8,'Não digo isto como quem manda, mas para provar, pela diligência dos outros, a sinceridade de vosso amor.'),
('acf','2co',8,9,'Porque já sabeis a graça de nosso Senhor Jesus Cristo que, sendo rico, por amor de vós se fez pobre; para que pela sua pobreza enriquecêsseis.'),
('acf','2co',8,10,'E nisto dou o meu parecer; pois isto convém a vós que, desde o ano passado, começastes; e não foi só praticar, mas também querer.'),
('acf','2co',8,11,'Agora, porém, completai também o já começado, para que, assim como houve a prontidão de vontade, haja também o cumprimento, segundo o que tendes.'),
('acf','2co',8,12,'Porque, se há prontidão de vontade, será aceita segundo o que qualquer tem, e não segundo o que não tem.'),
('acf','2co',8,13,'Mas, não digo isto para que os outros tenham alívio, e vós opressão,'),
('acf','2co',8,14,'Mas para igualdade; neste tempo presente, a vossa abundância supra a falta dos outros, para que também a sua abundância supra a vossa falta, e haja igualdade;'),
('acf','2co',8,15,'Como está escrito: O que muito colheu não teve demais; e o que pouco, não teve de menos.'),
('acf','2co',8,16,'Mas, graças a Deus, que pôs a mesma solicitude por vós no coração de Tito;'),
('acf','2co',8,17,'Pois aceitou a exortação, e muito diligente partiu voluntariamente para vós.'),
('acf','2co',8,18,'E com ele enviamos aquele irmão cujo louvor no evangelho está espalhado em todas as igrejas.'),
('acf','2co',8,19,'E não só isto, mas foi também escolhido pelas igrejas para companheiro da nossa viagem, nesta graça que por nós é ministrada para glória do mesmo Senhor, e prontidão do vosso ânimo;'),
('acf','2co',8,20,'Evitando isto, que alguém nos vitupere por esta abundância, que por nós é ministrada;'),
('acf','2co',8,21,'Pois zelamos do que é honesto, não só diante do Senhor, mas também diante dos homens.'),
('acf','2co',8,22,'Com eles enviamos também outro nosso irmão, o qual muitas vezes, e em muitas coisas, já experimentamos ser diligente, e agora muito mais diligente ainda pela muita confiança que em vós tem.'),
('acf','2co',8,23,'Quanto a Tito, é meu companheiro, e cooperador para convosco; quanto a nossos irmãos, são embaixadores das igrejas e glória de Cristo.'),
('acf','2co',8,24,'Portanto, mostrai para com eles, e perante a face das igrejas, a prova do vosso amor, e da nossa glória acerca de vós.'),
('acf','2co',9,1,'Quanto à administração que se faz a favor dos santos, não necessito escrever-vos;'),
('acf','2co',9,2,'Porque bem sei a prontidão do vosso ânimo, da qual me glorio de vós para com os macedônios; que a Acaia está pronta desde o ano passado; e o vosso zelo tem estimulado muitos.'),
('acf','2co',9,3,'Mas enviei estes irmãos, para que a nossa glória, acerca de vós, não seja vã nesta parte; para que (como já disse) possais estar prontos,'),
('acf','2co',9,4,'A fim de, se acaso os macedônios vierem comigo, e vos acharem desapercebidos, não nos envergonharmos nós (para não dizermos vós) deste firme fundamento de glória.'),
('acf','2co',9,5,'Portanto, tive por coisa necessária exortar estes irmãos, para que primeiro fossem ter convosco, e preparassem de antemão a vossa bênção, já antes anunciada, para que esteja pronta como bênção, e não como avareza.'),
('acf','2co',9,6,'E digo isto: Que o que semeia pouco, pouco também ceifará; e o que semeia em abundância, em abundância ceifará.'),
('acf','2co',9,7,'Cada um contribua segundo propôs no seu coração; não com tristeza, ou por necessidade; porque Deus ama ao que dá com alegria.'),
('acf','2co',9,8,'E Deus é poderoso para fazer abundar em vós toda a graça, a fim de que tendo sempre, em tudo, toda a suficiência, abundeis em toda a boa obra;'),
('acf','2co',9,9,'Conforme está escrito:Espalhou, deu aos pobres;a sua justiça permanece para sempre.'),
('acf','2co',9,10,'Ora, aquele que dá a semente ao que semeia, também vos dê pão para comer, e multiplique a vossa sementeira, e aumente os frutos da vossa justiça;'),
('acf','2co',9,11,'Para que em tudo enriqueçais para toda a beneficência, a qual faz que por nós se dêem graças a Deus.'),
('acf','2co',9,12,'Porque a administração deste serviço, não só supre as necessidades dos santos, mas também é abundante em muitas graças, que se dão a Deus.'),
('acf','2co',9,13,'Visto como, na prova desta administração, glorificam a Deus pela submissão, que confessais quanto ao evangelho de Cristo, e pela liberalidade de vossos dons para com eles, e para com todos;'),
('acf','2co',9,14,'E pela sua oração por vós, tendo de vós saudades, por causa da excelente graça de Deus que em vós há.'),
('acf','2co',9,15,'Graças a Deus, pois, pelo seu dom inefável.'),
('acf','2co',10,1,'Além disto, eu, Paulo, vos rogo, pela mansidão e benignidade de Cristo, eu que, na verdade, quando presente entre vós, sou humilde, mas ausente, ousado para convosco;'),
('acf','2co',10,2,'Rogo-vos, pois, que, quando estiver presente, não me veja obrigado a usar com confiança da ousadia que espero ter com alguns, que nos julgam, como se andássemos segundo a carne.'),
('acf','2co',10,3,'Porque, andando na carne, não militamos segundo a carne.'),
('acf','2co',10,4,'Porque as armas da nossa milícia não são carnais, mas sim poderosas em Deus para destruição das fortalezas;'),
('acf','2co',10,5,'Destruindo os conselhos, e toda a altivez que se levanta contra o conhecimento de Deus, e levando cativo todo o entendimento à obediência de Cristo;'),
('acf','2co',10,6,'E estando prontos para vingar toda a desobediência, quando for cumprida a vossa obediência.'),
('acf','2co',10,7,'Olhais para as coisas segundo a aparência? Se alguém confia de si mesmo que é de Cristo, pense outra vez isto consigo, que, assim como ele é de Cristo, também nós de Cristo somos.'),
('acf','2co',10,8,'Porque, ainda que eu me glorie mais alguma coisa do nosso poder, o qual o Senhor nos deu para edificação, e não para vossa destruição, não me envergonharei.'),
('acf','2co',10,9,'Para que não pareça como se quisera intimidar-vos por cartas.'),
('acf','2co',10,10,'Porque as suas cartas, dizem, são graves e fortes, mas a presença do corpo é fraca, e a palavra desprezível.'),
('acf','2co',10,11,'Pense o tal isto, que, quais somos na palavra por cartas, estando ausentes, tais seremos também por obra, estando presentes.'),
('acf','2co',10,12,'Porque não ousamos classificar-nos, ou comparar-nos com alguns, que se louvam a si mesmos; mas estes que se medem a si mesmos, e se comparam consigo mesmos, estão sem entendimento.'),
('acf','2co',10,13,'Porém, não nos gloriaremos fora da medida, mas conforme a reta medida que Deus nos deu, para chegarmos até vós;'),
('acf','2co',10,14,'Porque não nos estendemos além do que convém, como se não houvéssemos de chegar até vós, pois já chegamos também até vós no evangelho de Cristo,'),
('acf','2co',10,15,'Não nos gloriando fora da medida nos trabalhos alheios; antes tendo esperança de que, crescendo a vossa fé, seremos abundantemente engrandecidos entre vós, conforme a nossa regra,'),
('acf','2co',10,16,'Para anunciar o evangelho nos lugares que estão além de vós e não em campo de outrem, para não nos gloriarmos no que estava já preparado.'),
('acf','2co',10,17,'Aquele, porém, que se gloria, glorie-se no Senhor.'),
('acf','2co',10,18,'Porque não é aprovado quem a si mesmo se louva, mas, sim, aquele a quem o Senhor louva.'),
('acf','2co',11,1,'Quisera eu me suportásseis um pouco na minha loucura! Suportai-me, porém, ainda.'),
('acf','2co',11,2,'Porque estou zeloso de vós com zelo de Deus; porque vos tenho preparado para vos apresentar como uma virgem pura a um marido, a saber, a Cristo.'),
('acf','2co',11,3,'Mas temo que, assim como a serpente enganou Eva com a sua astúcia, assim também sejam de alguma sorte corrompidos os vossos sentidos, e se apartem da simplicidade que há em Cristo.'),
('acf','2co',11,4,'Porque, se alguém for pregar-vos outro Jesus que nós não temos pregado, ou se recebeis outro espírito que não recebestes, ou outro evangelho que não abraçastes, com razão o sofreríeis.'),
('acf','2co',11,5,'Porque penso que em nada fui inferior aos mais excelentes apóstolos.'),
('acf','2co',11,6,'E, se sou rude na palavra, não o sou contudo na ciência; mas já em todas as coisas nos temos feito conhecer totalmente entre vós.'),
('acf','2co',11,7,'Pequei, porventura, humilhando-me a mim mesmo, para que vós fôsseis exaltados, porque de graça vos anunciei o evangelho de Deus?'),
('acf','2co',11,8,'Outras igrejas despojei eu para vos servir, recebendo delas salário; e quando estava presente convosco, e tinha necessidade, a ninguém fui pesado.'),
('acf','2co',11,9,'Porque os irmãos que vieram da macedônia supriram a minha necessidade; e em tudo me guardei de vos ser pesado, e ainda me guardarei.'),
('acf','2co',11,10,'Como a verdade de Cristo está em mim, esta glória não me será impedida nas regiões da Acaia.'),
('acf','2co',11,11,'Por quê? Porque não vos amo? Deus o sabe.'),
('acf','2co',11,12,'Mas o que eu faço o farei, para cortar ocasião aos que buscam ocasião, a fim de que, naquilo em que se gloriam, sejam achados assim como nós.'),
('acf','2co',11,13,'Porque tais falsos apóstolos são obreiros fraudulentos, transfigurando-se em apóstolos de Cristo.'),
('acf','2co',11,14,'E não é maravilha, porque o próprio Satanás se transfigura em anjo de luz.'),
('acf','2co',11,15,'Não é muito, pois, que os seus ministros se transfigurem em ministros da justiça; o fim dos quais será conforme as suas obras.'),
('acf','2co',11,16,'Outra vez digo: Ninguém me julgue insensato, ou então recebei-me como insensato, para que também me glorie um pouco.'),
('acf','2co',11,17,'O que digo, não o digo segundo o Senhor, mas como por loucura, nesta confiança de gloriar-me.'),
('acf','2co',11,18,'Pois que muitos se gloriam segundo a carne, eu também me gloriarei.'),
('acf','2co',11,19,'Porque, sendo vós sensatos, de boa mente tolerais os insensatos.'),
('acf','2co',11,20,'Pois sois sofredores, se alguém vos põe em servidão, se alguém vos devora, se alguém vos apanha, se alguém se exalta, se alguém vos fere no rosto.'),
('acf','2co',11,21,'Envergonhado o digo, como se nós fôssemos fracos, mas no que qualquer tem ousadia (com insensatez falo) também eu tenho ousadia.'),
('acf','2co',11,22,'São hebreus? também eu. São israelitas? também eu. São descendência de Abraão? também eu.'),
('acf','2co',11,23,'São ministros de Cristo? (falo como fora de mim) eu ainda mais: em trabalhos, muito mais; em açoites, mais do que eles; em prisões, muito mais; em perigo de morte, muitas vezes.'),
('acf','2co',11,24,'Recebi dos judeus cinco quarentenas de açoites menos um.'),
('acf','2co',11,25,'Três vezes fui açoitado com varas, uma vez fui apedrejado, três vezes sofri naufrágio, uma noite e um dia passei no abismo;'),
('acf','2co',11,26,'Em viagens muitas vezes, em perigos de rios, em perigos de salteadores, em perigos dos da minha nação, em perigos dos gentios, em perigos na cidade, em perigos no deserto, em perigos no mar, em perigos entre os falsos irmãos;'),
('acf','2co',11,27,'Em trabalhos e fadiga, em vigílias muitas vezes, em fome e sede, em jejum muitas vezes, em frio e nudez.'),
('acf','2co',11,28,'Além das coisas exteriores, me oprime cada dia o cuidado de todas as igrejas.'),
('acf','2co',11,29,'Quem enfraquece, que eu também não enfraqueça? Quem se escandaliza, que eu me não abrase?'),
('acf','2co',11,30,'Se convém gloriar-me, gloriar-me-ei no que diz respeito à minha fraqueza.'),
('acf','2co',11,31,'O Deus e Pai de nosso Senhor Jesus Cristo, que é eternamente bendito, sabe que não minto.'),
('acf','2co',11,32,'Em Damasco, o que governava sob o rei Aretas pôs guardas às portas da cidade dos damascenos, para me prenderem.'),
('acf','2co',11,33,'E fui descido num cesto por uma janela da muralha; e assim escapei das suas mãos.'),
('acf','2co',12,1,'Em verdade que não convém gloriar-me; mas passarei às visões e revelações do Senhor.'),
('acf','2co',12,2,'Conheço um homem em Cristo que há catorze anos (se no corpo, não sei, se fora do corpo, não sei; Deus o sabe) foi arrebatado ao terceiro céu.'),
('acf','2co',12,3,'E sei que o tal homem (se no corpo, se fora do corpo, não sei; Deus o sabe)'),
('acf','2co',12,4,'Foi arrebatado ao paraíso; e ouviu palavras inefáveis, que ao homem não é lícito falar.'),
('acf','2co',12,5,'De alguém assim me gloriarei eu, mas de mim mesmo não me gloriarei, senão nas minhas fraquezas.'),
('acf','2co',12,6,'Porque, se quiser gloriar-me, não serei néscio, porque direi a verdade; mas deixo isto, para que ninguém cuide de mim mais do que em mim vê ou de mim ouve.'),
('acf','2co',12,7,'E, para que não me exaltasse pela excelência das revelações, foi-me dado um espinho na carne, a saber, um mensageiro de Satanás para me esbofetear, a fim de não me exaltar.'),
('acf','2co',12,8,'Acerca do qual três vezes orei ao Senhor para que se desviasse de mim.'),
('acf','2co',12,9,'E disse-me: A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza. De boa vontade, pois, me gloriarei nas minhas fraquezas, para que em mim habite o poder de Cristo.'),
('acf','2co',12,10,'Por isso sinto prazer nas fraquezas, nas injúrias, nas necessidades, nas perseguições, nas angústias por amor de Cristo. Porque quando estou fraco então sou forte.'),
('acf','2co',12,11,'Fui néscio em gloriar-me; vós me constrangestes. Eu devia ter sido louvado por vós, visto que em nada fui inferior aos mais excelentes apóstolos, ainda que nada sou.'),
('acf','2co',12,12,'Os sinais do meu apostolado foram manifestados entre vós com toda a paciência, por sinais, prodígios e maravilhas.'),
('acf','2co',12,13,'Pois, em que tendes vós sido inferiores às outras igrejas, a não ser que eu mesmo vos não fui pesado? Perdoai-me este agravo.'),
('acf','2co',12,14,'Eis aqui estou pronto para pela terceira vez ir ter convosco, e não vos serei pesado, pois que não busco o que é vosso, mas sim a vós: porque não devem os filhos entesourar para os pais, mas os pais para os filhos.'),
('acf','2co',12,15,'Eu de muito boa vontade gastarei, e me deixarei gastar pelas vossas almas, ainda que, amando-vos cada vez mais, seja menos amado.'),
('acf','2co',12,16,'Mas seja assim; eu não vos fui pesado mas, sendo astuto, vos tomei com dolo.'),
('acf','2co',12,17,'Porventura aproveitei-me de vós por algum daqueles que vos enviei?'),
('acf','2co',12,18,'Roguei a Tito, e enviei com ele um irmão. Porventura Tito se aproveitou de vós? Não andamos porventura no mesmo espírito, sobre as mesmas pisadas?'),
('acf','2co',12,19,'Cuidais que ainda nos desculpamos convosco? Falamos em Cristo perante Deus, e tudo isto, ó amados, para vossa edificação.'),
('acf','2co',12,20,'Porque receio que, quando chegar, não vos ache como eu quereria, e eu seja achado de vós como não quereríeis; que de alguma maneira haja pendências, invejas, iras, porfias, detrações, mexericos, orgulhos, tumultos;'),
('acf','2co',12,21,'Que, quando for outra vez, o meu Deus me humilhe para convosco, e chore por muitos daqueles que dantes pecaram, e não se arrependeram da imundícia, e fornicação, e desonestidade que cometeram.'),
('acf','2co',13,1,'É esta a terceira vez que vou ter convosco. Por boca de duas ou três testemunhas será confirmada toda a palavra.'),
('acf','2co',13,2,'Já anteriormente o disse, e segunda vez o digo como quando estava presente; mas agora, estando ausente, o escrevo aos que antes pecaram e a todos os mais, que, se outra vez for, não lhes perdoarei;'),
('acf','2co',13,3,'Visto que buscais uma prova de Cristo que fala em mim, o qual não é fraco para convosco, antes é poderoso entre vós.'),
('acf','2co',13,4,'Porque, ainda que foi crucificado por fraqueza, vive, contudo, pelo poder de Deus. Porque nós também somos fracos nele, mas viveremos com ele pelo poder de Deus em vós.'),
('acf','2co',13,5,'Examinai-vos a vós mesmos, se permaneceis na fé; provai-vos a vós mesmos. Ou não sabeis quanto a vós mesmos, que Jesus Cristo está em vós? Se não é que já estais reprovados.'),
('acf','2co',13,6,'Mas espero que entendereis que nós não somos reprovados.'),
('acf','2co',13,7,'Ora, eu rogo a Deus que não façais mal algum, não para que sejamos achados aprovados, mas para que vós façais o bem, embora nós sejamos como reprovados.'),
('acf','2co',13,8,'Porque nada podemos contra a verdade, senão pela verdade.'),
('acf','2co',13,9,'Porque nos regozijamos de estar fracos, quando vós estais fortes; e o que desejamos é a vossa perfeição.'),
('acf','2co',13,10,'Portanto, escrevo estas coisas estando ausente, para que, estando presente, não use de rigor, segundo o poder que o Senhor me deu para edificação, e não para destruição.'),
('acf','2co',13,11,'Quanto ao mais, irmãos, regozijai-vos, sede perfeitos, sede consolados, sede de um mesmo parecer, vivei em paz; e o Deus de amor e de paz será convosco.'),
('acf','2co',13,12,'Saudai-vos uns aos outros com ósculo santo.'),
('acf','2co',13,13,'Todos os santos vos saúdam.'),
('acf','2co',13,14,'A graça do Senhor Jesus Cristo, e o amor de Deus, e a comunhão do Espírito Santo seja com todos vós. Amém.')
